window.UNITS=[{"id":"P1U1","part":1,"n":1,"sec":{"read":{"t":"وَفَوْقَ كُلِّ ذي عِلْمٍ عَليمٌ","pg":5,"paras":["لا شَكَّ في أَنَّ كُلَّ مُتَأَمِّلٍ لِلْكَوْنِ يَتَعَجَّبُ مِنْ عَظيمِ قُدْرَةِ اللهِ -تَبارَكَ وَتَعالى- عَلى حُسْنِ خَلْقِهِ، وَتَدْبيرِهِ، فَفيهِ مِنَ الحَوادِثِ العَظيمَةِ، وَما اشْتَمَلَ عَلَيْهِ مِنْ بَديعِ صُنْعِهِ، عَزَّ وَجَلَّ، وَعَجائِبِ قُدْرَتِهِ، وَإِحاطَتِهِ بِكُلِّ شَيْءٍ في الآفاقِ، وَالأَنْفُسِ الدّالَّةِ عَلى وَحْدانِيَّتِهِ ما يُشيرُ إِلى قُدْرَةِ اللهِ في خَلْقِ هذا الكَوْنِ الواسِعِ، وَأَنَّ هذا الكَوْنَ بِمُعْجِزاتِهِ إِنَّما هُوَ دَليلٌ عَلى إِتْقانٍ، وَحِكْمَةٍ في الخَلْقِ، وَالإِبْداعِ.","وَالآياتُ الَّتي بَيْنَ أَيْدينا تَتَناوَلُ الحَديثَ عَنِ السّاعَةِ، وَاخْتِصاصِ عِلْمِ اللهِ بِها، وَعِلْمِهِ بِما تُكِنُّهُ الأَكْمامُ وَالأَرْحامُ، وَتَعْرِضُ مَشْهَدَ الكافِرينَ وَهُمْ يُسْأَلونَ عَمَّنِ اتَّخَذوهُمْ شُرَكاءَ للهِ، وَتَكْشِفُ حَقيقَةَ الإِنْسانِ الَّذي يَنْسى اللهَ في الرَّخاءِ، وَيَتَذَكَّرُهُ في الضَّرّاءِ، عَلى الرَّغْمِ مِنْ حِرْصِ الإِنْسانِ، إِلّا أَنَّهُ لا يَحْتاطُ لَها، فَيُكَذِّبُ، وَيَكْفُرُ، غَيْرَ آبِهٍ لِما يَعْقُبُ هذا التَّكْذيبَ مِنْ سوءِ المُنْقَلَبِ وَالمَآلِ. وَتَخْتِمُ السّورَةُ بِوَعْدِ اللهِ أَنْ يَكْشِفَ لِلنّاسِ مِنْ آياتِهِ الَّتي لا تَنْتَهي في الأَنْفُسِ، وَالآفاقِ؛ حَتّى يَتَبَيَّنوا، وَيَتَيَقَّنوا بِرَبِّهِمْ."],"voc":[["أكْمَامِها","جَمْعُ كُمٍّ، وَهِي أوْعِيَةُ الثِّمارِ."],["آذَنّاكَ","أسْمعناكَ، وَأعْلمْناكَ."],["مَحيصٍ","فَرارٍ عَنِ النّارِ."],["الشَّرُّ","الفَقْرُ، وَالمَرَضُ."],["فَيَئوسٌ قَنوطٌ","فَيائِسٌ مِنْ رَحْمَةِ اللهِ، وَمِنْ إِجابَةِ الدُّعاءِ."],["مِرْيَةٍ","شَكٍّ. ﴾"]],"img":[["p1-5.webp",5],["p1-6.webp",6],["p1-7.webp",7],["p1-8.webp",8]]},"grammar":{"t":"الإِعْرابُ وَالبِناءُ","pg":9,"pts":["الإعرابُ: تغيُّر العلامة في آخر الكلمة لتغيّر العوامل الدّاخلة عليها.","البناءُ: لزومُ آخر الكلمة حركةً واحدةً لا تتغيّر مهما تغيّرت العوامل.","الأسماء معربةٌ في الغالب، ومن المبنيّ منها: الضّمائر وأسماء الإشارة والأسماء الموصولة (عدا المثنّى) وأسماء الاستفهام.","الماضي والأمر مبنيّان، والمضارع معربٌ ما لم تتّصل به نون النّسوة أو نون التّوكيد المباشرة.","الحروف كلّها مبنيّة."],"img":[["p1-9.webp",9],["p1-10.webp",10]],"q":[["أيُّ الكلمات مبنيّة؟",["هذا","الكتابُ","عالمٌ","يعلمُ"],0,"اسم إشارة."],["الفعل المضارع في «الطّالباتُ يَدْرُسْنَ»:",["مبنيّ على السّكون","معرب مرفوع","معرب منصوب","مبنيّ على الفتح"],0,"اتّصلت به نون النّسوة."],["«فوقَ كلّ ذي علمٍ عليمٌ»: «ذي» معربة بـ:",["الياء لأنّها من الأسماء الخمسة","الكسرة","الفتحة","مبنيّة"],0,""]]},"balagha":{"t":"مُقَدِّمَةٌ في عِلْمِ البَلاغَةِ","pg":11,"pts":["البلاغةُ: مطابقةُ الكلام لمقتضى الحال مع فصاحته.","علومُها ثلاثة: المعاني، والبيان، والبديع."],"img":[["p1-11.webp",11]]},"imla":{"t":"الهَمْزَةُ المُتَوَسِّطَةُ (مُراجَعَةٌ)","pg":12,"pts":["الهمزة المتوسّطة تُكتب على حرفٍ يناسب أقوى الحركتين: حركتها وحركة ما قبلها.","ترتيب الحركات قوّةً: الكسرة (ياء/نبرة) ثمّ الضّمّة (واو) ثمّ الفتحة (ألف) ثمّ السّكون."],"img":[["p1-12.webp",12]]},"khatt":{"t":"الخَطُّ","pg":13,"pts":["خطّ النّسخ والرّقعة: كتابة عبارة من الدّرس."],"img":[["p1-13.webp",13]]},"taabir":{"t":"كِتابَةُ الفِقْرَةِ","pg":14,"pts":["كتابةُ الفقرة: الجملة المفتاحيّة، والجمل الدّاعمة، والجملة الختاميّة."],"img":[]}},"listen":"أهَمِّيَّةُ الوَحْدَةِ"},{"id":"P1U2","part":1,"n":2,"sec":{"read":{"t":"زَيْتٌ","pg":16,"paras":["مَحمود شقير كاتِبٌ فِلَسْطينِيٌّ مِنْ مَواليدِ جَبَلِ الْمُكَبِّرِ في القُدْسِ، عامَ ١٩٤١م. نَبَغَ في كِتابَةِ القِصَّةِ القَصيرَةِ، وَالْأُقْصوصَةِ، وَأَدَبِ السّيرَةِ، وَأَدَبِ الأَطْفالِ.","وَالقِصَّةُ الَّتي بَيْنَ أيْدينا، تَتَحَدَّثُ عَنْ هَمِّ الفِلَسْطينِيِّ في المُحافَظَةِ عَلى لُقْمَةِ عَيْشِهِ، وَارْتِباطِهِ بِأرْضِهِ وَزَيْتونِهِ، وَتُوَضِّحُ مُعاناةَ الأمِّ الفِلَسْطينِيَّةِ، وَخَوْفَها عَلى عائِلَتِها مِنْ غَطْرَسَةِ الاحْتِلالِ، وَانْتِهاكاتِهِ الجائِرَةِ.","هُما الآنَ في الطَّريقِ إِلى البَيْتِ، يَدُهُ عَلى قَلْبِهِ مِنْ حُلُمِها المُريعِ، وَيَدُها عَلى قَلْبِها مِنْ حُلُمِها، يَجْلِسانِ مُتَلاصِقَيْنِ في المَقْعَدِ المُجاوِرِ للسّائِقِ، في الشّاحِنَةِ الصَّغيرَةِ الَّتي تَحْمِلُ الآنَ عَشْرَ صَفائِحَ مِنَ الزَّيْتِ.","المَرْأةُ رَأتْ في حُلُمِها قَبْلَ لَيْلَتَيْنِ أنَّ الجُنودَ اعْتَرَضوا الشّاحِنَةَ في وَضَحِ النَّهارِ، أمَروا المَرْأةَ أنْ تَقِفَ بَعيداً دونَ حَراكٍ، وَأمَروا الرَّجُلَ أنْ يُنْزِلَ مِنَ الشّاحِنَةِ صَفائِحَ الزَّيْتِ كُلَّها، رَأتْ في حُلُمِها أنَّ الرَّجُلَ يَصْدَعُ بِما يُؤْمَرُ بِهِ، تَصْطَفُّ الصَّفائِحُ مَرْعوبَةً عَلى الرَّصيفِ، يَتَأمَّلُها الجُنودُ بِصَلَفٍ وَازْدِراءٍ، ثُمَّ يُطْلِقونَ عَلَيْها الرَّصاصَ مِنْ فُوَّهاتِ بَنادِقِهِمْ، يَنْدَلِقُ الزَّيْتُ أخْضَرَ يانِعاً مِنْ عَشَراتِ الثُّقوبِ الَّتي أحْدَثَها الرَّصاصُ في أجْسادِ الصَّفائِحِ، وَالمَرْأةُ تُحاوِلُ أنْ تَسُدَّ الثُّقوبَ بِقِطَعٍ مِنَ القُماشِ الَّذي لا تَدْري مِنْ أيْنَ تَكاثَرَ بَيْنَ يَدَيْها، وَحينَما لا تَنْفَعُ مُحاوَلاتُها تَهْجِمُ عَلى الجُنودِ، تَضْرِبُهُمْ بِقَبْضَةِ يَدِها، يُصَوِّبونَ بَنادِقَهُمْ صَوْبَ صَدْرِها، فَتَفيقُ مِنْ نَوْمِها، وَهِيَ في ذُعْرٍ شَديدٍ.","قالَ لَها الرَّجُلُ: اهْدَئي يا بِنْتَ الحَلالِ، هذِهِ أَضْغاثُ أحْلامٍ.","قالَتْ المَرْأةُ: كَيْفَ أهْدَأ وَأنا أراهُمْ كُلَّ يَوْمٍ يَنْعَفونَ الطَّحينَ عَلى البَلاطِ، وَيَدْلُقونَ الزَّيْتَ فَوْقَ الأغْطِيَةِ وَالوَسائِدِ في البُيوتِ؟! وَظَلَّ الرَّجُلُ يَرْوي لَها الحِكاياتِ المُسَلِّيَةَ إِلى ما بَعْدَ مُنْتَصَفِ اللَّيْلِ، حَتّى اسْتَكانَتْ وَنامَتْ مِنْ جَديدٍ. وَالرَّجُلُ لَمْ يَنَمْ حَتّى الصَّباحِ. أشْفَقَ عَلى المَرْأةِ، وَهُوَ يَتَأمَّلُها في نَوْمِها الْمُزَعْزَعِ. إِنَّهُ يَعْرِفُ قَلَقَها حينَما يَتَعَلَّقُ الأمْرُ بِمَؤونَةِ البَيْتِ، وَلُقْمَةِ الأوْلادِ.","بَعْدَ مُنْتَصَفِ اللَّيْلِ بِقَليلٍ جاءَ دَوْرُهُما. أخَذَتْ (ماكيناتُ) الحَديدِ في المَدينَةِ المُجاوِرَةِ تَهْرُسُ حَبّاتِ الزَّيْتونِ الخَضْراءَ، الَّتي تُشْبِهُ حَدَقاتِ العُيونِ. الرَّجُلُ يُتابِعُ الزَّيْتَ الَّذي يَتَدَفَّقُ في حِشْمَةٍ وَاعْتِدالٍ. وَالمَرْأةُ تَذْكُرُ اسْمَ اللّهِ في صَوْتٍ مَسْموعٍ؛ كَيْ تَحُلَّ البَرَكَةُ، وَيَتَضاعَفَ المَحْصولُ، ثُمَّ تَرْكُضُ في أرْجاءِ المَكانِ، تُهَيِّئُ مَزيداً مِنْ صَفائِحِ الحَديدِ، وَالرَّجُلُ يَرْمُقُها في إِعْجابٍ، وَيَقولُ: إنَّها كَنْزٌ ثَمينٌ، إِنَّها نَوّارَةُ الدّارِ.","هُما الآنَ في الطَّريقِ إِلى البَيْتِ، يَنْمو في صَدْرَيْهِما قَلَقٌ مُسْتَبِدٌّ، وَالسّائِقُ الَّذي قَدَّرَ حِرْصَهُما عَلى لُقْمَةِ الأوْلادِ، قالَ: إِنَّهُ يَعْرِفُ طَريقاً فَرْعِيّاً يُجَنِّبُهُما حاجِزَ الجَيْشِ، وَالمَرْأةُ ارْتاحَ بالُها لِلْفِكْرَةِ، وَالرَّجُلُ بَعْدَ تَرَدُّدٍ أشارَ إِلى السّائِقِ أنْ يَفْعَلَ ما يُريدُ.","هُما الآنَ عَلى مَرْمى حَجَرٍ مِنَ البَيْتِ، يَنْقُلانِ الصَّفائِحَ إِلى الدّاخِلِ، وَالمَرْأةُ تَسْكُبُ الزَّيْتَ في الصُّحونِ، تُحَضِّرُ خُبْزَ الطّابونِ وَالزَّعْتَرَ، يَأْكُلُ أوْلادُها وَأوْلادُ الجيرانِ، وَيَشْبَعونَ، وَالمَرْأةُ يَطْمَئِنُّ بالُها إِلى حينَ.","في مَساءِ اليَوْمِ التّالي، يُداهِمُ الجُنودُ البَيْتَ، تَتَصَدّى المَرْأةُ وَالأوْلادُ لَهُمْ، فيَخْتَلِطُ الطَّحينُ بِالدَّمِ وَالزَّيْتِ."],"voc":[["المُريعُ","المُفْزِعُ."],["يَصْدَعُ","يَجْهَرُ بِهِ دونَ خَوْفٍ."],["الصَّلَفُ","التَّكَبُّرُ وَالعَجْرَفَةُ."],["الازْدِراءُ","الاحْتِقارُ وَالإِهانَةُ."],["الصَّوْبُ","الجِهَةُ أوِ النّاحِيَةُ."],["الأضْغاثُ","ما كانَ مِنَ الأحْلامِ مُضْطَرِباً يَصْعُبُ تَأويلُهُ."],["اسْتَكانَتْ","خَضَعَتْ وَهَدَأتْ."],["الْمُزَعْزَعُ","المُضْطَرِبُ."],["الحَدَقَةُ","السَّوادُ المُسْتَديرُ وَسَطَ العَيْنِ."],["الحِشْمَةُ","الحَياءُ وَالرَّزانَةُ وَالوَقارُ."],["يَرْمُقُها","يَنْظُرُ إِلَيْها."]],"img":[["p1-16.webp",16],["p1-17.webp",17],["p1-18.webp",18],["p1-19.webp",19],["p1-20.webp",20]]},"poem":{"t":"عَلى جِذْعِ زَيْتونَةٍ","pg":21,"verses":[],"voc":[["تُشَرِّشُ","يُصْبِحُ لَها شُروشٌ، بِمَعْنى تَتَجَذَّرُ."],["لاكَ","عَلَكَ، ومَضَغَ."]],"img":[["p1-21.webp",21],["p1-22.webp",22],["p1-23.webp",23],["p1-24.webp",24]],"lines":["لِأَنّي لا أَحيكُ الصّوفْ","لِأَنّي كُلَّ يَوْمٍ عُرْضَةٌ لِأَوامِرِ التَّوْقيفْ","وَبَيْتي عُرْضَةٌ لِزِيارَةِ البوليسِ","لِلتَّفْتيشِ، وَالتَّنْظيفْ","لِأَنّي عاجِزٌ أَنْ أَشْتَري وَرَقاً","سَأَحْفِرُ كُلَّ ما أَلْقى","وَأَحْفِرُ كُلَّ أَسْراري","عَلى زَيْتونَةٍ","في ساحَةِ الدّارِ","*","سَأَحْفِرُ رَقْمَ كُلِّ قَسيمَةٍ","مِنْ أَرْضِنا سُلِبَتْ","وَمَوْقِعَ قَرْيَتي، وَحُدودَها،","وَبُيوتَ أَهْليها الَّتي نُسِفَتْ","وَأَشْجاري الَّتي اقْتُلِعَتْ","وَكُلَّ زُهَيْرَةٍ بَرِّيَّةٍ سُحِقَتْ","*","وأَسماءَ السُّجونِ","وَنَوْعَ كُلِّ (كَلَبْشَةٍ)","شُدَّتْ عَلى كَفّي","وَ (دوسيهاتِ) حُرّاسي","وَكُلَّ شَتيمَةٍ","صُبَّتْ عَلى راسي","*","وَأَحْفِرُ:","كَفرَ قاسِمِ لَسْتُ أنْساها","وَأَحْفِرُ:","دَيْرَ ياسينٍ تُشَرِّشُ فِيَّ ذِكْراها","وَأَحْفِرُ:","قَدْ وَصَلْنا قِمَّةَ المَأْساةِ","لاكَتْنا وَلُكْناها،","وَلكِنّا... وَصَلْناها!","*","لِكَيْ أَذكُرْ، وَكَيْ تذْكُرْ","سَأَبْقى قائِماً أَحْفِرْ","جَميعَ فُصولِ مَأْساتي","وَكُلَّ مَراحِلِ النَّكْبَةْ","مِنَ الحَبَّةْ","إِلى القُبَّةْ","عَلى زَيْتونَةٍ","في ساحَةِ الدّارِ"]},"grammar":{"t":"اللّازِمُ وَالمُتَعَدّي","pg":25,"pts":["الفعلُ اللّازم: ما يكتفي بفاعله ولا يحتاج إلى مفعولٍ به (جلسَ الفلّاحُ).","الفعلُ المتعدّي: ما لا يكتفي بفاعله بل يحتاج إلى مفعولٍ به (قطفَ الفلّاحُ الزّيتونَ).","من المتعدّي ما ينصب مفعولًا واحدًا، ومنه ما ينصب مفعولين (أعطى، منح، ظنّ)."],"img":[["p1-25.webp",25],["p1-26.webp",26]],"q":[["الفعل «نامَ» في «نامَ الطّفلُ»:",["لازم","متعدٍّ لمفعول","متعدٍّ لمفعولين","ناقص"],0,""],["الفعل «منحَ» في «منحَ المعلّمُ الطّالبَ جائزةً»:",["متعدٍّ لمفعولين","لازم","متعدٍّ لمفعول","ناقص"],0,""],["المفعول به في «عصرَ الفلّاحُ الزّيتونَ»:",["الزّيتونَ","الفلّاحُ","عصرَ","لا يوجد"],0,""]]},"balagha":{"t":"عِلْمُ البَديعِ (الجِناسُ)","pg":28,"pts":["الجناسُ: أن تتشابه كلمتان في اللّفظ وتختلفا في المعنى.","الجناسُ التّامّ: تطابق اللّفظين في نوع الحروف وعددها وترتيبها وحركاتها.","الجناسُ النّاقص: اختلافهما في واحدٍ من هذه الأمور."],"img":[["p1-28.webp",28]]},"imla":{"t":"حالاتٌ خاصَّةٌ في كِتابَةِ الهَمْزَةِ المُتَوَسِّطَةِ","pg":30,"pts":["إذا جاءت الهمزة المتوسّطة مفتوحةً بعد ألف كُتبت على السّطر (عباءة).","إذا جاءت مفتوحةً بعد واوٍ ساكنة كُتبت على السّطر (مروءة).","إذا جاءت مفتوحةً أو مضمومةً بعد ياءٍ ساكنة كُتبت على نبرة (هيئة، بيئة)."],"img":[["p1-30.webp",30]]},"khatt":{"t":"الخَطُّ","pg":32,"pts":["كتابة بيتٍ من القصيدة بخطّ النّسخ."],"img":[["p1-32.webp",32]]},"taabir":{"t":"تَحْليلُ الفِقْرَةِ","pg":32,"pts":["تحليلُ الفقرة إلى عناصرها."],"img":[["p1-32.webp",32]]}},"listen":"الزَّيْتونُ غِذاءٌ وَهُوِيَّةٌ"},{"id":"P1U3","part":1,"n":3,"sec":{"read":{"t":"صِناعَةُ النَّجاحِ وَتَجاوُزُ الفَشَلِ","pg":35,"paras":["نصر الدّين الزّبير كاتبٌ سودانِيٌّ، تَناولَ في هذا المقالِ رسالةً تربويةً تتعلّقُ بهاجسِ التفوّقِ الدراسيِّ الّذي يؤرِّقُ الوالدينِ منذُ دخولِ ابنهِما المدرسةَ، ويُبرِزُ حجمَ الضّغوطاتِ الّتي تقعُ على الطالبِ منَ الوالدينِ؛ لتلبيةِ رغبتِهما بتفوّقِهِ، وما يترتّبُ على تدنّي التّحصيلِ من حُكمٍ قاسٍ عليهِ عندما يُتَّهَمُ بالغباءِ والفشلِ، ويُقَدِّمُ الكاتبُ مفارقةً من خلالِ استشهادهِ بقصّةِ نجاحِ أديسون الذي طردتهُ المدرسةُ؛ بحجةِ الغباءِ، لكنّهُ تحوَّلَ بفضلِ توجيهاتِ أمِّهِ إلى عالمٍ عظيمٍ ملأتِ اختراعاتُهُ الدُّنيا.","عِنْدَما عادَ (توماس أديسون)، وَهُوَ طِفْلٌ صَغيرٌ إِلى بَيْتِهِ، قالَ لِأمِّهِ: هذِهِ رِسالَةٌ لَكِ مِنْ إِدارَةِ المَدْرَسَةِ.","غَمَرَتْ بَريقَ عَيْنَيْها الدُّموعُ، وَهِيَ تَقْرَأ لَهُ: \"ابْنُكِ عَبْقَرِيٌّ، وَالمَدْرَسَةُ صَغيرَةٌ عَلى قُدْراتِهِ؛ عَلَيْكِ أنْ تُعَلِّميهِ في البَيْتِ\".","مَرَّتِ السَّنَواتُ، وَتُوُفِّيَتْ أمُّ أديسون، الَّذي تَحَوَّلَ إِلى أعْظَمِ مُخْتَرِعٍ في التّاريخِ البَشَرِيِّ. وَفي أحَدِ الأيّامِ، وَهُوَ يَبْحَثُ في خِزانَةِ والِدَتِهِ، وَجَدَ رِسالَةً كانَ نَصُّها:\"ابْنُكِ غَبِيٌّ جِدّاً، فَمِنْ صَباحِ الغَدِ لَنْ نُدْخِلَهُ المَدْرَسَةَ\". بَكى أديسون لِساعاتٍ طَويلَةٍ، ثُمَّ كَتَبَ في دَفْتَرِ مُذَكِّراتِهِ:","\"أديسون كانَ طِفْلاً غَبِيّاً، وَلكِنْ بِفَضْلِ وَالِدَتِهِ الرّائِعَةِ تَحَوَّلَ إِلى عَبْقَرِيٍّ. كَثيرٌ مِنَ الفاشِلينَ هُمْ أشْخاصٌ لَمْ يُدْرِكوا قُرْبَهُمْ مِنَ النَّجاحِ عِنْدَما قَرَّروا الانْسِحابَ\".","يُعَدُّ النَّجاحُ وَالتَّفَوُّقُ مِنَ الأوْلَوِيّاتِ الَّتي يُفَكِّرُ فيها الوالِدانِ عِنْدَ دُخولِ ابْنِهِما المَدْرَسَةَ، فَمُنْذُ اليوْمِ الأوَّلِ لالْتِحاقِهِ بِالمَدْرَسَةِ، تَبْدَأُ الأحْلامُ، وَتَتَعَدَّدُ التَّوْجيهاتُ، وَتَكْثُرُ قائِمَةُ الطَّلَباتِ مِنَ الأهْلِ: لا تُكْثِرْ مِنْ مُشاهَدَةِ التِّلْفازِ، لا تَسْهَرْ طَويلاً، لا تَتَأخَّرْ في اللَّعِبِ مَعَ رِفاقِكَ، افْتَحْ كُتُبَكَ، وَادْرُسْ، ماذا تَعَلَّمْتَ في المَدْرَسَةِ اليَوْمَ؟ ما واجِباتُكَ المَدْرَسيَّةُ ليَوْمِ غَدٍ؟... وَكَأنَّ كُلَّ ما يَتَرَتَّبُ عَلى الطّالِبِ فِعْلُهُ هُوَ الدِّراسَةُ وَالمُذاكَرَةُ، وَعَلَيْهِ أنْ يَنْسى كُلَّ ما عَدا ذَلِكَ خِلالَ العامِ الدِّراسِيِّ، ويُرَحِّلَ اهْتِماماتِهِ كُلَّها وَهِواياتِهِ الأخْرى إِلى فَصْلِ الصَّيْفِ، وَما عَلى هذا الطّالِبِ المِسْكينِ سِوى الاجْتِهادِ مِنْ أجْلِ تَحْصيلِ التَّفَوُّقِ الدِّراسِيِّ.","وَلَكُمْ أَنْ تَتَخَيَّلوا مِقْدارَ خَيْبَةِ الأَمَلِ الَّتي يُصابُ بِها الوالِدانِ، حينَ يَعْلَمانِ أنَّ فِلْذَةَ كَبِدِهِما ضَعيفُ التَّحْصيلِ، عِنْدَها تَكونُ الكارِثَةُ في البَيْتِ، وَتَبْدَأ المُحاولاتُ الحَثيثَةُ لِحَشْوِ دِماغِ هَذا المِسْكينِ بِالمَعْلوماتِ عَلى اخْتِلافِها، وَيُصْبِحُ البَيْتُ مَحَجّاً لِلْمُدَرِّسينَ الخُصوصِيّينَ، وَتَتَضافَرُ جُهودُ الوالِدَيْنِ وَمَنْ حَوْلَهُما مِنْ أجْلِ النُّهوضِ بِمُسْتَوى هذا الطّالِبِ، فَتوضَعُ خُطَطٌ وَدِراساتٌ تَبوءُ كُلُّها بِالفَشَلِ، بَعْدَها يوضَعُ هذا الطّالِبُ عَلى قائِمَةِ مُتَدَنّي التَّحْصيلِ، وَتَعْمى الأبْصارُ عَنْ مَواهِبِهِ الأخْرى، ويُطْرَدُ الوَلَدُ مِنْ جَنَّةِ أبَوَيْهِ، ويُحْرَمُ ثِمارَ عَطْفِهِما، وَيَنْسى الوالِدانِ أنْ يَتَساءَلا: كَيْفَ لَهُما أنْ يَسْتَنْهِضا الطّاقاتِ الإيجابِيَّةَ الأُخْرى الكامِنَةَ في ابْنِهِما (الفاشِلِ دِراسِيّاً)؟ وَكَيْفَ لَهُما أَنْ يُعَزِّزا مُبادَراتِ الخَلْقِ والإِبْداعِ فيهِ؟","هذِهِ والِدَةُ المُخْتَرِعِ العَظيمِ (أديسون) لَمْ تَبْكِ نائِحَةً عَلَيْهِ، عِنْدَما وَصَلَتْها رِسالَةُ المَدْرَسَةِ الَّتي تَتَّهِمُ ابْنَها بِالغَباءِ وَالبَلادَةِ، بَلْ شَدَّتْ عَلى يَدَيْهِ، وَآمَنَتْ بِقُدْراتِهِ الإِبْداعِيَّةِ الأخْرى بِكُلِّ مَحَبَّةٍ وَحَنانٍ؛ وَهَكَذا تَحَوَّلَ هذا التَّبَلُّدُ الدِّراسِيُّ إِلى عَبْقَرِيَّةٍ فَذَّةٍ، تَبَدَّتْ في الاخْتِراعاتِ الَّتي تَجاوَزَتْ ألْفَ اخْتِراعٍ، يَتَصَدَّرُها اخْتِراعُ المِصْباحِ الكَهْرُبائِيِّ، الَّذي أَتَتْ فِكْرَتُهُ عَقِبَ مَرَضِ والِدَتِهِ الشَّديدِ، وَحاجَةِ الطَّبيبِ إِلى الضَّوْءِ في أَثْناءِ عِلاجِها. وَهكَذا، مِنْ قَلْبِ المِحْنَةِ وَالمَأْساةِ، يَعْمَلُ العَقْلُ الجامِحُ عَلى تَمْزيقِ المَعاييرِ القائِمَةِ، وَيَبْدَأ بِالتَّفْكيرِ لِإيجادِ حَلٍّ لِمَأساةٍ قَدْ تَكونُ شَخْصِيَّةً، لكِنَّها في المُقابِلِ حاجَةُ البَشَرِيَّةِ كُلِّها.","كانَ (أديسون) قَبْلَ التَوَصُّلِ إِلى اخْتِراعِ المِصْباحِ يَعُدُّ التَّجارِبَ الفاشِلَةَ الَّتي فاقَتْ (١٨٠٠) تَجْرِبَةٍ غَيْرَ مُكْتَمِلَةِ النَّجاحِ، تَعَلَّمَ مِنْها قَواعِدَ ثابِتَةً يَبْني عَلَيْها تَجْرِبَةً لاحِقَةً، فالفَشلُ فُرْصَةٌ وَتَجْرِبَةٌ، وَهُوَ هَزيمَةٌ مُؤَقَّتَةٌ تَقودُكَ إِلى فُرَصِ النَّجاحِ.","لَعَلَّ كُلَّ والِدَةٍ تَلْمَسُ في طِفْلِها الفَشَلَ الدِّراسِيَّ، تَجِدُ عَزاءَها في قِصَّةِ (أديسون)؛ لِتُدْرِكَ أنَّ هُناكَ طاقاتٍ إِبْداعِيَّةً كامِنَةً في كُلِّ طِفْلٍ، وَلكِنْ لا بُدَّ مِنْ إِعْطائِهِ الدّافِعَ اللَّازِمَ، وَالثِّقَةَ الكَبيرَةَ لإِخْراجِها، فَلا تُرْغِمُ طِفْلَها عَلى الانْسِحابِ مِنْ مَسيرَةِ التَّقَدُّمِ في الحَياةِ؛ فَالنَّجاحُ قَدْ يَنْتَظِرُهُ في مَحَطّاتٍ أخَرَ.","(نصر الدّين الزّبير، بتصرّف)"],"voc":[["العَبْقَرُ","مَوْضِعٌ تَزْعُمُ العَرَب أنَّهُ مِنْ أرْضِ الجِنِّ، وَقَدْ نَسَبوا إِلَيْهِ كُلَّ شَيْءٍ تَعَجَّبوا مِنْ حِذْقِهِ، أوْ جَوْدَةِ صَنْعَتِهِ"],["وَقُوَّتِهِ، فَقالوا","عَبْقَرِيٌّ."],["يُرَحِّلُ","يُؤَجِّلُ وَيُؤَخِّرُ."],["الفِلْذَة","القِطْعَةُ مِنَ الكَبِدِ. وَتَأْتي أفْلاذُ الأكْبادِ للدِّلالَةِ عَلى الأبْناءِ."],["تَبوءُ","تَرْجِعُ."],["يُعزِّزُ","يُقَوّي."],["البَلادَةُ","ضِدُّ الذَّكاءِ."],["الجامِحُ","المُنْدَفِعُ."],["المَعاييرُ","مُفْرَدُها المِعْيارُ، وَهُوَ المِكْيالُ أوِ الميزانُ، والمَقْصودُ هُنا الأسُسُ والقَواعِدُ."]],"img":[["p1-35.webp",35],["p1-36.webp",36],["p1-37.webp",37],["p1-38.webp",38],["p1-39.webp",39]]},"grammar":{"t":"صُوَرُ الفاعِلِ وَالمَفْعولِ بِهِ","pg":40,"pts":["الفاعل: اسمٌ مرفوع أُسند إليه فعلٌ مبنيٌّ للمعلوم.","يأتي اسمًا ظاهرًا (نجح الطّالبُ)، أو ضميرًا متّصلًا (نجحْتُ)، أو ضميرًا مستترًا (اجتهِدْ: أنت).","المفعول به يأتي اسمًا ظاهرًا أو ضميرًا متّصلًا (كافأني المعلّمُ) أو منفصلًا (إيّاك نعبد)."],"img":[["p1-40.webp",40],["p1-41.webp",41]],"q":[["الفاعل في «اجتهِدْ في دروسك»:",["ضمير مستتر تقديره أنت","دروسك","الكاف","في"],0,""],["المفعول به في «شجّعَنا المدرّبُ»:",["نا","المدرّب","شجّع","لا يوجد"],0,""],["«إيّاكَ نستعين»: «إيّا»:",["ضمير منفصل في محلّ نصب مفعول به مقدّم","فاعل","مبتدأ","حرف"],0,""]]},"imla":{"t":"تَدْريباتٌ عَلى الهَمْزَةِ المُتَوَسِّطَةِ","pg":43,"pts":["تدريباتٌ على الهمزة المتوسّطة."],"img":[["p1-43.webp",43]]},"khatt":{"t":"الخَطُّ","pg":43,"pts":["كتابة حكمة بخطّ الرّقعة."],"img":[["p1-43.webp",43]]},"taabir":{"t":"تَطْبيقٌ عَمَلِيٌّ عَلى تَحْليلِ الفِقْرَةِ","pg":44,"pts":["تطبيقٌ على تحليل الفقرة."],"img":[]}},"listen":"الذَّكاءُ"},{"id":"P1U4","part":1,"n":4,"sec":{"read":{"t":"رِسالَةٌ مِنْ طِفْلَةٍ فِلَسْطينِيَّةٍ إِلى أطْفالِ العالَمِ","pg":46,"paras":["أحِبّائي أطْفالَ العالَمِ،","السَّلامُ عَلَيْكُم ورَحْمَةُ اللّهِ وبَرَكاتُهُ، وبَعْدُ:","أكْتُبُ إلَيْكُمْ أحِبّائي، أطْفالَ العالَمِ، مِنَ القُدْسِ الشَّريفِ، عاصِمَةِ الحُلُمِ الفِلَسْطينِيِّ، وَأنْتُم تَعْدونَ في الحُقولِ، تُسابِقونَ الفَراشَ، وتُعانِقونَ الجَمالَ، وتَحْمِلونَ راياتِ بِلادِكُم خَفّاقَةً عَالِيَةً.","طِفْلَةٌ فِلَسْطينِيَّةٌ أنا،","لا أعْرِفُ في السِّياسَةِ شَيْئاً، ولَكنّي أعْرِفُ أنّي بِنْتُ فِلَسْطينَ وهذا الشَّعْبِ، وفي شَراييني سَرى الأمَلُ الفِلَسْطينِيُّ بِالدَّوْلَةِ الفِلَسْطينِيَّةِ، وفي وَعْيي اسْتَقرَّ حُلُمٌ بِغَدٍ فِلَسْطينِيٍّ مُشْرِقٍ: لا قَتْلَ فيهِ وَلا دَمارَ، وَلا حُزْنَ فيه وَلا بُكاءَ. طِفْلَةٌ فِلَسْطينِيَّةٌ أنا،","مُنْذُ وُلِدْتُ اغْتالوا طُفولَتي، ومَزَّقوا لُعْبَتي؛ فَخَبَّأْتُها في قَلبي، منذُ وُلِدْتُ وأزيزُ الرَّصاصِ يَخْتَرقُ أذُنَيَّ، ويُجَلِّلُ السَّوادُ الأشياءَ كُلَّها حَوْلي، فَأرى عُيوناً باكِيَةً: فَهذِهِ أمُّ شَهيدٍ، وَهذِهِ بنْتُ أسيرٍ، وَهذِهِ أخْتُ مَفْقودٍ، وَهذا طِفْلٌ شَوَّهَتْهُ قُنْبُلةٌ اغْتالَتْ لُعْبَتَهُ، وَانْتَزَعَتْ مَعَها عَيْنَهُ وَقَلْبَهُ وَفَرَحَهُ، فَعَرَفَ الحُزْنُ إِلى قَلْبِهِ طَريقاً لَمْ يَعْرِفْها الفَرَحُ أبَداً. وَهذِهِ امْرَأةٌ شابَّةٌ فَقَدَتْ زَوْجَها؛ فَحَفَرَ الحُزْنُ في وَجْنَتَيْها أخاديدَ اليَأْسِ بِأظافِرَ لا لَحْمَ عَلَيْها.","مُنْذُ وُلِدْتُ وَأنا أرى حُقولَنا مُسْتَباحَةً، وَأزِقَّتَنا مُغْلَقَةً، يَمْشي فيها المَوْتُ وَالعَسْكَرُ، وَأرى رُكامَ مَنازِلَ مُهَدَّمَةٍ، تَناثَرَتْ حِجارَتُها في الأرْجاءِ، وَما تَزالُ تَئِنُّ تَحْتَها ذِكْرَياتُ الأطْفالِ، وَأحْلامُ العَصافيرِ.","كُنْتُ أتَمَنّى أنْ أرى البَسْمَةَ تَعْلو الشِّفاهَ، وَأنْ يُقْتَلَعَ الحُزْنُ مِنَ القُلوبِ، فَتُشْرِقَ الوُجوهُ، أحْلُمُ أنْ أعيشَ أنا وَرِفاقي في أمْنٍ وَسَلامٍ، كَكُلِّ البَشَرِ، لَنا دَوْلَةٌ وَحُدودٌ، وَرايَةٌ وَكَرامَةٌ.","كُنْتُ أحْلُمُ أنْ يَكونَ لي مَدْرَسَةٌ لا أخافُ أنْ يَدوسَني فيها حِذاءُ جُنْدِيٍّ غاصِبٍ، أوْ تَنْقُلَ لَهُ جُدْرانُ المَدْرَسَةِ أحْلامي، كُنْتُ أحلُمُ أنْ يَسْتَجيبَ القَلَمُ لِأمانِيِّ القَلْبِ، فَيَرسُمَ شَمْساً تُشْرِقُ، وَفَلّاحاً يَزْرَعُ، وَطِفْلاً يُمسِكُ بِيَدِ طِفْلَةٍ يُلَوِّحُ بِها، وَفي الأخْرى تَحْمِلُ كُرّاسَةً وَقَلَماً، وَقَلْباً يَحْمِلُ الحُبَّ لِأطْفالِ الدُّنْيا. طِفْلَةٌ فِلَسْطينِيَّةٌ أنا،","لا أعْرِفُ في السِّياسَةِ شَيْئاً، لِماذا ذَبَحوا طُفولَتي أمامي، وَاغْتالوا الوَرْدَ في الحُقولِ؟ لِماذا قَتَلوا الفَراشاتِ في حَدائِقِنا، زَعوا الطُّيورَ؟ لِماذا حَجَبوا الشَّمْسَ، وَنَثَروا العَتَمَةَ، وَسَدّواْوَأف الدُّروبَ؟","ولَكِنْ في أعْماقِ قَلْبي اسْتَقَرَّ حُلُمُ فِلَسْطينَ؛ أنْ أعيشَ في هُدوءٍ وَسَلامٍ. أحْلُمُ بِأنْ تَخْفِقَ راياتُ بِلادي في أكُفِّ الأطْفالِ، فَرَحاً وَحُرِّيَّةً، أحْلُمُ بِأنْ تُشْرِقَ شَمْسٌ جَديدَةٌ، تَحْمِلُ الحُبَّ، تَحْمِلُ البَسْمةَ، تَحْمِلُ غَدَ أطْفالِ فِلَسْطينَ."],"voc":[["عَدا","جَرى."],["الرّايَةُ","العَلَمُ."],["الخَفّاقُ","المُرَفْرِفُ."],["سَرى الأمَلُ","انْتَشَرَ."],["الاغْتيالُ","القَتْلُ عَلى غَفْلَةٍ."],["أزيزُ الرَّصاصِ","صَوْتُهُ."],["جَلَّلَ","غَطّى."],["الوَجْنَةُ","الخَدُّ."],["الأخْدودُ","الشَّقُّ المُسْتَطيلُ في الأرْضِ."],["اسْتَباحَ الجُنْدُ المَدينَةَ","اسْتَوْلَوْا عَلَيْها حَرْباً، وعَدّوا كُلَّ شَيْءٍ فيها مُباحاً لَهُمْ."]],"img":[["p1-46.webp",46],["p1-47.webp",47],["p1-48.webp",48],["p1-49.webp",49]]},"poem":{"t":"يا قُدْسُ","pg":50,"verses":[],"voc":[["يَسوعُ","السَّيِّدُ المَسيح ُ، عيسى عَلَيْهِ السَّلامُ."],["تَفوحُ","تَنْتَشِرُ رائِحَتُها."],["البَتُولُ مِنَ النِّساءِ","المُنْقَطِعَةُ عَنِ الرِّجالِ لا أرَبَ لَها فيهِمْ؛ وَبِها سُمِّيَتْ مَرْيَمُ أمُّ المَسيحِ، عَلى نَبِيِّنا، وَعَلَيْها الصَّلاةُ وَالسَّلامُ."],["الواحَةُ","البُقْعَةُ الخَضْراءُ في أرْضٍ قاحِلَةٍ. 51ُ"]],"img":[["p1-50.webp",50],["p1-51.webp",51],["p1-52.webp",52],["p1-53.webp",53]],"lines":["بَكَيْتُ.. حَتّى انْتَهَتِ الدُّموعْ","صَلَّيْتُ.. حَتّى ذابَتِ الشُّموعْ","رَكَعْتُ.. حَتّى مَلَّني الرُّكوعْ","سَأَلْتُ عَنْ مُحَمَّدٍ","فيكِ، وَعَنْ يَسوعْ","يا قُدْسُ.. يا مَدينَةً تَفوحُ أَنْبِياءْ","يا أَقْصَرَ الدُّروبِ بَيْنَ الأَرْضِ وَالسَّماءْ","*","يا قُدْسُ.. يا مَنارَةَ الشَّرائِعْ","يا طِفْلَةً جَميلَةً مَحْروقَةَ الأَصابِعْ","حَزينَةٌ عَيْناكِ يا مَدينَةَ البَتولْ","يا واحَةً ظَليلَةً مَرَّ بِها الرَّسولْ","حَزينَةٌ حِجارَةُ الشَّوارِعْ","حَزينَةٌ مآذِنُ الجَوامِعْ","يا قُدْسُ.. يا مَدينَةً تَلْتَفُّ بِالسَّوادْ","مَنْ يَقرَعُ الأَجْراسَ في كَنيسَةِ القيامَةْ؟","صَبيحَةَ الآحادْ","مَنْ يَحْمِلُ الأَلْعابَ لِلأَوْلادْ","في لَيْلَةِ الميلادْ","*","يا قُدْسُ.. يا مَدينَةَ الأَحْزانْ","يا دَمْعَةً كَبيرَةً تَجولُ في الأَجْفانْ","مَنْ يوقِفُ العُدْوانْ","عَلَيْكِ، يا لُؤْلُؤَةَ الأَدْيانْ؟","مَنْ يَغْسِلُ الدِّماءَ عَنْ حِجارَةِ الجُدْرانْ؟","مَنْ يُنقِذُ الإنْجيلْ؟","مَنْ يُنْقِذُ القُرْآنْ؟...","مَنْ يُنْقِذُ الإِنْسانْ؟","*","يا قُدْسُ.. يا مَدينَتي","يا قُدْسُ.. يا حَبيبَتي","غَداً.. غَداً.. سَيُزْهِرُ اللَّيْمونْ","وَتَفْرَحُ السَّنابِلُ الخَضْراءُ والغُصونْ","وَتَضْحَكُ العُيونْ","وَتَرْجِعُ الحَمائِمُ المُهاجِرَةْ","إِلى السُّقوفِ الطّاهِرَةْ","وَيَرْجِعُ الأَطْفالُ يَلْعَبونْ","وَيَلْتَقي الآباءُ والبَنونْ","عَلى رُباكِ الزّاهِرَةْ..","يا بَلَدي.. يا بَلَدَ السَّلامِ والزَّيْتونْ"]},"grammar":{"t":"أحْوالُ بِناءِ الفِعْلِ الماضي","pg":54,"pts":["يُبنى الماضي على الفتح إذا لم يتّصل به شيء، أو اتّصلت به تاء التّأنيث السّاكنة، أو ألف الاثنين، أو ضمير نصب (الهاء، الكاف، الياء، نا المفعولين).","يُبنى على الضّمّ إذا اتّصلت به واو الجماعة.","يُبنى على السّكون إذا اتّصل به ضمير رفع متحرّك (التّاء، نا الفاعلين، نون النّسوة)."],"img":[["p1-54.webp",54],["p1-55.webp",55]],"q":[["«كتبَتْ الطّفلةُ رسالتَها»: يُبنى الفعل على:",["الفتح","السّكون","الضّمّ","حذف النّون"],0,""],["«كتبْنا للعالم»: يُبنى على:",["السّكون","الفتح","الضّمّ","الكسر"],0,""],["«الأطفالُ رسموا»: يُبنى على:",["الضّمّ","الفتح","السّكون","حذف النّون"],0,""]]},"imla":{"t":"ألِفُ تَنْوينِ النَّصْبِ بَعْدَ الهَمْزَةِ المُتَطَرِّفَةِ","pg":57,"pts":["تُكتب ألف تنوين النّصب بعد الهمزة المتطرّفة المسبوقة بألف دون ألف (سماءً)، وبعد الهمزة على السّطر المسبوقة بحرفٍ يوصل بما بعده تُرسم على نبرة مع ألف (شيئًا، عبئًا)."],"img":[["p1-57.webp",57]]},"khatt":{"t":"الخَطُّ","pg":58,"pts":["كتابة سطر من «يا قدس»."],"img":[["p1-58.webp",58]]},"taabir":{"t":"تَطْبيقٌ عَمَلِيٌّ عَلى بِناءِ الفِقْرَةِ","pg":58,"pts":["تطبيقٌ عمليّ على بناء الفقرة."],"img":[["p1-58.webp",58]]}},"listen":"العَمَلُ ناموسُ الحَياةِ"},{"id":"P1U5","part":1,"n":5,"sec":{"read":{"t":"الرَّمْلَةُ","pg":60,"paras":["يتحدّثُ النّصُّ الّذي بَينَ أيدينا عَنْ مدينةِ الرَّملةِ الفِلَسْطينِيَّةِ العَريقَةِ ذاتِ التّاريخِ المَجيدِ، الّتي كانت تُسَمّى قَصَبةَ فِلَسْطينَ، وَيَسْتَعرضُ تاريخَهَا المُشْرِقَ، وَكَيفَ كانت حاضِرَةً للْخِلافَةِ الإِسْلامِيَّةِ زَمَنَ الأمَوِيّينَ، وَما آلَتْ إلَيْهِ بَعدَما اغْتَصَبَها الاحتلالُ الصّهيونيّ، وَتَهْجيرِ أهْلِها، فيما يَظَلُّ الأمَلُ مَغْروساً في القُلوبِ والعُقولِ بِحَتْمِيَّةِ العَوْدَةِ إلَيْها، وإلى بَقِيَّةِ القُرى والمُدنِ الفِلسطينيّةِ الّتي احْتُلَّتْ سَنَةَ ١٩٤٨م.","إِذا السَّحابُ زَفَتْهُ الرّيحُ مُرْتَفِعاً فَلا عَدا الرَّمْلَةَ البَيْضاءَ مِنْ بَلَدِ","كَما تُزَيِّنُ حَبَّةُ اللُّؤْلُؤِ واسِطَةَ العِقْدِ الَّذي يُزَيِّنُ جيدَ الحَسْناءِ، تَنْتَظِمُ الرَّمْلَةُ (قَصَبَةُ فِلَسْطينَ) وَسَطَ مُدُنٍ قَمَرِيَّةٍ يَرْبِطُهُنَّ مَدارٌ مِنْ تاريخٍ طَويلٍ، حافِلٍ بِالحُبِّ وَالحُزْنِ وَالعَطاءِ، وَناطِقٍ بِصَوْتِ الأمَلِ المُتَجَدِّدِ بِعَوْدَةِ الأحْبابِ، بَعْدَ أنْ طالَ الفِراقُ، وَعَزَّ اللِّقاءُ.","عَلى تَلَّةٍ مُرْتَفِعَةٍ تَتَرَبَّعُ الرَّمْلَةُ مُعْتَزَّةً بِعَراقَتِها، وَهُوِيَّتِها العَرَبِيَّةِ الإِسْلامِيَّةِ الَّتي مَنَحَها إِيّاها الأمَوِيّونَ؛ فَقَدْ بَناها الخَليفَةُ الأُمَوِيُّ سُلَيْمانُ بْنُ عَبْدِ المَلِكِ عامَ ٧١٥م، وَجَعَلَها مَقَرَّ خِلافَتِهِ. أخَذَ بِناؤُها شَكْلاً مُنْتَظَماً؛ حَيْثُ يَقْسِمُها شارِعانِ رَئيسانِ يَتَقاطَعانِ في مَرْكَزِ المَدينَةِ، وَهُناكَ أقيمَتْ دارُ الإِمارَةِ، وَبِجانِبِها المَسْجِدُ الأبْيَضُ، وَعَلى طولِ الشّارِعَيْنِ امْتَدَّتِ الأسْواقُ المُتَخَصِّصَةُ؛ كسوقِ العُطورِ، وَسوقِ اللُّحومِ، وَسوقِ الخُضارِ، وَسوقِ البُقولِيّاتِ، وَغَيْرِها، وَلَعَلَّ البارِزَ مِنْها دارُ الصَّبّاحينَ (سوقُ الدَّهّانينَ).","وَالرَّمْلَةُ -كَما هُوَ واضِحٌ مِنِ اسْمِها- مُشْتَقَّةٌ مِنْ كَلِمَةِ (رَمْلٍ)، فَقَدْ بُنِيَتْ عَلى أرْضٍ رَمْلِيَّةٍ مُحاذِيَةٍ لِمَدينَةِ اللُّدِّ (ليدا) القَديمَةِ، وَلَرُبَّما اشْتُقَّ مِنْ امْرَأةٍ اسْمُها (رَمْلَة)، وَجَدَها سُلَيْمانُ بْنُ عَبْدِ المَلِكِ في بَيْتِ شَعْرٍ، فَأكْرَمَتْهُ، وَأحْسَنَتْ ضِيافَتَهُ، فَسَألَها عَنِ اسْمِها، فَقالَتْ (رَمْلَة)، فَأعادَ بِناءَ المَدينَةِ، وَسَمّاها رَمْلَةً، وَباتَ هذا الاسْمُ شاهِداً لا يَمَّحي عَلى كَرَمِ تِلْكَ المَدينَةِ المِضْيافَةِ.","في الرَّمْلَةِ، تَتَعانَقُ سُهولُ الحُبوبِ وَالبُقولِيّاتِ وَالخَضْراواتِ، وَفي سَمائِها رائِحَةٌ عِطْرِيَّةٌ حَزينَةٌ، يَبُثُّها عَبَقُ بَيّاراتِ الحَمْضِيّاتِ الَّتي صادَرَها الاحْتِلالُ البَغيضُ. وَقَدْ كَشَفَت الحَفْرِيّاتُ عَنْ خَوابٍ كَبيرَةٍ مُسْتَطيلَةِ الشَّكْلِ، تَحْتَوي عَلى آثارِ صِبْغَةٍ حَمْراءِ اللَّوْنِ، كانَتْ تُسْتَعْمَلُ لِصَبْغِ الأقْمِشَةِ، وَيَبْدو أنَّها كانَتْ أبْرَزَ مَصادِرِ ثَرْوَةِ المَدينَةِ. وَاكْتُشِفَتْ دَلائِلُ أخْرى عَلى النَّشاطاتِ الصِّناعِيَّةِ في المَدينَةِ، وُجِدَتْ في بَقايا أرْبَعَةِ مَحَلّاتٍ لِلْخَزَفِ، وَتَحْتَوي عَلى قَوالِبَ، وَمَصابيحَ، وَصَوانٍ.","وَازْدِهارُ المَدينَةِ واضِحٌ أيْضاً في الهَنْدَسَةِ المِعْمارِيَّةِ، حَيْثُ تَظْهَرُ مَجْمُوعَةٌ مِنَ النُّقوشِ الهَنْدَسِيَّةِ عَلى البُيوتِ البَيْضاءِ. وَتَزْخَرُ الرَّمْلَةُ بِعَدَدٍ مِنَ المَواقِعِ الأثَرِيَّةِ المُهِمَّةِ، مِنْها: بَقايا قَصْرِ سُلَيْمانَ بْنِ عَبْدِ المَلِكِ، وَالجامِعُ الكَبيرُ بِمِئْذَنَةٍ يَبْلُغُ طولُها خَمْسَةً وَعِشْرينَ مِتْراً، تَتَكَوَّنُ مِنْ خَمْسَةِ طَوابِقَ مُرَبَّعَةِ الشَّكْلِ مَبْنِيَّةٍ بِالحَجَرِ المُسَمّى (النَّحيت)، مِنْ أعْلاها يَقِفُ النّاظِرُ مُطِلّاً عَلى سُهولِ يافا الجَميلَةِ، وَهِيَ تَرْوي حِكاياتِ الأجْدادِ، وَيَصْدَحُ بُرْتُقالُها بِتَراتيلِ الشَّوْقِ لِأصْحابِهِ، وَمِنَ النّاحِيَةِ الأخْرى تُطِلُّ عَلَيْها جِبالُ القُدْسِ عاصِمَةِ فِلَسْطينَ، إِنَّها لَوْحَةٌ بَديعَةٌ لِعِناقِ الفَراشاتِ فَوْقَ فِلَسْطينَ.","وَلا نَنْسى بِرْكَةَ العَنْزِيَّةِ (الأقْواسَ) الَّتي بَناها الرَّشِيدُ؛ لِتَكونَ مُجَمَّعاً مائِيّاً قَوِيّاً، وَقَبْرَ الفَضْلِ بْنِ العَبّاسِ، وَمَقامَ النَّبِيِّ صالِحٍ، وَعَدَداً مِنَ الكَنائِسِ المَسيحِيَّةِ. كُلُّ هذِهِ الآثارِ وَغَيْرُها تَبْقى صَوْتاً صارِخاً يَنْطِقُ بِعُروبَةِ هذِهِ اللُّؤْلُؤَةِ الَّتي خَطَفَها الصَّهايِنَةُ في نَكْبَةِ ١٩٤٨م، وَطَرَدوا أَهْلَها مِنْها، فَصاروا لاجِئينَ.","الرَّمْلَةُ مَدينَةُ الماضي وَالحاضِرِ، بِمَوْقِعِها، وَسُهولِها، وَمُناخِها المُعْتَدِلِ، شَهِدَتْ حُضوراً في الحَرْبِ وَفي السِّلْمِ، كانَتْ مَعْقِلاً عَسْكَرِيّاً لِجُيوشٍ مُتَعَدِّدَةٍ، وَعانَتْ في تاريخِها مِنْ صِراعاتٍ، وَتَجاذُباتٍ، وَأطْماعٍ أثَّرَتْ كَثيراً في نَهْضَتِها، وَلكِنَّها كانَتْ دَوْماً تَتَجاوَزُها، وَلَمْ تَسْلَمْ مِنْ وَيْلاتِ الطَّبيعَةِ وَالزَّلازِلِ.","واليَوْمَ تَقِفُ الرَّمْلَةُ تُناجي أبْناءَها، وَتُرْسِلُ لَهُمْ هَمَساتٍ مُشْبَعَةً بِالحَنينِ، تُسْمَعُ في جِبالِ القُدْسِ وَالجَليلِ، وَتُعانِدُ مُغْتَصِبيها الَّذينَ اسْتَوْطَنوها، وَرَحَّلوا أهْلَها الأصْلِيّينَ، تَسْتَعْصي عَلَيْهِمْ؛ لِأنَّها تُمَثِّلُ الوَجْهَ الفِلَسْطينِيَّ العَرَبِيَّ الأصيلَ."],"voc":[["(المتنبّي) زَفَتْهُ","حَرَّكَتْهُ، وَساقَتْهُ."],["الجيدُ","العُنُقُ، أوْ مَوْضِعُ القِلادَةِ."],["الحافِلُ","المَليءُ."],["الْمُحاذي","المُقابِلُ أو المجاور."],["الخَوابي","مُفْرَدُها الخابِيَةُ، وَهِيَ الجَرَّةُ العَظيمَةُ، أوِ الوِعَاءُ الَّذي يُحْفَظُ فيهِ الماءُ، أوِ الزَّيْتُ، أوِ الحُبوبُ، وَغَيْرُهُا."],["تَزْخَرُ","تَمْتَلِئُ."],["صَدَحَ","رَفَعَ صَوْتَهُ بِالغِناءِ."],["التَّراتيلُ","جَمْعُ التَرْتيلَةِ، وَهِيَ أنْشودَةٌ مُرَتَّلَةٌ مِنَ الصَّلاَةِ عِنْدَ الْمَسيحِيّينَ."],["المَعْقِلُ","المَلْجَأ وَالحِصْنُ."]],"img":[["p1-60.webp",60],["p1-61.webp",61],["p1-62.webp",62],["p1-63.webp",63],["p1-64.webp",64]]},"grammar":{"t":"المَبْنِيُّ لِلْمَعْلومِ وَالمَبْنِيُّ لِلْمَجْهولِ","pg":65,"pts":["المبنيّ للمعلوم: فعلٌ ذُكر فاعله.","المبنيّ للمجهول: ما حُذف فاعله وأُقيم المفعول به مقامه فيسمّى نائب فاعل، وهو مرفوع.","بناء الماضي للمجهول: يُضمّ أوّله ويُكسر ما قبل آخره (كُتِبَ).","بناء المضارع للمجهول: يُضمّ أوّله ويُفتح ما قبل آخره (يُكْتَبُ)."],"img":[["p1-65.webp",65],["p1-66.webp",66]],"q":[["المبنيّ للمجهول من «فَتَحَ»:",["فُتِحَ","فَتَّحَ","يَفْتَحُ","افْتَحْ"],0,""],["المبنيّ للمجهول من «يَبْني»:",["يُبْنى","بُنِيَ","يَبْنِي","ابْنِ"],0,""],["«بُنِيَ المسجدُ الأبيض»: «المسجدُ»:",["نائب فاعل مرفوع","فاعل","مفعول به","مبتدأ"],0,""]]},"imla":{"t":"الألِفُ اللَّيِّنَةُ في أواخِرِ الأفْعالِ","pg":69,"pts":["الألف اللّيّنة في آخر الفعل الثّلاثيّ تُكتب قائمة إذا كان أصلها واوًا (دعا، سما)، وياءً إذا كان أصلها ياءً (رمى، مشى).","وتُكتب ياءً في الفعل فوق الثّلاثيّ (استدعى، أعطى) ما لم تُسبق بياء (أحيا)."],"img":[["p1-69.webp",69]]},"khatt":{"t":"الخَطُّ","pg":70,"pts":["كتابة عبارة بخطّ النّسخ."],"img":[["p1-70.webp",70]]},"taabir":{"t":"كِتابَةُ فِقْرَتَيْنِ","pg":71,"pts":["كتابة فقرتين."],"img":[]}},"listen":"الأطْفالُ الكِبارُ"},{"id":"P1U6","part":1,"n":6,"sec":{"read":{"t":"لِماذا؟","pg":73,"paras":["السُّؤالُ اللّاهِثُ اللّاهِبُ الَّذي كانَ يَمْلَأ عَلَيَّ طَريقي كُلَّها وَأنا عائِدٌ مِنْ زِيارَةِ الهِنْدِ، مارّاً في سَماءِ البَحْرِ العَرَبِيِّ وَهِضابِ عُمانَ، مُطِلّاً عَلى الإِماراتِ، مُجْتازاً الكُوَيْتَ إِلى دِمَشْقَ، مُشْبَعاً بِروائِحِ النِّفْطِ، وَطُيوفٍ مِنَ الحَضارَةِ وَالبَداوَةِ تُحيطُ بِهذهِ الرَّوائِحِ، قَبْلَ أنْ أواجِهَ أرْواحَ الغوطَةِ وَنَسائِمَ بَرَدى، مُمْتَلِئَ القَلْبِ بِالرِّمالِ وَالصَّحارى، مُتمَنِّياً لَوِ اسْتَطَعْتُ أنْ أزْحَفَ عَلى كُلِّ رَمْلٍ، أقَبِّلُ مَواطِنَ أقدامِ أولئِكَ الَّذينَ انْطَلَقوا مِنْ مَدينَةِ الرَّسولِ، صَلّى اللهُ عَلَيْهِ وَسَلَّمَ، وبَوادي الجَزيرَةِ، وَوَحَّدوا هذا الجيلَ مِنَ النّاسِ بَعْدَ طولِ اقْتِتالٍ وَخِصامٍ، السُّؤالُ الَّذي كانَ يَمْلَأ عَلَيَّ وُجودِيَ كُلَّهُ، وَدُنْيايَ كُلَّها في هذِهِ الرِّحْلَةِ، هُوَ: لِماذا؟ لِماذا يَظَلُّ العَرَبُ يَعيشونَ في أتونِ الفُرْقَةِ ؟","لِماذا؟ لِماذا أقطَعُ الطَّريقَ في هذِهِ الأجْزاءِ مِنْ أرْضِ العَرَبِ، أبْرِزُ جَوازي مَرَّةً في كُلِّ نِصْفِ ساعَةٍ، كَأنّي أنْتَقِلُ مِنْ دَوْلَةٍ إِلى دَوْلةٍ، عَلى حينِ قَطَعْتُ آلافَ الأمْيالِ، وَاجْتَزْتُ أبْعَدَ المَسافاتِ، وَانْتَقَلْتُ مِنَ البَحْرِ إِلى البَرِّ، وَمِنَ السّاحِلِ إِلى الدّاخِلِ، وَمِنَ الوادي إِلى الجَبَلِ، وَأوْشَكْتُ أنْ أبْلُغَ المُرْتَفَعاتِ العُلْيا في (كَشْميرَ) دونَ أنْ يَسْألوني، أيْنَ جَوازُكَ؟","الهِنْدُ قارَّةٌ، وَغابَةٌ مِنَ اللُّغاتِ، يَعيشُ فيها ما يَزيدُ عَلى المِلْيارِ، يَنْتَظِمُهُمْ نَسَقٌ واحِدٌ جَميلٌ. فَكَيْفَ لا يَنْتَظِمُنا -في بِلادِ العَرَبِ- نَسَقٌ لُغَوِيٌّ أَصيلٌ، هُوَ هُوَ في كُلِّ مَكانٍ مِنْ هذِهِ البِلادِ، هُوَ في الواقِعِ الخارِجِيِّ، وَهُوَ في الواقِعِ النَّفْسِيِّ، وَهُوَ في الفَرْدِ، وَفي الجَماعَةِ، هُوَ في الوِجْدانِ، وَهُوَ في العَقْلِ، تَسْمَعُهُ في أطْرافِ الجَبَلِ الأخْضَرِ عَلى المُحيطِ الهِنْديِّ، ثُمَّ يَصْحَبُكَ في الرِّحْلةِ البَعيدَةِ إِلى أطْرافِ الأطْلَسيِّ. فَكَيْفَ اسْتَطاعَ التَّشَتُّتُ اللُّغَوِيُّ في القارَّةِ الهِنْديَّةِ أنْ يَخْتَفِيَ عَنْ طَريقِ الدَّوْلَةِ الواحِدَةِ، ثُمَّ لَمْ يَسْتَطِعِ التَّوحُّدُ اللُّغَويُّ أنْ يُساعِدَ في الأرْضِ العَرَبِيَّةِ عَلى إِنْشاءِ الدَّوْلَةِ الواحِدَةِ؟","لِماذا تَخْتَلِطُ الدِّماءُ عَلى طولِ الهِنْدِ وَعَرْضِها؛ لِتُؤَلِّفَ هذِهِ البُحَيْرةَ الَّتي تَنْتَهي إِلَيْها كُلُّ هذِهِ الرَّوافِدِ المُتبايِنَةِ، فَتَتَلاقى هذا التَّلاقِيَ المُتَجَدِّدَ، وَتَنْبِضُ النَّبْضَ المُشْتَرَكَ، وَيَكونُ لَها هذا الأرَجُ الواحِدُ، أرَجُ الهِنْدِ؟","لِماذا كانَ ذلِكَ هُناكَ؟ وَلِماذا تُؤَلِّفُ بُحَيْرَةُ الدَّمِ العَرَبِيِّ هذا الأرْخَبيلَ أ مِنَ الجُزُرِ الصَّغيرَةِ، يَنْحَسِرُ عَنْها بَحْرٌ، ثُمَّ يُغَطّيها بَحْرٌ، تَخْلُقُ مِنْ بَيْنِها الجُسورَ، ثُمَّ تُحَطِّمُ هذِهِ الجُسورَ؟ لِماذا يَكونُ لِهذا الدَّمِ العَرَبِيِّ عَشَراتُ القُلوبِ الَّتي يَنْبِضُ بِها، وَلا يَكونُ لِلعَرَبِ قَلْبٌ واحِدٌ يَنْبِضُ بِوُجودٍ واحِدٍ، وَيَسْتَشْرِفُ أفُقاً واحِداً، وَيَتَطَلَّعُ إِلى مُسْتَقْبَلٍ واحِدٍ؟","لِماذا يَرْتَفِعُ في سَمائِنا عِشْرونَ عَلَماً، وَلِكُلِّ عَلَمٍ قِصَّةٌ، ثُمَّ نَنْسى القِصَّةَ الكُبْرى، رِسالَةَ العَلَمِ الواحِدِ، واللُّغَةِ الواحِدَةِ والأمَلِ الواحِدِ، والأرْضِ الواحِدَةِ. عَلى حينِ يَرْتَفِعُ في سَماءِ غَيْرِنا عَلَمٌ واحِدٌ يَطْوي الأعْلامَ الصَّغيرَةَ؛ لِيُؤَلِّفَ قِصَّةَ العَلَمِ الواحِدِ؟ إِنَّكَ لَتَسْألُني: لِماذا ؟ وإِنّي لَأتَساءَلُ: لِماذا؟","دَعْني مِنْ تَطْويلاتِ القَوْلِ وَزُخْرُفاتِهِ، فَقَدْ بَدَأْتُ مُنْذُ زَمَنٍ قَريبٍ، أذْهَبُ إِلى أنَّ الَّذي يَقْتُلُنا إِنَّما هُوَ الكَلامُ، وَتَمَنَّيْتُ لَوْ قَطَعَ العَرَبُ طَريقَ الجَدَلِ؛ ليَأْخُذوا طَريقَ العَمَلِ. تَمَنَّيْتُ لَوْ أنَّ العَرَبَ صَمَتوا وَامْتَنَعوا عَنِ الكَلامِ بَعْضَ الأعْوامِ، وَانْصَرَفوا إِلى عَمَلٍ يُنْفِذونَهُ، وَأمَلٍ يُحَقِّقونَهُ.","أيُّها العائِدُ إِلى وَطَنِكَ مِنْ أيِّ بَلْدٍ كُنْتَ، لِتَكُنِ الكَلِمَةُ الحَلالُ الَّتي تَسْتَطيعُ أنْ تَقولَها، وَيَجِبُ أنْ تَقولَها، أنّى كانَ مَوْقِفُكَ مِنَ الحَياةِ في وَطَنِكَ: لِماذا ؟ وَحينَ نَكْتَشِفُ الجَوابَ، نَكونُ قَدِ اكْتَشَفْنا الطَّريقَ."],"voc":[["اللّاهِثُ","مَنْ يَتَنَفَّس بِسُرْعَةٍ مِنْ أثَرِ الجَرْيِ أوِ العَطَشِ."],["اللّاهِبُ","الحارُّ، المُثيرُ."],["أتونُ الفُرْقَةِ","شِدَّتُها وَضَراوَتُها."],["كَشْمير","مَدينَةٌ تَقَعُ شَمالَ غَرْبِ الهند."],["النَّسَقُ","النِّظامُ."],["الأرَجُ","الرّائِحَةُ الطَّيِّبَةُ."],["الأرْخَبيلُ","المَجْموعَةُ مِنَ الجُزُرِ المُتَقارِبَةِ في البَحْرِ."],["يَسْتَشْرِفُ","يَتَطَلَّعُ، وَيَحْدِسُ."],["الزُّخْرُفُ","الزّينَةُ."]],"img":[["p1-73.webp",73],["p1-74.webp",74],["p1-75.webp",75],["p1-76.webp",76]]},"poem":{"t":"لَنا الصَّدْرُ","pg":77,"verses":[["أَراكَ عَصِيَّ الدَّمْعِ شيمَتُكَ الصَّبْرُ","أَما لِلْهَوى نَهْيٌ عَلَيْكَ وَلا أَمْرُ؟"],["بَلى، أَنا مُشْتاقٌ وَعِنْدِيَ لَوْعَةٌ","وَلكِنَّ مِثْلي لا يُذاعُ لَهُ سِرُّ!"],["إِذا اللَّيْلُ أَضْواني بَسَطْتُ يَدَ الهَوى","وَأَذْلَلْتُ دَمْعاً مِنْ خَلائِقِهِ الكِبْرُ"],["تَكادُ تُضيءُ النّارُ بَيْنَ جَوانِحي","إِذا هِيَ أَذْكَتْها الصَّبابَةُ وَالفِكْرُ"],["أُسِرْتُ وَما صَحْبي بِعُزْلٍ، لَدى الوَغى","وَلا فَرَسي مُهْرٌ، وَلا رَبُّهُ غُمْرُ"],["وَلكِنْ إِذا حُمَّ القَضاءُ عَلى امْرِئٍ","فَلَيْسَ لَهُ بَرٌّ يَقيهِ، وَلا بَحْرُ"],["وَقالَ أُصَيْحابي: \"الفِرارُ أَوِ الرَّدى؟\"","فَقُلْتُ: \"هُما أَمْرانِ، أَحْلاهُما مُرُّ\""],["وَلكِنَّني أَمْضي لِما لا يَعيبُني","وَحَسْبُكَ مِنْ أَمْرَيْنِ خَيْرُهُما الأَسْرُ"],["سَيَذْكُرُني قَوْمي إِذا جَدَّ جِدُّهُمْ","وَفي اللَّيْلَةِ الظَّلْماءِ، يُفْتَقَدُ البَدْرُ"],["فَإِنْ عِشْتُ فَالطَّعْنُ الَّذي يَعْرِفونَهُ","وَتِلْكَ القَنا، وَالبيضُ وَالضُّمَّرُ الشُّقْرُ"],["وَإِنْ مِتُّ فَالإِنْسانُ لا بُدَّ مَيِّتٌ","وَإِنْ طالَتِ الأَيّامُ، وَانْفَسَحَ العُمْرُ"],["وَنَحْنُ أُناسٌ، لا تَوَسُّطَ عِنْدَنا","لَنا الصَّدْرُ، دونَ العالَمينَ، أَوِ القَبْرُ"],["تَهونُ عَلَيْنا في المَعالي نُفوسُنا","وَمَنْ خَطَبَ الحَسْناءَ لَمْ يُغْلِها المَهْرُ"],["أَعَزُّ بَني الدُّنْيا، وَأَعْلى ذَوي العُلا","وَأَكْرَمُ مَنْ فَوْقَ التُّرابِ وَلا فَخْرُ"]],"voc":[["عَصِيُّ الدَّمْعِ","الَّذي ل ا يَبْكي بِيُسْرٍ."],["الشّيمَةُ","الطَّبْعُ."],["اللَّوْعَةُ","الحُرْقَةُ في القَلْبِ."],["أضْوى","خَيَّمَ عَلى."],["الخَليقَةُ","الطَّبيعَةُ وَالسَّجِيَّةُ."],["الجَوانِحُ","الأضْلاعُ القصيرة ممّا يلي الصّدر."],["أذْكى","سَعَّرَ وَأجَّجَ."],["الصَّبابَةُ","حَرارَةُ الشَّوْقِ."],["العُزْلُ","جَمْعُ أعْزَلَ، وَهَوَ المُجَرَّدُ مِنْ السِّلاحِ."],["الوَغى","الحَرْبُ."],["الغُمْرُ","قَليلُ التَّجْرِبَةِ."],["حُمَّ القَضاءُ","وَقَعَ القَدَرُ."],["الرَّدى","المَوْتُ."],["حَسْبُكَ","كافيكَ."],["القَنا","الرِّماحُ."],["البيضُ","السُّيوفُ."],["الضُمَّرُ","الخُيولُ الضامِّرَة."],["انْفَسَحَ","اتَّسَعَ."],["تَهونُ","تَرْخُصُ.ُ"]],"img":[["p1-77.webp",77],["p1-78.webp",78],["p1-79.webp",79]]},"grammar":{"t":"بِناءُ فِعْلِ الأمْرِ","pg":80,"pts":["يُبنى فعل الأمر على ما يُجزم به مضارعه.","يُبنى على السّكون إذا كان صحيح الآخر ولم يتّصل به شيء، أو اتّصلت به نون النّسوة (اكتبْ، اكتبْنَ).","يُبنى على حذف حرف العلّة إذا كان معتلّ الآخر (ادعُ، اسعَ، ارمِ).","يُبنى على حذف النّون إذا اتّصلت به ألف الاثنين أو واو الجماعة أو ياء المخاطبة."],"img":[["p1-80.webp",80],["p1-81.webp",81]],"q":[["«اسْعَ إلى الخير»: يُبنى على:",["حذف حرف العلّة","السّكون","حذف النّون","الفتح"],0,""],["«ادرسْنَ يا طالباتُ»: يُبنى على:",["السّكون","حذف النّون","الفتح","حذف حرف العلّة"],0,""],["«تعاونوا»: يُبنى على:",["حذف النّون","السّكون","الضّمّ","الفتح"],0,""]]},"balagha":{"t":"المُحَسِّناتُ اللَّفْظِيَّةُ (السَّجْعُ)","pg":84,"pts":["السّجع: توافقُ الفاصلتين أو أكثر في الحرف الأخير، وموطنه النّثر.","من أمثلته: «اللّهمّ أعطِ منفقًا خلفًا، وأعطِ ممسكًا تلفًا»."],"img":[["p1-84.webp",84]]},"imla":{"t":"الألِفُ اللَّيِّنَةُ في الأسْماءِ فَوْقَ الثُّلاثِيَّةِ","pg":83,"pts":["الألف اللّيّنة في الأسماء فوق الثّلاثيّة تُكتب ياءً (مستشفى، مصطفى) إلّا إذا سُبقت بياء فتُكتب قائمة (دنيا، قضايا)، وتُستثنى الأعلام الأعجميّة (أمريكا)."],"img":[["p1-83.webp",83]]},"khatt":{"t":"الخَطُّ","pg":87,"pts":["كتابة بيت بخطّ الرّقعة."],"img":[["p1-87.webp",87]]},"taabir":{"t":"كِتابَةُ فِقْرَتَيْنِ","pg":87,"pts":["كتابة فقرتين."],"img":[["p1-87.webp",87]]}},"listen":"الياسَمينُ الدِّمَشْقِيُّ"},{"id":"P1U7","part":1,"n":7,"sec":{"read":{"t":"حِكايَةُ اللَّبُؤَةِ وَالإِسْوارِ وَابْنِ آوى","pg":89,"paras":["قالَ الفَيْلَسوفُ بَيْدَبا: زَعَموا أنَّ لَبُؤَةً كانَتْ في أجَمَةٍ، وَلها شِبْلانِ، وَأنَّها خَرَجَتْ في طَلَبِ الصَّيْدِ، وَخَلَّفَتْهُما في الكَهْفِ، فَمَرَّ بِهِما إِسْوارٌ، فَحَمَلَ عَلَيْهِما، وَرَماهُما، فَقَتَلَهُما، وَسَلَخَ جِلْدَيْهِما فَاحْتَقَبَهُما، وَانْصَرَفَ بِهِما إِلى مَنْزِلِهِ، ثُمَّ إِنَّها رَجَعَتْ. فَلَمّا رَأتْ ما حَلَّ بِهِما مِنَ الأمْرِ الفَظيعِ، اضْطَرَبَتْ ظَهْراً لِبَطْنٍ، وَصاحَتْ، وَضَجَّتْ. وَكانَ إِلى جانِبِها ابْنُ آوى. فَلَمّا سَمِعَ صِياحَها قالَ لَها: ما الَّذي تَصْنَعينَ؟ وَما نَزَلَ بِكِ؟ فَأخْبِريني بِهِ. قالَتِ اللَّبُؤَةُ: شِبْلايَ مَرَّ بِهِما إِسْوارٌ، فَقَتَلَهُما، وَسَلَخَ جِلْدَيْهِما فاحْتَقَبَهُما، وَنَبَذَهُما بِالعَراءِ. قالَ لَها ابْنُ آوى: لا تَضِجّي، وَاعْلَمي أنَّ هذا الإِسْوارَ لَمْ يَأْتِ إِلَيْكِ بِشَيْءٍ إِلّا وَقَدْ كُنْتِ تَفْعَلينَ بِغَيْرِكِ مِثْلَهُ، وَتَأْتينَ إِلى غَيْرِ واحِدٍ مِثْلَ ذلِكَ، مِمَّنْ كانَ يَجِدُ بِحَميمِهِ، وَمَنْ يَعِزُّ عَلَيْهِ مِثْلَ ما تَجِدينَ بِشِبْلَيْكِ. فَاصْبِري عَلى فِعْلِ غَيْرِكِ، كَما صَبَرَ غَيْرُكِ عَلى فِعْلِكِ، فَإِنَّهُ قَدْ قيلَ: \"كَما تَدينُ تُدانُ\". وَلِكُلِّ عَمَلٍ ثَمَرَةٌ مِنَ الثَّوابِ وَالعِقابِ. وَهُما عَلى قَدْرِهِ في الكَثْرَةِ وَالقِلَّةِ، كَالزَّرْعِ إِذا حَضَرَ الحَصادُ أعْطى عَلى حَسْبِ بَذْرِهِ. قالَتِ اللَّبُؤَةُ: بَيِّنْ لي ما تَقولُ، وَأفْصِحْ لي عَنْ إِشارَتِهِ. قالَ ابْنُ آوى: كَمْ أتى لَكِ مِنَ العُمْرِ؟ قالَتِ اللَّبُؤَةُ: مِئَةُ سَنَةٍ. قالَ ابْنُ آوى: ما كانَ قوتُكِ؟ قالَتِ اللَّبُؤَةُ: لَحْمُ الوَحْشِ. قالَ ابْنُ آوى: مَنْ كانَ يُطْعِمُكِ إِيّاهُ؟ قالَتِ اللَّبُؤَةُ: كُنْتُ أصيدُ الوَحْشَ، وَآكُلُهُ. قالَ ابْنُ آوى: أرَأيْتِ الوُحوشَ الَّتي كُنْتِ تَأْكُلينَ، أما كانَ لَها آباءٌ وَأمَّهاتٌ؟ قالَتْ: بَلى. قالَ ابْنُ آوى: فَما بالي لا أرى وَلا أسْمَعُ لِأولئِكَ الآباءِ وَالأمَّهاتِ مِنَ الجَزَعِ وَالضَّجيجِ ماِ أرى وَأسْمَعُ لَكِ؟ أما إِنَّهُ لَمْ يَنْزِلْ بِكِ ما نَزَلَ إِلّا لِسوء نَظَرِكِ في العَواقِبِ، وَقِلَّةِ تَفْكيرِكِ فيها، وَجَهالَتِكِ بِما يَرْجِعُ عَلَيْكِ مِنْ ضُرِّها.","فَلَمّا سَمِعَتِ اللَّبُؤَةُ ذلِكَ مِنْ كَلامِ ابْنِ آوى، عَرَفَتْ أنَّ ذلِكَ مِمّا جَنَتْ عَلى نَفْسِها، وَأنَّ عَمَلَها كانَ جَوْراً وَظُلْماً، فَتَرَكَتِ الصَّيْدَ، وَانْصَرَفَتْ عَنْ أكْلِ اللَّحْمِ إِلى الثِّمارِ وَالنُّسُكِ وَالعِبادَةِ. فَلَمّا رَأى ذلِكَ (وَرَشانٌ) الَّذي كانَ يَعْتاشُ مِنَ الثِّمارِ، قالَ لَها: قَدْ كُنْتُ أظُنُّ أنَّ الشَّجَرَ في عامِنا هذا لَمْ يَحْمِلْ؛ لِقِلَّةِ الماءِ، فَلَمّا أبْصَرْتُكِ تَأْكُلينَها، وَأَنْتِ آكِلَةُ اللَّحْمِ، عَلِمْتُ أَنَّ الشَّجَرَ هذا العامَ أَثْمَرَ كَما في كُلِّ عامٍ، وَإِنَّما أتَتْ قِلَّةُ الثَّمَرِ مِنْ جِهَتِكِ. فَوَيْلٌ لِلشَّجَرِ، وَوَيْلٌ لِلثِّمارِ، وَوَيْلٌ لِمَنْ عَيْشُهُ مِنْها! ما أسْرَعَ هَلاكَهُمْ إِذا دَخَلَ عَلَيْهِمْ في أرْزاقِهِمْ، وَغَلَبَهُمْ عَلَيْها مَنْ لَيْسَ لَهُ فيها حَظٌّ وَلَمْ يَكُنْ مُعْتاداً عَلى أكْلِها!","فَلَمّا سَمِعَتِ اللَّبُؤَةُ كَلامَ الوَرَشانِ، تَرَكَتْ أكْلَ الثِّمارِ، وَأقْبَلَتْ عَلى أكْلِ الحَشيشِ، وَالعِبادَةِ.","وَإِنَّما ضَرَبْتُ لَكَ أيُّها المَلِكُ هذا المَثَلَ؛ لِتَعْلَمَ أنَّ الجاهِلَ رُبَّما انْصَرَفَ بِضُرٍّ يُصيبُهُ عَنْ ضُرِّ النّاسِ، كَاللَّبُؤَةِ الَّتي انْصَرَفَتْ، لِما لَقِيَتْ في شِبْلَيْها، عَنْ أكْلِ اللَّحْمِ بِأكْلِ الثِّمارِ، بِقَوْلِ ابْنِ آوى، ثُمَّ عَنْ أكْلِ الثِّمارِ بِأكْلِ الحَشائِشِ، بِقَوْلِ الوَرَشانِ، وَأقْبَلَتْ عَلى النُّسُكِ وَالعِبادَةِ. وَالنّاسُ أحَقُّ بِحُسْنِ النَّظَرِ في ذلِكَ؛ فَإِنَّهُ قَدْ قيلَ: ما لا تَرْضاهُ لِنَفْسِكَ لا تَصْنَعْهُ لِغَيْرِكَ؛ فَإِنَّ في ذلِكَ العَدْلَ، وَفي العَدْلِ رِضا اللّهِ -جَلَّ، وَعَلا- وَرِضا النّاسِ."],"voc":[["اللَّبُؤَةُ","أنْثى الأسَدِ."],["الأجَمَةُ","مَوْضِعٌ يَكْثُرُ فيهِ الشَّجَرُ، وَيَلْتَفُّ."],["الشِّبْلُ","ابْنُ الأسَدِ."],["الإِسْوارُ","الجَيِّدُ الرَّمْيِ بِالسِّهامِ."],["احْتَقَبَهُما","شَدَّهُما في مُؤَخَّرِ رَحْلِ رَكوبَتِهِ، أوْ حَمَلَهُما."],["ابْنُ آوى","حَيَوانٌ مِنْ فَصيلَةِ الكَلْبِيّاتِ، أصْغَرُ حَجْماً مِنَ الذِّئْبِ، وَيُجْمَعُ عَلى بَناتِ آوى."],["نَبَذَهُما","طَرَحَهُما.ُ"],["الوَجْدُ","الحُزْن"],["الجَزَعُ","ما يُحِسُّ بِهِ المَرْءُ مَنَ القَلَقِ وَالاضْطِرابِ، وَضيقِ الصَّدْرِ."],["وَرَشانٌ","طَيْرٌ مِنْ فَصيلَة الحَمامِ."],["النُّسُكُ","التَّزَهُّدُ وَالتَّعَبُّدُ. عن"]],"img":[["p1-89.webp",89],["p1-90.webp",90],["p1-91.webp",91],["p1-92.webp",92],["p1-93.webp",93]]},"poem":{"t":"التَّرْبِيَةُ وَالأُمَّهاتُ","pg":94,"verses":[["هِيَ الأَخْلاقُ تَنْبُتُ كَالنَّباتِ","إِذا سُقِيَتْ بِماءِ المَكْرُماتِ"],["تَقومُ إِذا تَعَهَّدَها المُرَبّي","عَلى ساقِ الفَضيلَةِ مُثْمِراتِ"],["وَلَمْ أَرَ لِلْخَلائِقِ مِنْ مَحَلٍّ","يُهَذِّبُها كَحِضْنِ الأُمَّهاتِ"],["فَحِضْنُ الأُمِّ مَدْرَسَةٌ تَسامَتْ","بِتَرْبِيَةِ البَنينَ أَوِ البَناتِ"],["وَأَخْلاقُ الوَليدِ تُقاسُ حُسْناً","بِأَخْلاقِ النِّساءِ الوالِداتِ"],["فَكَيْف تَظُنُّ بِالأَبْناءِ خَيْراً","إذا نَشَؤوا بِحِضْنِ الجاهِلاتِ"],["أَلَيْسَ العِلْمُ في الإِسْلامِ فَرْضاً","عَلى أَبْنائِهِ وَعَلى البَناتِ"],["وَكانَتْ أُمُّنا في العِلْم بَحْراً","تَحُلُّ لِسائِليها المُشْكِلاتِ"],["وَعَلَّمَها النَّبِيُّ أَجَلَّ عِلْمٍ","فَكانَتْ مِنْ أَجَلِّ العالِماتِ"],["أَلَمْ نَرَ في الحِسانِ الغيدِ قَبْلاً","أَوانِسَ كاتِباتٍ شاعِراتِ؟"],["وَقَدْ كانَتْ نِساءُ القَوْمِ قِدْماً","يَرُحْنَ إِلى الحُروبِ مَعَ الغُزاةِ"],["يَكُنَّ لَهُمْ عَلى الأَعْداءِ عَوْناً","وَيَضْمِدْنَ الجُروحَ الدّامِياتِ"],["وَكَمْ مِنْهُنَّ مَنْ أُسِرَت وَذاقَتْ","عَذابَ الهونِ في أَسْرِ العُداةِ"],["فَماذا اليَوم ضَرَّ لَوِ الْتَفَتْنا","إِلى أَسْلافِنا بَعْضَ التِفاتِ"]],"voc":[["ضَمَّدَ الجُرْحَ",""]],"img":[["p1-94.webp",94],["p1-95.webp",95]]},"grammar":{"t":"بِناءُ فِعْلِ الأمْرِ (مُراجَعَةٌ)","pg":96,"pts":["مراجعة بناء فعل الأمر."],"img":[["p1-96.webp",96]],"q":[["«ارمِ الكرة»: يُبنى على:",["حذف حرف العلّة","السّكون","حذف النّون","الفتح"],0,""],["«احذري يا سلمى»: يُبنى على:",["حذف النّون","السّكون","الكسر","الفتح"],0,""]]},"balagha":{"t":"تَطْبيقٌ عَمَلِيٌّ عَلى السَّجْعِ","pg":97,"pts":["تطبيقٌ عمليّ على السّجع."],"img":[["p1-97.webp",97]]},"imla":{"t":"الألِفُ اللَّيِّنَةُ (مُراجَعَةٌ)","pg":96,"pts":["مراجعة الألف اللّيّنة."],"img":[["p1-96.webp",96]]},"khatt":{"t":"الخَطُّ","pg":98,"pts":["كتابة حكمة."],"img":[["p1-98.webp",98]]},"taabir":{"t":"كَيْفِيَّةُ كِتابَةِ مُقَدِّمَةٍ تَسْبِقُ فِقْرَةً ما","pg":99,"pts":["كيفيّة كتابة مقدّمة."],"img":[]}},"listen":"مِكْيالُكَ يُكالُ لَكَ بِهِ"},{"id":"P1U8","part":1,"n":8,"sec":{"read":{"t":"شَيْءٌ خَطيرٌ سَيَحْدُثُ في هذِهِ القَرْيَةِ","pg":101,"paras":["تَخَيَّلوا قَرْيَةً صَغيرَةً جِدّاً، تَعيشُ فيها سَيِّدَةٌ مُسِنَّةٌ مَعَ ابْنَيْنِ اثْنَيْنِ: ابْنٍ في السابِعَةَ عَشْرَةَ، وَابْنَةٍ في الرّابِعَةَ عَشْرَةَ. إِنَّها تُقَدِّمُ وَجْبَةَ الفَطورِ لابْنَيْها، وَيُلاحِظانِ في وَجْهِها مَلامِحَ قَلَقٍ شَديدٍ. يَسْأَلُها الابْنانِ عَمّا أَصابَها، فَتُجيبُهُما:","- لا أَدْري، لكِنَّني اسْتَيْقَظْتُ بِإِحْساسِ أَنَّ شَيْئاً خَطيراً جِدّاً سَيَحْدُثُ في هذِهِ القَرْيَةِ.","يَضْحَكُ الابْنانِ مِنْها، وَيَقولانِ: إِنَّها هَواجِسُ عَجوزٍ.","يَذْهَبُ الابْنُ لِيَلْعَبَ (البِلْيارْدو)، وَفي اللَّحْظَةِ الَّتي يوشِكُ فيها عَلى تَوْجيهِ ضَرْبَةِ (كارامبولا)، شَديدَةِ البَساطَةِ، يَقولُ لَهُ الخَصْمُ:","- أُراهِنُكَ (بِبيزو) أَنَّكَ لَنْ تُفْلِحَ.","يَضْحَكُ الجَميعُ، وَيَضْحَكُ هُوَ أَيْضاً، وَيُوَجِّهُ ضَرْبَةَ (الكارامبولا)، وَلا يُفْلِحُ فيها. يَدْفَعُ (البيزو)، وَيَسْأَلُهُ الحاضِرونَ: ما الَّذي حَدَثَ، لَقَدْ كانَتْ (كارامبولا) سَهْلَةً جِدّاً؟ فَيُجيبُ:","- صَحيحٌ، لكِنَّني ما زِلْتُ قَلِقاً مِنْ شَيْءٍ قالَتْهُ أُمّي صَباحَ اليَوْمِ، عَنْ أَمْرٍ خَطيرٍ سَيَحْدُثُ في هذِهِ القَرْيَةِ.","يَضْحَكُ الجَميعُ مِنْهُ، وَيَعودُ الَّذي كَسَبَ (البيزو) إِلى بَيْتِهِ، وَيَجِدُ أُمَّهُ وَمَعَها ابْنَةُ عَمٍّ، فَيَقولُ سَعيداً بالبيزو:","- كَسَبْتُ هذا (البيزو) مِنْ (داماسو) بِأَسْهَلِ طَريقَةٍ؛ لِأَنَّهُ أَبْلَهُ.","- وَلِماذا هَوَ أَبْلَهُ؟","- لَمْ يَسْتَطِعْ تَحْقيقَ ضَرْبَةِ (كارامبولا) سَهْلَةٍ جِدّاً؛ لِأَنَّهُ مُضْطَرِبٌ بِسَبَبِ قَلَقٍ اسْتَيْقَظَتْ بِهِ أُمُّهُ اليَوْمَ، وَإِحْساسِها بِأَنَّ شَيْئاً خَطيراً جِدّاً سَيَحْدُثُ في هذِهِ القَرْيَةِ.","عِنْدَئِذٍ تَقولُ لَهُ أُمُّهُ:","- لا تَسْخَرْ مِنْ هَواجِسِ المُسِنّينَ؛ لِأَنَّها تَتَحَقَّقُ أَحْياناً.","تَسْمَعُ القَريبَةُ الحاضِرَةُ ما قالَهُ، وَتَذْهَبُ لِشِراءِ لَحْمٍ. تَقولُ لِلجَزّارِ:","- أَعْطِني رِطْلَ لَحْمٍ. وَبَيْنَما هُوَ يَقْطَعُ اللَّحْمَ، تُضيفُ قائِلَةً:","- مِنَ الأَفْضَلِ أَنْ تُعْطِيَني رِطْلَيْنِ؛ لِأَنَّهُمْ يَقولونَ إِنَّ شَيْئاً خَطيراً سَيَحْدُثُ، وَمِنَ الخَيْرِ أَنْ نَكونَ مُسْتَعِدّينَ.","يَبيعُها الجَزّارُ اللَّحْمَ، وَعِنْدَما تَأْتي سَيِّدَةٌ أُخْرى؛ لِتَشْتَرِيَ رِطْلَ لَحْمٍ، يَقولُ لَها:","- خُذي رِطْلَيْنِ؛ لِأَنَّ النّاسَ يَأْتونَ إِلى هُنا قائِلينَ: إِنَّ شَيْئاً خَطيراً سَيَحْدُثُ، وَهُمْ يَسْتَعِدّونَ، وَيَشْتَرونَ مُؤَناً.","فَتُجيبُهُ السَّيِّدَةُ عِنْدَئِذٍ:","- لَدَيَّ أَبْناءٌ كَثيرونَ، مِنَ الأَفْضَلِ أَنْ تُعْطِيَني أَرْبَعَةَ أَرْطالٍ.","تَأْخُذُ أَرْبَعَةَ أَرْطالٍ. وَهكَذا يَبيعُ الجَزّارُ اللَّحْمَ كُلَّهُ خِلالَ نِصْفِ ساعَةٍ، ثُمَّ يَذْبَحُ بَقَرَةً أُخْرى، وَيَبيعُها كُلَّها، وَتَأْخُذُ الشّائِعَةُ تَنْتَشِرُ. وَتَأْتي لَحْظَةٌ يَكونُ جَميعُ مَنْ في القَرْيَةِ بِانْتِظارِ حُدوثِ شَيْءٍ. تُشَلُّ النَّشاطاتُ كُلُّها. وَفَجْأَةً، في السّاعَةِ الثّانِيَةِ بَعْدَ الظُّهْرِ، يَشْتَدُّ الحَرُّ كَالعادَةِ. فَيَقولُ أَحَدُهُمْ:","- هَلْ لاحَظْتَ شِدَّةَ هذا الحَرِّ؟","- أَجَلْ، وَلكِنَّ الحَرَّ شَديدٌ عَلى الدَّوامِ في هذِهِ القَرْيَةِ؛ إِنَّها قَرْيَةٌ شَديدَةُ الحَرِّ؛ حَتّى إِنَّ الموسيقِيّينَ فيها يُثَبِّتونَ أَجْزاءَ آلاتِهِم الموسيقِيَّةِ بالقَطْرانِ، وَلا يَعْزِفونَ إِلّا في الظِّلِّ؛ لِأَنَّهُمْ إِذا عَزَفوا عَلَيْها تَحْتَ الشَّمْسِ تَسْقُطُ مُفَكَّكَةً.","- وَمَعَ ذلِكَ، يَقولُ أَحَدُهُمْ: لَمْ يَحْدُثْ قَطُّ أَنْ كانَ الحَرُّ بِهذِهِ الشِّدَّةِ في مِثْلِ هذا الوَقْتِ.","- بَلى، وَلكِنْ لَيْسَ بِهذِهِ الشِّدَّةِ الَّتي هُوَ عَلَيْها الآنَ.","وَفي القَرْيَةِ المُقْفِرَةِ، في السّاحَةِ المُقْفِرَةِ، يَحُطُّ فَجْأَةً عُصْفورٌ، وَيَنْتَشِرُ الخَبَرُ: \"يوْجَدُ عُصْفورٌ في السّاحَةِ\"، وَيَأْتي الجَميعُ مَذْعورينَ لِرُؤْيَةِ العُصْفورِ.","- لكِنَّ العَصافيرَ تَحُطُّ دَوْماً هُنا أَيُّها السّادَةُ.","- أَجَلْ، وَلكِنْ لَيْسَ في مِثْلِ هذِهِ السّاعَةِ.","وَتَأْتي لَحْظَةٌ مِنَ التَّوَتُّرِ الشَّديدِ يَكونُ مَعَها أَهالي القَرْيَةِ جَميعُهُمْ مُتَلَهِّفينَ بِقُنوطٍ؛ لِلمُغادَرَةِ دونَ أَنْ يَجِدوا الشَّجاعَةَ لِفِعْلِ ذلِكَ. فَيَصْرُخُ أَحَدُهُمْ:","- أَنا رَجُلٌ وافِرُ الرُّجولَةِ، وَسَوْفَ أَرْحَلُ.","يُوَضِّبُ أَثاثَهُ، وَأَبْناءَهُ، وَبَهائِمَهُ، وَيَحْشُرُ كُلَّ ما لَدَيْهِ في عَرَبَةٍ، وَيَجْتازُ بِها الشّارِعَ المَرْكَزِيَّ، حَيْثُ تَراهُ القَرْيَةُ البائِسَةُ كُلُّها. وَتَأْتي لَحْظَةٌ يَقولونَ فيها: \"إِذا كانَ هذا قَدْ تَجَرَّأَ عَلى الذَّهابِ، فَسَوْفَ نَذْهَبُ نَحْنُ أَيْضاً\". وَيَبْدَأُ هَجْرُ القَرْيَةِ بِكُلِّ مَعْنى الكَلِمَةِ. تُحْمَلُ الأَمْتِعَةُ، وَالبَهائِمُ، وَكُلُّ شَيْءٍ. وَيَقولُ شَخْصٌ آخَرُ مِمَّنْ يُغادِرونَ القَرْيَةَ: \"عَسى أَلّا تَقَعَ المُصيبَةُ عَلى كُلِّ ما بَقِيَ مِنْ بَيْتِنا\"، وَعِنْدَئِذٍ يَحْرِقُ بَيْتَهُ، وَيَحْرِقُ آخَرونَ بُيوتاً أُخْرى. يَهْرُبونَ بِذُعْرٍ رَهيبٍ حَقيقِيٍّ، كَما لَوْ أَنَّهُ هُروبٌ مِنْ حَرْبٍ، وَبَيْنَهُمْ تَمْضي السَّيِّدَةُ صاحِبَةُ النُّبوءَةِ وَهِيَ تَقولُ:","- لَقَدْ قُلْتُ لَهُمْ: إِنَّ شَيْئاً خَطيراً سَوفَ يَحْدُثُ؛ فَقالوا: إِنَّني مَجْنونَةٌ."],"voc":[["الهَواجِسُ","مَا يَخْطُرُ بِبال الإِنْسانِ، مِنْ أفْكَارٍ، أوْ صُوَرٍ، نَتيجَةَ قَلَقٍ، أوْ حَيْرَةٍ، أوْ هَمٍّ، أوْ تَخَوُّفٍ مِنْ شَيْءٍ ما."],["كارامبولا","مُصْطَلَحٌ مَأْخوذٌ مِنْ لُعْبَةِ البِلْيارْدو، يُقْصَدُ بِهِ ارْتِدادُ الكُرَةِ عِدَّةَ مَرّاتٍ في اتِّجاهاتٍ مُخْتَلِفَةٍ."],["البيزو","العُمْلَةُ الرَّسْميَّةُ في بَعْضِ بِلادِ قارَّةِ أمريكا الجَنوبِيَّةِ."],["شَلَّ حَرَكَتَهُ","عَطَّلَها."],["يُوَضِّبُ","يُجَهِّزُ."]],"img":[["p1-101.webp",101],["p1-102.webp",102],["p1-103.webp",103],["p1-104.webp",104],["p1-105.webp",105],["p1-106.webp",106]]},"grammar":{"t":"تَدْريباتٌ عَلى المُعْرَبِ وَالمَبْنِيِّ في الأفْعالِ","pg":107,"pts":["تدريباتٌ على المعرب والمبنيّ في الأفعال: الماضي والأمر مبنيّان، والمضارع معرب إلّا مع نوني النّسوة والتّوكيد."],"img":[["p1-107.webp",107],["p1-108.webp",108]],"q":[["الفعل المعرب:",["يَحْدُثُ","حَدَثَ","احْذَرْ","يَكْتُبْنَ"],0,""],["«القريةُ لن تنامَ»: «تنام»:",["معرب منصوب","مبنيّ","مرفوع","مجزوم"],0,""]]},"imla":{"t":"الإِمْلاء","pg":null,"pts":[],"img":[]},"khatt":{"t":"الخَطُّ","pg":109,"pts":["كتابة عبارة."],"img":[["p1-109.webp",109]]},"taabir":{"t":"كِتابَةُ ثَلاثِ فِقْراتٍ","pg":110,"pts":["كتابة ثلاث فقرات."],"img":[]}},"listen":"تَخَلَّصْ مِنْ قَلَقِكَ"},{"id":"P2U1","part":2,"n":1,"sec":{"read":{"t":"الرَّحْمَةُ بِالأطْفالِ","pg":5,"paras":["قَلْبُ الأَبَوينِ مَفْطورٌ عَلى مَحَبَّةِ أَبْنائِهِمْ، فَالمَشاعِرُ الأَبَوِيَّةُ مَجْبولَةٌ عَلى حِمايَتِهِمْ، وَالرَّحْمَةِ بِهِمْ، وَالشَّفَقَةِ عَلَيْهِمْ، وَالاهْتِمامِ بِأَمْرِهِم، وَيُصَوِّرُ القُرْآنُ الكَريمُ تِلْكَ المَشاعِرَ الأَبَوِيَّةَ الصّادِقَةَ أَجْمَلَ تَصْويرٍ، فَتارَةً يَجْعَلُ الأَوْلادَ زينَةَ الحَياةِ الدُّنيا، كَما في قَوْلِهِ تَعالى: «الْمَالُ وَالْبَنُونَ زِينَةُ الْحَيَاةِ الدُّنْيَا» (الكهف: ٤٦)، وَتارَةً يَعُدُّهم نِعْمَةً عَظيمَةً تَسْتَحِقُّ الشُّكْرَ عَلَيها، كَما في قَوْلِهِ تَعالى: «وَأَمْدَدْنَاكُم بِأَمْوَالٍ وَبَنِينَ وَجَعَلْنَاكُمْ أَكْثَرَ نَفِيرًا» (الإسراء: ٦)","رَسَّخَتِ الشَّريعَةُ الإِسْلامِيَّةُ الرَّحْمَةَ بِالأَطْفالِ، وَحَضَّتِ الكِبارَ مِنْ آباءٍ، وَأُمَّهاتٍ، وَمُعَلِّمينَ، وَمَسْؤولينَ عَلى التَّحَلّي بِهذِهِ الأَخْلاقِ تُجاهَ الأَطْفالِ، وَدَليلُ ذلِكَ اهْتِمامُ النَّبِيِّ ﷺ بِمَوضوعِ الرَّحمَةِ بِالأَطْفالِ، وَالحُنُوِّ عَلَيْهِمْ، وَرِعايَتِهِمْ.","١- عَنْ أَنَسٍ -رضي الله عنه- قالَ: كانَ غُلامٌ يَهودِيٌّ يَخْدِمُ النَّبِيَّ ﷺ، فَمَرِضَ، فَأَتاهُ النَّبِيُّ يَعودُهُ، فَقَعَدَ عِنْدَ رَأْسِهِ، فَقالَ لَهُ: \"أَسْلِمْ\"، فَنَظَرَ إِلى أَبيهِ وَهُوَ عِنْدَهُ، فَقالَ: أَطِعْ أَبا القاسِمِ، فَأَسْلَمَ. فَخَرَجَ النَّبِيُّ ﷺ وَهُوَ يَقولُ: \"الحَمْدُ للهِ الَّذي أَنْقَذَهُ مِنَ النّارِ\". (رواه البخاريّ)","٢- عَنْ أَبي قَتادَةَ -رَضِيَ اللهُ عَنْهُ- عَنِ النَّبِيِّ ﷺ قالَ: \"إِنّي لَأَقومُ في الصَّلاةِ، أُريدُ أَنْ أُطَوِّلَ فيها، فَأَسْمَعُ بُكاءَ الصَّبِيِّ، فَأَتَجَوَّزُ في صَلاتي؛ كَراهِيَّةَ أَنْ أَشُقَّ عَلى أُمِّهِ\". (رواه البخاريّ)","٣- عَنْ عائِشَةَ -رَضِيَ اللَّهُ عَنْها- قالَتْ: قَدِمَ ناسٌ مِنَ الأَعْرابِ عَلى رَسولِ اللَّهِ ﷺ، فَقالوا: أَتُقَبِّلونَ صِبْيانَكُمْ؟ فَقالَ: \"نَعَمْ\"، قالوا: لَكِنّا وَاللَّهِ ما نُقَبِّلُ. فَقالَ رَسولُ اللَّهِ ﷺ: \"أَوَ أَمْلِكُ إِنْ كانَ اللَّهُ نَزَعَ مِنْ قُلوبِكُم الرَّحْمَةَ؟\". (متّفقٌ عَلَيْهِ)","٤- عَنْ عَبْدِ اللهِ بنِ شَدّادٍ -رَضِيَ اللَّهُ عَنْهُ- قالَ: بَيْنما رَسولُ اللهِ ﷺ يُصَلّي بِالنّاسِ، إِذْ جاءَهُ الحُسَينُ، فَرَكِبَ عُنُقَهُ وَهُوَ ساجِدٌ، فَأَطالَ السُّجودَ بَيْنَ النّاسِ، حَتّى ظَنّوا أَنَّهُ قَدْ حَدَثَ أَمْرٌ، فَلَمّا قَضى صَلاتَهُ، سَأَلوهُ عَنْ ذلِكَ، فَقالَ ﷺ: \"إِنَّ ابْني ارْتَحَلَني، فَكَرِهْتُ أَنْ أُعْجِلَهُ حَتّى يَقْضِيَ حاجَتَهُ\". (رواه النَّسائيّ)","٥- عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبيهِ، عَنْ جَدِّهِ قالَ: \"قالَ رَسولُ اللهِ ﷺ: \"لَيْسَ مِنّا مَنْ لَمْ يَرْحَمْ صَغيرَنا، ويُوَقِّرْ كَبيرَنا\". (رواه التِّرمذيّ)"],"voc":[["(الكهف","٤٦)"],["(الإ سراء","٦) ﷺ ﷺ ﷺ"],["أتّجَوَّزُ في صَلاتي","أسْتَعْجِلُ."],["ﷺ ارْتَحَلَني","رَكِبَ فَوْقَ عُنُقي."],["ﷺ يُوَقِّرْ","يَحْتَرِمْ."]],"img":[["p2-5.webp",5],["p2-6.webp",6],["p2-7.webp",7],["p2-8.webp",8],["p2-9.webp",9]]},"poem":{"t":"مِنْ أجْلِ الطُّفولَةِ","pg":10,"verses":[["وَسيماً مِنَ الأَطْفالِ لَوْلاهُ لَمْ أَخَفْ","عَلى الشَّيْبِ أَنْ أَنْأى وَأَنْ أَتغَرَّبا"],["تَوَدُّ النُّجومُ الزُّهْرُ لَو أَنَّها دُمًى","لِيَخْتارَ مِنْها المُتْرَفاتِ وَيَلْعَبا"],["وَعِنْدي كُنوْزٌ مِنْ حَنانٍ وَرَحْمَةٍ","نَعيمِيَ أَنْ يُغْرى بِهِنَّ وَيَنْهَبا"],["يَجورُ وَبَعْضُ الجَوْرِ حُلْوٌ مُحَبَّبٌ","وَلَمْ أرَ قَبْلَ الطِّفْلِ ظُلْماً مُحَبَّبا"],["وَيَغْضَبُ أَحْياناً وَيَرْضى وَحَسْبُنا","مِنَ الصَّفْوِ أَنْ يَرْضى عَلَيْنا وَيَغضَبا"],["وَإِنْ نالَهُ سَقْمٌ تَمَنَّيْتُ أَنَّني","فِداءٌ لَهُ كُنْتُ السَّقيمَ المُعَذَّبا"],["يَزِفُّ لَنا الأَعْيادَ عيداً إِذا خَطا","وَعيداً إِذا ناغى وَعيداً إِذا حَبا"],["كَزُغْبِ القَطا لَوْ أَنَّهُ راحَ صادِياً","سَكَبْتُ لَهُ عَيْني وَقَلْبي لِيَشْرَبا"],["وَأوثِرُ أَنْ يَرْوى وَيَشْبَعَ ناعِماً","وأَظْمَأَ في النُّعْمى عَلَيْهِ وَأَسْغَبا"],["يَنامُ عَلى أَشْواقِ قَلْبي بِمَهْدِهِ","حَريراً مِنَ الوَشْيِ اليَماني مُذَهَّبا"],["وَأُسْدِلُ أَجْفاني غِطاءً يُظِلُّهُ","وَيا لَيْتَها كانَتْ أَحَنَّ وَأَحْدَبا"],["وَيا رَبِّ مِنْ أَجْلِ الطُّفولَةِ وَحْدَها","أَفِضْ بَرَكاتِ السِّلْمِ شَرْقاً وَمَغْرِبا"],["وَصُنْ ضِحْكَةَ الأَطْفالِ يا رَبِّ إِنَّها","إِذا غَرَّدَتْ في مُوحِشِ الرَّمْلِ أَعْشَبا"]],"voc":[["-١ ناغى","كَرَّرَ مَقاطِع وَأصْواتاً مُحَبَّبَةً. -٢"],["زَغَبُ القَطا","الشُّعَيْراتُ -٣ الصُّفْرُ عَلى ريشِ طائِرِ -٤ القَطا."],["الصّادي","العَطْشانُ. -٥"],["أوثِرُ","أفَضِّلُ."],["-٦ النُّعْمى","النِّعْمَةُ."],["-٧ ناغى أسْغَبَ","دَخَلَ في المَجاعَةِ. -٨ كَزُغْبِ القَطا صادِيا"],["الوَشْيُ","الثِّيابُ -٩ وَأوثِرُ النُّعْمى وَأسْغَبا المُزَرْكَشَةُ المُلَوَّنَةُ."],["اليَماني","نِسْبَةً إِلى اليَمَنِ. -١٠ الوَشْيِ اليَماني"],["أسْدِلُ","أسْتُرُ وَأغَطّي. -١١ وَأسْدِلُ وَأحْدَبا"],["الأحْدَبُ","كَثيرُ العَطْفِ."],["-١٢ موحِشٌ","مُقْفِرٌ، خَالٍ مِنْ -١٣ مُوحِشِ مَظاهِرِ الحَياةِ."]],"img":[["p2-10.webp",10],["p2-11.webp",11],["p2-12.webp",12]]},"grammar":{"t":"رَفْعُ الفِعْلِ المُضارِعِ","pg":13,"pts":["يُرفع المضارع ما لم يُسبق بناصب أو جازم.","علامة رفعه الضّمّة ظاهرةً على الصّحيح الآخر، ومقدّرةً على المعتلّ الآخر (يدعو، يرمي، يسعى).","أو ثبوت النّون في الأفعال الخمسة (يكتبان، تكتبان، يكتبون، تكتبون، تكتبين)."],"img":[["p2-13.webp",13],["p2-14.webp",14]],"q":[["«الأطفالُ يحبّون اللّعب»: علامة رفع «يحبّون»:",["ثبوت النّون","الضّمّة","الواو","الفتحة"],0,"من الأفعال الخمسة."],["«يسعى الطّفلُ»: علامة رفع «يسعى»:",["الضّمّة المقدّرة","الضّمّة الظّاهرة","ثبوت النّون","السّكون"],0,""],["«ترحمُ الأمُّ صغيرَها»: علامة رفع «ترحم»:",["الضّمّة الظّاهرة","ثبوت النّون","المقدّرة","الفتحة"],0,""]]},"balagha":{"t":"مُراجَعَةٌ","pg":17,"pts":["مراجعة الجناس والسّجع."],"img":[["p2-17.webp",17]]},"imla":{"t":"الألِفُ الفارِقَةُ","pg":18,"pts":["الألف الفارقة: ألفٌ تُكتب ولا تُلفظ بعد واو الجماعة في الأفعال (كتبوا، لم يكتبوا، اكتبوا).","لا تُكتب بعد واو جمع المذكّر السّالم المضاف (معلّمو المدرسة)، ولا بعد الواو الأصليّة (يدعو، يرجو)."],"img":[["p2-18.webp",18]]},"khatt":{"t":"الخَطُّ","pg":21,"pts":["كتابة عبارة."],"img":[["p2-21.webp",21]]},"taabir":{"t":"كِتابَةُ فِقْراتٍ مُتَرابِطَةٍ","pg":21,"pts":["كتابة فقرات مترابطة."],"img":[["p2-21.webp",21]]}},"listen":"مِنْ سيرَةِ الحَبيبِ ﷺ"},{"id":"P2U2","part":2,"n":2,"sec":{"read":{"t":"سِنْدِيانَةٌ مِنْ فِلَسْطينَ","pg":23,"paras":["وَليدُ سَيْف كاتِبٌ، وَشاعِرٌ، وَقاصٌّ، وَباحِثٌ أكاديميٌّ فِلَسْطينيُّ الأصْلِ، مِنْ مَدينَةِ طولَكَرْمَ، وُلِدَ عامَ (١٩٤٨م)، حَصَلَ عَلى الدُّكْتوراه في اللُّغَةِ العَرَبِيَّةِ، وعَمِلَ مُحاضِراً في الجامِعَةِ الأرْدُنِيَّةِ، ثُمَّ تَفَرَّغَ لِلعَمَلِ الدِّرامِيِّ، فَأنْجَزَ عِدَّةَ أعْمالٍ، مِنْها: مُسَلْسَلُ (التَّغْريبَةُ الفِلَسْطينِيَّةُ)، وَمِنْ أشْهَرِ أعْمالِهِ: قَصائِدُ في زَمَنِ الفَتْحِ، وَتغريبَةُ بَني فِلَسْطينَ. وَالنَّصُّ الَّذي بَيْنَ أيْدينا سيرَةٌ ذاتِيَّةٌ مِنْ كِتابِهِ (الشّاهِدُ المَشْهودُ)، يَتَحَدَّثُ فيهِ عَنْ ذِكْرياتِهِ مَعَ جَدَّتِهِ، وَتَعَلُّقِهِ بِها، وَحُزْنِهِ عَلى وَفاتِها.",".. وَلا أذْكُرُ جَدَّتي إِلّا وَهِيَ جالِسَةٌ عَلى سَجّادَةِ الصَّلاةِ. المَصْنوعَةِ مِنْ جِلْدِ الغَنَمِ وَفَرْوَتِهِ، فَإِنْ لَمْ تَكُنْ في صَلاةٍ، فَهِيَ في ذِكْرِ اللّهِ بَيْنَ الصَّلاةِ وَالصَّلاةِ. وَكانَتْ مَلامِحُ وَجْهِها تَنِمُّ عَنْ سَكينَةٍ داخِلِيَّةٍ عَميقَةٍ، فَهِيَ في سَلامٍ دائِمٍ مَعَ رَبِّها، وَمَعَ نَفْسِها، وَمَعَ النّاسِ. فَكُنْتُ إذا قُلْتُ لَها: \"اللّهُ يُخلّيكِ يا سِتّي\"، انْتَفَضَتْ كَأنَّ أفْعى قَدْ لَدَغَتْها، وَتَقولُ: \" لا تَدْعُ عَلَيَّ يا حَبيبي\". فَأقولُ: \" إِنَّما أدْعو لَكِ يا سِتّي \"، فَتَقولُ: \" بَلْ هِيَ دَعْوَةٌ عَلَيَّ، ما حاجَتي بِطولِ العُمْرِ، وَأنا أتعَجَّلُ لِقاءَ رَبّي\"؟ لَمْ تَكُنْ تَقولُ ذلكَ تَبَرُّماً بِالحَياةِ، وَلا تَعَجُّلاً لِمَوْتٍ يُريحُ مِنْ شَقاءِ الدُّنْيا. وَلكِنَّها النَّفْسُ المُطْمَئِنَّةُ الَّتي اسْتوفَتْ مَهَمَّتَها في الحَياةِ، وَأصابَتْ حَظَّها مِنْها بِحُلْوِها وَمُرِّها.","عاشَتْ جَدَّتي دينَها في دُنْياها دونَ أنْ تَصْحَبَ مَعَها مُجَلَّداتِ الفِقْهِ وَالتَّفْسيرِ وَالحَديثِ، حَسْبُها مِنْ دينِها أنَّها شَهِدَتِ الشَّهادَتَيْنِ، وَاسْتَوْفَتْ أرْكانَ الإِسلامِ صَلاةً وَصِياماً وَحَجّاً وَزَكاةً، وَزادَتْ عَلى ذلِكَ مِنَ النَّوافِلِ ما اسْتطاعَتْ تَقَرُّباً وَاحْتِساباً، وَأمْسَكَتْ لِسانَها عَنِ الخَوْضِ في النّاسِ، فَلَمْ أسْمَعْها قَطُّ تَذْكُرُ أحَداً بِسوءٍ، وَكانَتْ مِنْ أحَنِّ النّاسِ عَلى الفَقيرِ وَالضَّعيفِ وَاليَتيمِ وَالأرْمَلَةِ. فَإذا عُصِرَ زَيْتونُ أرْضِنا في القَرْيَةِ، وَجيءَ بِهِ إِلى بَيْتِنا في طولَكَرْمَ، لَمْ نَأْكُلْ مِنْهُ حتّى تُخْرِجَ مِنْهُ حَقَّ العائِلِ وَالفَقيرِ.","عَلى مِثالِ الأمِّ الفِلَسْطينِيَّةِ، كانَتْ جَدَّتي السِّنْدِيانَةَ القَديمَةَ المورِفَةَ الَّتي تَلْتَفُّ حَوْلَها الأسْرَةُ، وَتَسْتَظِلُّ بِظِلِّها. وَكانَ احْتِرامُ أبْنائِها لَها نَهْجاً. وَكانَ والِدي أحَدَّهُم مِزاجاً، وَلكِنَّهُ كانَ وَقّافاً عِنْدَ أمِّهِ إِذا نَهَتْهُ عَنْ أمْرٍ يَهُمُّ بِهِ إِذا غَضِبَ، أوْ أمَرَتْهُ بِقَبولِ شَيْءٍ قَدْ امْتَنَعَ عَنْهُ. وَما كانَتْ تَفْعَلُ ذلكَ بِلَهْجَةِ الأمِّ المُتَحَكِّمَةِ، فَذلِكَ أبْعَدُ شَيْءٍ عَنْ شَخَصِيَّتِها. كانَ يَكفي أنْ تَتَدَخَّلَ بِرَأْيِها، فَيَقِفَ عِنْدَهُ. وَبِالطَّبْعِ، كُنّا نُدْرِكُ ذلِكَ إِذْ كُنّا صِغاراً، فَنَعوذُ بِها مِنْ غَضَباتِ الوالِدِ، أو نَسْتَشْفِعُ بِها لِحاجَتِنا عِنْدَهُ.","وَلَكَمْ كُنْتُ أحِبُّ أنْ أسْتَلْقِيَ عِنْدَها، فَأسْنِدَ رَأْسي إِلى رُكْبَتِها، وَيَحْلو لَها أنْ تُمَسِّدَ شَعْرِيَ الخَشِنَ، وَتَرْقِيَني بِالدُّعاءِ وَالذِّكْرِ. فَإنْ ألَمَّ بِي عارِضٌ مِنْ مَرَضٍ أوْ غَيْرِهِ، كانَتْ تَفْعَلُ ذلِكَ وَفي كَفِّها قَبْضَةٌ مِنْ مِلْحٍ، فَإذا فَرَغَتْ مِنَ الرُّقْيَةِ، نَثَرَتْ المِلْحَ في الهَواءِ؛ لِأنّها تَعْتَقِدُ أنَّهُ امْتَصَّ مِنْ جِسْمي السّوءَ العارِضَ.","وَعَلى مِثالِ الجَدَّةِ المَأْلوفِ، كانَتْ جَدَّتي مُسْتَوْدَعَ الحِكاياتِ الشَّعْبِيَّةِ الَّتي نُسَمّيها في فِلَسْطينَ \" الخُرّيفِيّاتْ \" وَكُنّا نُلِحُّ عَلَيْها أنْ تُعيدَ عَلَيْنا قَصَّ الحِكايَةِ لِلمَرَّةِ الألْفِ دونَ أنْ نَمَلَّ. وَفي كُلِّ مَرَّةٍ جَديدَةٍ كُنّا نَذْهَبُ مَعَ الحِكايَةِ إِلى تُخومٍ سِحْرِيَّةٍ بَعيدَةٍ، وَلا يُخْفِقُ القَصُّ المَكْرورُ في أنْ يَخْلُقَ فينا عُنْصُرَ التَّوَتُّرِ وَالتَّشْويقِ في انْتِظارِ أنْ تَنْجَلِيَ حَقيقَةُ المَكْرِ أخيراً، فَيَنْتَصِفَ المَظْلومُ مِنَ الظّالِمِ.","هَزَّني نَبَأ وَفاةِ جَدَّتي، وَحاوَلْتُ أنْ أكْتُبَ حُزْني، وَلكِنَّهُ كانَ أكْبَرَ مِنَ العِبارَةِ، وَلَيْسَ يَسَعُ تِلْكَ السِّنْدِيانَةَ العَظيمَةَ إِلّا قَلْبي وَوِجْداني وَذاكِرَتي الَّتي تَحْتَضِنُ إِرْثَها الدّائِمَ. غايَةُ ما اسْتَطَعْتُ أنْ أفْعَلَهُ وَفاءً لِذِكْراها بَعْدَ حينٍ مِنَ الدَّهْرِ، أنّي ألْقَيْتُ بَعْضَ مَلامِحِ شَخْصِيَّتِها عَلى شَخْصِيَّةِ \"أمِّ أحْمَدَ\" في\"التَّغْريبَةِ الفِلَسْطينِيَّةِ\". وَلَمّا كانَ السِّنْدِيانُ الفِلَسْطينِيُّ مُتَشابِهاً رَأى المُشاهِدُ الفِلَسْطينِيُّ في \"أمِّ أحْمَدَ\" مِثالَ الأمِّ الفِلَسْطينِيَّةِ. تِلْكَ الَّتي سَوْفَ نَراها فيما بَعْدُ تَحْتَضِنُ جِذْعَ زَيْتونَةٍ قَديمَةٍ، كَما تَحْتَضِنُ وَلَداً يُوشِكُ أنْ يَتَخَطَّفَهُ الغُزاةُ \"المارّونَ بَيْنَ الكَلِماتِ العابِرَةِ\"، وَإِنِ اسْتَباحوا إِلى حينٍ لَحْمَنا وَدَمَنا وَقَمْحَنا."],"voc":[["التَّبَرُّمُ","الضّيقُ وَالضَّجَرُ."],["أمْسَكَتْ لِسانَها","امْتَنَعَتْ عَنِ الكَلامِ الفاحِشِ عَلى النّاسِ."],["السِّنْدِيانَةُ","شَجَرَةٌ عَظيمَةٌ مِنْ شَجَرِ الأحْراجِ."],["المورِفَةُ","الطَّويلَةُ المُمْتَدَّةُ."],["الوَقّافُ","المُتَأنّي، غَيْرُ المُتَعَجِّلِ."],["تُمَسِّدُ","تَمْسَحُ."],["تَرْقيني","تُعَوِّذُني بِقَوْلِها"],["التُّخومُ","مُفْرَدُها تُخْمٌ، وَهُوَ الحَدُّ الفاصِلُ بَيْنَ أرْضَيْنِ. من كتاب"]],"img":[["p2-23.webp",23],["p2-24.webp",24],["p2-25.webp",25],["p2-26.webp",26],["p2-27.webp",27]]},"grammar":{"t":"نَصْبُ الفِعْلِ المُضارِعِ","pg":28,"pts":["يُنصب المضارع إذا سُبق بأحد أحرف النّصب: أنْ، لنْ، كي، لام التّعليل، حتّى، فاء السّببيّة.","علامة نصبه الفتحة ظاهرة (لن يتركَ) أو مقدّرة على الألف (لن يسعى)، وحذف النّون في الأفعال الخمسة (لن يتركوا)."],"img":[["p2-28.webp",28],["p2-29.webp",29]],"q":[["«لن يتخلّى الفلسطينيُّ عن أرضه»: علامة نصب «يتخلّى»:",["الفتحة المقدّرة","الفتحة الظّاهرة","حذف النّون","السّكون"],0,""],["«جاؤوا ليزرعوا السّنديان»: علامة النّصب:",["حذف النّون","الفتحة","السّكون","الياء"],0,""],["أيّها ليس من أحرف النّصب؟",["لم","لن","كي","أن"],0,"«لم» حرف جزم."]]},"balagha":{"t":"الطِّباقُ","pg":32,"pts":["الطّباق: الجمع بين اللّفظ وضدّه.","طباق الإيجاب: الجمع بين لفظين متضادّين مثبتين (اللّيل والنّهار).","طباق السّلب: الجمع بين فعلين من مصدر واحد أحدهما مثبت والآخر منفيّ (يعلمون، لا يعلمون)."],"img":[["p2-32.webp",32]]},"imla":{"t":"اخْتِبارِيٌّ","pg":34,"pts":["إملاء اختباريّ."],"img":[["p2-34.webp",34]]},"khatt":{"t":"الخَطُّ","pg":35,"pts":["كتابة عبارة."],"img":[["p2-35.webp",35]]},"taabir":{"t":"فَنُّ التَّلْخيصِ","pg":36,"pts":["فنّ التّلخيص: قراءة النّصّ، تحديد الأفكار الرّئيسة، الصّياغة بأسلوب الطّالب، الإيجاز."],"img":[]}},"listen":"ذاكِرَةُ الفِلَسْطينِيِّ"},{"id":"P2U3","part":2,"n":3,"sec":{"read":{"t":"كَرامَةُ الكَرامَةِ","pg":40,"paras":["بَعْدَ هَزيمَةِ عامِ ألْفٍ وتِسْعِمِئَةٍ وسَبْعَةٍ وسِتينَ، وَاحْتِلالِ الضِّفَةِ الغَرْبِيَّةِ وغزَّةَ، وسَيْطَرَةِ الاحْتلالِ الصِّهْيونِيِّ على فِلَسْطينَ جَميعِها، شَعَرَتِ الأمَّةُ العَرَبِيَّةُ والإِسْلامِيَّةُ بِالقَهْرِ والخَيْبَةِ والخِذْلانِ، فَجاءَتْ مَعرَكَةُ الكَرامَةِ في العامِ التّالي، فَكَسَرَتْ شَوْكَةَ الجَيْشِ الصِّهْيونِيِّ؛ ما أعادَ لِلأمَّةِ نَوْعاً مِنَ الكَرامَةِ والثِّقَةِ بالنَّفْسِ.","الكَرامَةُ بَلدَةٌ أرْدُنِيَّةٌ تَتَرَبّعُ بِمُحاذاةِ الجِهَةِ الشَّرْقِيَّةِ مِنْ نَهْرِ الأرْدُنِّ. تَجَمَّعَتْ فيها قُوّاتُ الفِدائِيّينَ الفِلَسْطينِيّينَ بَعْدَ حَرْبِ عامِ ألْفٍ وَتِسْعِمِئَةٍ وَسَبْعَةٍ وَسِتينَ؛ لِتَجْعَلَها قاعِدَةَ انْطِلاقٍ لِعَمَلِيّاتِها الفِدائِيَّةِ ضِدَّ الاحْتِلالِ الصِّهْيونِيِّ.","مَلَأ الرُّعْبُ قُلوبَ الصَّهايِنَةِ بِسَبِبِ التَّواجُدِ الفِدائِيِّ الفِلَسْطينِيِّ في مَنْطِقَةِ الكَرامَةِ، فَوَضَعَتْ حُكومَةُ العَدُوِّ أهْدافًاً مُحَدَّدَةً لِإِبْعادِ الخَطَرِ عَنْها، تَمَثّلَتْ في إِنْهاءِ العَمَلِ الفِدائِيِّ الفِلَسْطينِيِّ في الأغْوارِ الأرْدُنِّيَّةِ، وَمُعاقَبَةِ الأرْدُنِّ عَلى احْتِضانِهِ الفِدائِيّينَ، وَاحْتِلالِ مُرْتَفَعاتِ السَّلْطِ وَتَحْويلِها إِلى حِزامٍ أمْنِيٍّ لِكِيانِهِمْ.","فَجْرَ يَوْمِ الواحِدِ وَالعِشْرينَ مِنْ آذارَ سَنَةَ ألْفٍ وَتِسْعِمِئَةٍ وَثَمانٍ وَسِتّينَ لِلْميلادِ، زَحَفَتْ قُوّاتُ الاحْتِلالِ الصِّهْيونِيِّ بِأسْلِحَتِها البَرِّيَّةِ وَالجَوِّيَّةِ، شَرْقيَّ نَهْر الأرْدُنِّ؛ لِتَحْقيقِ أهْدافِها الَّتي وَضَعَتْها. اعْتَقَدَ وَزيرُ الحَرْبِ في حُكومَةِ العَدُوِّ آنَذاكَ أنَّها مَهَمَّةٌ سَهْلَةٌ، سَتُحْسَمُ خِلالَ ساعاتٍ قَليلَةٍ، وَأنَّ الحَرْبَ سَتَكونُ نُزْهَةً.","دَخَلَ الصَّهايِنَةُ الكَرامَةَ، وَاشْتَبَكوا مَعَ الجُنودِ الأرْدُنِيّينَ وَالفِدائِيّينَ الفِلَسْطينِيّينَ بِالسِّلاحِ الأبْيَضِ ، وَلَمْ تَكُنِ المَعْرَكَةُ سَهْلَةً، كَما خُيِّلَ لَهُمْ، بَلْ كانَتْ مَلْحَمَةً سَطَّرَ فيها مُقاتِلو الضِّفَّتَيْنِ بُطولاتٍ خارِقَةً، فَلَمْ يَسْتَطِعِ العَدُوُّ تَحْقيقَ أهْدافِهِ الَّتي حَلَمَ بِها قَبْلَ المَعْرَكَةِ، فَأيْقَنَ أنَّ إِرادَةَ المُقاتِلينَ راسِخَةٌ رُسوخَ جِبالِ السَّلْطِ والقُدْسِ.","أنْزَلَتِ الطّائِراتُ العَمودِيَّةُ المِظَلِّيّينَ خَلْفَ خُطوطِ الفِدائِيّينَ، فَبَلَغَ عَدَدُ قُوّاتِ الاحْتِلالِ المُهاجِمَةِ نَحْوَ خَمْسَةَ عَشَرَ ألْفَ جُنْدِيٍّ، بَيْنَما ضَمَّتِ القُوّاتُ العَرَبِيَّةُ نَحْوَ ثَلاثِمِئَةِ فِدائِيٍّ فِلَسْطينِيٍّ أبْلَوْا بَلاءً حَسَناً في المُقاوَمَةِ وَصَدِّ العُدْوانِ، تَوَزَّعوا أسوداً عَلى الجِبالِ وَالكُهوفِ القَريبَةِ. إِضافَةً إِلى كَتيبةِ المِدْفَعِيَّةِ الأرْدُنِيَّةِ بِقِيادَةِ اللِّواءِ مَشْهورِ حَديثَةَ الجازي، الَّتي أمْطَرَتِ العَدُوَّ بِوابِلِ قَذائِفِها، وَأظْهَرَتْ بَسالَةً في التَّصَدّي لِلْمُعْتَدينَ الصَّهايِنَةِ الّذينَ جُنَّ جُنونُهُمْ لِما رَأوْهُ مِنْ شَجاعَةٍ خارِقَةٍ، وَتَضْحِياتٍ لَمْ تَخْطُرْ لَهُمْ عَلى بالٍ، فَحاوَلوا إِحْراقَ المَنْطِقَةِ بِكُلِّ ما يَمْتَلِكونَ مِنْ عُنْجُهِيَّةٍ وَوَحْشِيَّةٍ ماكِرَةٍ.","خاضَ الفِدائِيّونَ، بالرَّغْمِ مِنْ قِلَّةِ أسْلِحَتِهِمْ، وَبُدائِيَّتِها، مَعْرَكَةَ الكَرامَةِ بِنارٍ كَثيفَةٍ مِنَ القَنابِلِ اليَدَوِيَّةِ، وَالسِّلاحِ الأبْيَضِ، فَهَوَتْ خَناجِرُ الفِدائِيّينَ عَلى رِقابِ جُنودِ العَدُوِّ، وَحَزَّمَ بَعْضُ الفِدائِيّينَ أنْفُسَهُمْ بِأحْزِمَةٍ مُتَفَجِّرَةٍ، فَصارَتْ أجْسادُهُم نيراناً حارِقَةً للدَّبّاباتِ الصِّهْيونِيَّةِ. فَكانَتْ حَرْبَ عِصاباتٍ وَشَوارِعَ ضِدَّ جَيْشٍ نِظامِيٍّ صِهْيونِيٍّ، وَامْتَدَّتِ المَعْرَكَةُ مُنْذُ ساعاتِ الصَّباحِ الباكِرِ حَتّى ساعاتِ المَساءِ، دَمَّرَتْ خِلالَها القُوَّاتُ الغازِيَةُ ثَلاثَةَ أرْباعِ مَباني قَرْيَةِ الكَرامَةِ.","اضْطُرَّ الصَّهايِنَةُ أمامَ صُمودِ المُقاتِلينَ وَضَراوَةِ مُقاوَمَتِهِمْ إِلى طَلَبِ وَقْفٍ سَريعٍ لِإِطْلاقِ النّارِ؛ حِفاظاً عَلى سَلامَتِهِمْ، لكِنَّ القائِدَ الأرْدُنِّيَّ مَشْهورَ حَديثَةَ وَرِفاقَهُ رَفَضوا الطَّلَبَ ما دامَ هُناكَ صِهْيونِيٌّ واحِدٌ يُدَنِّسُ أرْضَ الكَرامَةِ. وَتَحْتَ وابِلٍ كَثيفٍ مِنْ نيرانِ الفِدائِيّينَ وَالجَيْشِ الأرْدُنِّيِّ وَتحْتَ جُنْحِ الظَّلامِ، بَدَأتِ القُوّاتُ الغازِيَةُ تُلَمْلِمُ جُثَثَ قَتْلاها وَجَرْحاها تَمْهيداً لِلْجَلاءِ، وَتَتْرُكُ وَراءَها بَعْضَ الجُثَثِ وَالأشْلاءأِ؛ لِتَكونَ طَعاماً لِوُحوشِ الأرْضِ وَكَواسِرِ السَّماءِ. وَانْدَحَرَتْ تَجُرُّ أذْيالَ الهَزيمَةِ وَالخَيْبَةِ.","اعْتَرَفَ الاحْتِلالُ الصِّهْيونِيُّ بِمَقْتَلِ العَشَراتِ مِنْ جُنودِهِ، وَجَرْحِ المِئاتِ، وَجَرى نَقْلُ عَشَراتِ الدَّبّاباتِ الصِّهْيونِيَّةِ المَعْطوبَةِ عَلى شاحِناتِ نَقْلٍ كَبيرَةٍ إِلى الأرْضِ المُحْتَلَّةِ، وَتَرَكوا بَعْضاً مِنْها في ساحَةِ المَعْرَكَةِ. وَلَنْ نَنْسى صورَةَ جُنْدِيٍّ صِهْيونِيٍّ مُحْتَرِقٍ مُكَبَّلٍ مِنْ قائِدِهِ بِسَلاسِلَ غَليظَةٍ داخِلَ دَبّابَتِهِ؛ خَشْيَةَ الهَرَبِ. وَسَحَبَ الأبْطالُ بَعْضَ الدَّبّاباتِ إِلى عَمّانَ؛ لِتَكونَ دُمىً يَلْعَبُ بِها الأطْفالُ المُبْتَهِجونَ بِالنَّصْرِ.","أعادَتْ مَعْرَكَةُ الكَرامَةِ جُزْءاً مِنَ الكَرامَةِ العَرَبِيَّةِ الَّتي هُدِرَتْ في عُدْوانِ الاحْتِلالِ الصِّهْيونِيِّ عَلى ثَلاثِ دُوَلٍ عَرَبِيَّةٍ، هِيَ: مِصْرُ، وَسوريا، وَالأرْدُنُّ في حُزَيْرانَ عامَ ألْفٍ وَتِسْعِمِئَةٍ وَسَبْعَةٍ وَسِتّينَ، وتَسابَقَ الكَثيرونَ مِنْ أبْناءِ فِلَسْطينَ وَالأمَّةِ العَرَبِيَّةِ؛ لِيَنالوا شَرَفَ الالتِحاقِ بالثَّوْرَةِ الفِلَسْطينِيَّةِ، وَأسْقَطَتِ الكَرامَةُ أسْطورَةَ الجَيْشِ الصِّهْيونِيِّ الَّذي لا يُقْهَرُ، وَلَقَّنَتِ العَدُوَّ دَرْساً لَنْ يَنْساهُ عَلى مَدى الأيّامِ، وَأصْبَحَ العالَمُ كُلُّهُ يَسْمَعُ عَنْ تَضْحِياتِ الشَّعْبِ الفِلَسْطينِيِّ لاسْتِرْدادِ حُقوقِهِ وَتَحْريرِ أرْضِهِ.","المَلْحَمَةُ: عَمَلٌ قَصَصِيٌّ لَهُ قَواعِدُ وَأصولٌ، يُشادُ فيهِ بِذِكْرِ الأبْطالِ وَالمُلوكِ، وَيَقومُ عَلى الخَوارِقِ وَالأساطيرِ. قَدْ يَكونُ شِعْراً، وَقَدْ يَكونُ نَثْراً.","الأسْطورَةُ:أ قِصَّةٌ وَقَعَتْ في غابِرِ الزَّمانِ لكِنْ تَمَّ تَضْخيمُها والمُبالَغَةُ فيها إِلى أنْ صارَتْ خَيالِيَّةً."],"voc":[["المُحاذاةُ","المُوازاةُ، وَالمُقابَلَةُ."],["السِّلاحُ الأبْيَضُ","كِنايَةٌ عَنِ القِتالِ بِالسَّكاكينِ وَالخَناجِرِ وما شابَهَها."],["المَلْحَمَةُ","المَعْرَكَةُ الشَّديدَةُ الَّتي يَكْثُرُ فيها القَتْلُ بَيْنَ المُتَحارِبينَ."],["أبْلَوْا بَلاءً","اجْتَهَدوا اجْتِهاداً كَبيراً."],["الوابِلُ","المَطَرُ الشَّديدُ، وَهِيَِ هُنا بِمَعْنى القَصْفِ المُتَواصِل"],["العُنْجُهِيَّة","الكِبْرُ، وَالتَّعالي."],["الضَّراوَةُ","الشِّدَّةُ."],["الجَلاءُ","الرَّحيلُ عَنِ المَكانِ."],["الأشْلاءُ","أعْضاءُ الإِنْسانِ بَعْدَ التَّفَرُّقِ."],["(مِنْ كِتابِ","مَعْرَكَةُ الكَرامَةِ، اللواءُ محمود النّاطور، بِتَصَرُّفٍ)"]],"img":[["p2-40.webp",40],["p2-41.webp",41],["p2-42.webp",42],["p2-43.webp",43],["p2-44.webp",44]]},"poem":{"t":"في ذِكْرى مَعْرَكَةِ الكَرامَةِ","pg":45,"verses":[["كَمْ قَرْيَةٍ في ثَنايا الكَوْنِ مُهْمَلَةٍ","سادَتْ وَبادَتْ بِلا ذِكْرٍ وَلا نَسَبِ"],["لكِنَّ قَرْيَتَنا في الدَّهْرِ خالِدَةٌ","قَدْ سَطَّرَتْ مَجْدَها بِالنّارِ لا الخُطَبِ"],["حينَ الغُزاةُ عَلى الأَغْوارِ قَدْ زَحَفوا","بِجَحْفَلٍ بالَغوا في حَشْدِهِ، لَجِبِ"],["كانَتْ جَميعُ بِلادِ العُرْبِ نائِمَةً","كَعُصْبَةِ الكَهْفِ لَمْ تَأْبَهْ لِمُغْتَصِبِ"],["وَلَمْ يَكُنْ غَيْرُ أُرْدُنِّ الفِدا يَقِظاً","ثَبْتَ الفُؤادِ أَمامَ الرَّوْعِ لَمْ يَهَبِ"],["فَنافَحَتْهُم أُسودُ الضَّفَّتَيْنِ مَعاً","يُدافِعونَ عَنِ الإِسْلامِ وَالعَرَبِ"],["وَجَدَّدوا ذِكْرى (بابِ الوادِ) مَلْحَمَةً","مِنَ الإِخاءِ مَدى الأَجْيالِ وَالحِقَبِ"],["كانوا أَشاوِسَ في الهَيْجاءِ ما فَزِعوا","وَلا أُفَرِّقُ في الأَلْقابِ وَالرُّتَبِ"],["ساقَ العِدا جُنْدَهُمْ كُرْهاً وليْسَ بِهِمْ","شَوْقٌ إلى الحَرْبِ مِنْ خَوْفٍ وَمِنْ رَهَبِ"],["زَجّوا بِهِمْ لُقْمَةً لِلمَوْتِ سائِغَةً","جاءَتْ لِقَوْمٍ لِنَيْلِ الثَّأْرِ في سَغَبِ"],["حَيْثُ الجِراحاتُ كانَتْ بَعْدُ دامِيَةً","وَمِنْ (حُزَيْرانَ) لَمْ تَبْرَأْ وَلَمْ تَغِبِ"],["ظَنّوا الكَرامَةَ كَنْزاً لا سِياجَ لَهُ","وَما عَلَيْنا سِوى التَّبْكيرِ في الهَرَبِ"],["فَإِذْ بِهِمْ دونَ جُنْدٍ مِنْ هِوايَتِهِمْ","صُنْعُ الشَّهادَةِ إِبْداعاً بِلا تَعَبِ"],["عادَ الغُزاةُ خِفافاً دونَما نَفَلٍ","إِلّا بِخُفَّيْ (حُنَيْنٍ)، تَبَّ مِنْ سَلَبِ"],["وَأَوْرَثونا سِلاحاً كانَ يَحْمِلُهُمْ","عَلى الغُرورِ وَما صانوهُ مِنْ عَطَبِ"],["فَكُلُّ دَبّابَةٍ أَطْفالُنا انْتَصَبوا","في بُرْجِها قَدْ رَأَوْها زينَةَ اللُّعَبِ"],["بورِكْتَ يا شَهْرَ (آذارٍ) لَنا عَلَماً","يُكافِئُ الأُمَّ عَمّا كانَ مِنْ نَصَبِ"],["فَنَحْنُ لِلْأَرْضِ قَدَّمْنا هَدِيَّتَنا","عِقْداً مِنَ الشُّهَداءِ الغُرِّ، لا الذَّهَبِ"]],"voc":[],"img":[["p2-45.webp",45],["p2-46.webp",46],["p2-47.webp",47]]},"grammar":{"t":"جَزْمُ الفِعْلِ المُضارِعِ","pg":48,"pts":["يُجزم المضارع إذا سُبق بأحد أحرف الجزم: لم، لمّا، لام الأمر، لا النّاهية.","علامة جزمه السّكون في الصّحيح الآخر، وحذف حرف العلّة في المعتلّ الآخر (لم يسعَ، لم يدعُ، لم يرمِ)، وحذف النّون في الأفعال الخمسة."],"img":[["p2-48.webp",48],["p2-49.webp",49]],"q":[["«لم ينسَ الأبطالُ الكرامة»: علامة جزم «ينسَ»:",["حذف حرف العلّة","السّكون","حذف النّون","الفتحة"],0,""],["«لا تتأخّروا»: علامة الجزم:",["حذف النّون","السّكون","حذف حرف العلّة","الضّمّة"],0,""],["«لمّا يحضرْ»: «لمّا» حرف:",["نفي وجزم","نصب","جرّ","استفهام"],0,""]]},"balagha":{"t":"تَدْريباتٌ عَلى الطِّباقِ","pg":52,"pts":["تدريبات على الطّباق بنوعيه."],"img":[["p2-52.webp",52]]},"imla":{"t":"أخْطاءٌ شائِعَةٌ في كِتابَةِ الألِفِ","pg":53,"pts":["يُبنى فعل الأمر المعتلّ الآخر على حذف حرف العلّة (اسعَ، ادعُ، ارمِ)، ولا تُكتب الألف أو الواو أو الياء في آخره."],"img":[["p2-53.webp",53]]},"khatt":{"t":"الخَطُّ","pg":54,"pts":["كتابة بيت."],"img":[["p2-54.webp",54]]},"taabir":{"t":"تَطْبيقٌ عَمَلِيٌّ عَلى التَّلْخيصِ","pg":55,"pts":["تطبيق عمليّ على التّلخيص."],"img":[]}},"listen":"قَلْعَةُ شَقيفٍ"},{"id":"P2U4","part":2,"n":4,"sec":{"read":{"t":"زِراعَةُ الوَرْدِ في غَزَّةَ","pg":57,"paras":["تُشَكِّلُ صادِراتُ الوَرْدِ في غَزَّةَ مَصْدَراً اقتِصادِيّاً، يُسْهِمُ بِنِسْبَةٍ لا بَأْسَ بِها في الدَّخْلِ القَوْمِيِّ، إِلى جانِبِ الرِّسالَةِ الَّتي تَحْمِلُها زِراعَةُ الوَرْدِ، في هذا الجُزْءِ النّابِضِ في قَلْبِ الوَطَنِ. هذِهِ الرِّسالَةُ المُحَمَّلَةُ بِمَعاني التَّجَذُّرِ، وَالإِصْرارِ عَلى الحَياةِ بِأمْنٍ وَسَلامٍ، عَلى الرَّغْمِ مِنَ الوَيْلاتِ وَالمُعاناةِ وَالحِصارِ .","وَفي هذا المَقالِ نُسَلِّطُ الضَّوْءَ عَلى قِطاعِ زِراعَةِ الوَرْدِ في غَزَّةَ، وَما يَتَعَلَّقُ بِهذا القِطاعِ مِنْ حَيْثُ: دَوْرُهُ في الاقْتِصادِ الوَطَنِيِّ، وَالصُّعوباتُ الدّاخِلِيَّةُ وَالخارِجِيَّةُ الَّتي تُهَدِّدُ اسْتِمْرارَهُ، وَالآلِيّاتُ الكَفيلَةُ بِدَعْمِ هذا القِطاعِ وَتَطويرِهِ.","وَالوَرْدُ في أعْلى الغُصونِ كَأنَّهُ مَلِكٌ تَحُفُّ بِهِ سَراةُ جُنودِه الوَرْدُ لُغَةُ الحَياةِ وَالإِحْساسِ، وَصِلَةُ الألْفَةِ وَالمَحَبَّةِ بَيْنَ النّاسِ، وَهُوَ سَفيرُ القُلوبِ، وَرَسولُ البَسْمَةِ، وَبِالوَرْدِ تُزْهِرُ ألْوانُ الحَياةِ بَعْدَ بُؤْسٍ أوْ وَجَعٍ.","عُرِفَتْ زِراعَةُ الوَرْدِ في فِلَسْطينَ مُنْذُ القِدَمِ، إِلّا أنَّها اقْتَصَرَتْ عَلى الزِّراعَةِ المَنْزِلِيَّةِ، وَالحَدائِقِ العامَّةِ، أمّا زِراعَةُ الوَرْدِ لِأغْراضِ التِّجارَةِ، فَقَدْ عُرِفَتْ في غَزَّةَ عَلى وَجْهِ الخُصوصِ في بِدايَةِ التِّسْعينِيّاتِ مِنَ القَرْنِ الماضي، وَاتَّسَعَ نِطاقُها في عامِ (١٩٩٨م) إِذْ وَصَلَتْ إِلى أكْثَرَ مِنْ مِئَةِ مَشْروعٍ عَلى مِساحَةٍ تُقَدَّرُ بِنَحْوِ ألْفٍ وَمِئَتَيْ دونُمٍ، مُعْظَمُها يَتَرَكَّزُ في بَيْتَ لاهيا في أقْصى شَمالِ القِطاعِ، وَكَذلِكَ في رَفَحٍ أقْصى جَنوبِهِ، وَقَدْ ساعَدَ عَلى زِراعَةِ الوَرْدِ؛ اعْتِدالُ جَوِّ قِطاعِ غَزَّةَ، وَنَوْعِيَّةُ تُرْبَتِهِ، وَأراضيهِ السّاحِلِيَّةُ المُناسِبَةُ.","تَبْدَأ زِراعَةُ شَتَلاتِ الوَرْدِ الأصْلِيَّةِ (الشَّتَلاتِ الأمِّ) في كُلٍّ مِنْ: هولَنْدا، وَإيطالْيا، وَألْمانْيا، ثُمَّ تُنْقَلُ هذِهِ الشَّتَلاتُ إِلى قِطاعِ غَزَّةَ، حَيْثُ تُزْرَعُ هُناكَ في دَفيئاتٍ خاصَّةٍ، وَتَسْتَغْرِقُ زِراعَتُها وَقَطْفُها أحَدَ عَشَرَ شَهْراً.","تُعَقَّمُ الوُرودُ بَعْدَ قَطْفِها بِمَحْلولٍ مُخَصَّصٍ، وَبَعْدَ ذلِكَ تُحْفَظُ في ثَلّاجاتٍ مُدَّةَ يَوْمَيْنِ، قَبْلَ نَقْلِها بِوَساطَةِ شاحِناتٍ مُخَصَّصَةٍ وَمُزَوَّدَةٍ بِغُرْفَةٍ مُبَرِّدَةٍ؛ كَيْ تُحافِظَ عَلى نَضارَةِ الزَّهْرَةِ، إِلى حينِ وُصولِها إِلى البَلَدِ المُسْتَوْرِدِ، وَتُكَلِّفُ زِراعَةُ دونُمِ الوَرْدِ الواحِدِ خَمْسَةَ آلافِ دينارٍ تَقْريباً، وَيَبْقى الرَّقْمُ مُرَشَّحاً لِلزِّيادَةِ في حالِ تَعَرَّضَتِ الأرْضُ الزِّراعِيَّةُ لِأوْبِئَةٍ ، أوْ لِعَوامِلِ طَقْسٍ غَيْرِ مُناسِبَةٍ لِلشَّتَلاتِ، وَيَحْتاجُ دونُمُ الوَرْدِ الواحِدِ يَوْمِيّاً أرْبَعَةَ أكْوابٍ مِنَ المِياهِ العَذْبَةِ.","وَبِالرَّغْمِ مِنَ التَّكاليفِ الباهِظَةِ الَّتي يَتَكَبَّدُها زارِعو الوَرْدِ، إِلّا أنَّهُ يَظَلُّ مِنَ المَوارِدِ الإِنْتاجيَّةِ الزِّراعِيَّةِ المُهِمَّةِ في قِطاعِ غَزَّةَ؛ إِذْ يُسْهِمُ بِحَوالَيْ خَمْسَةٍ وَعِشْرينَ مِلْيونَ دولارٍ سَنَوِيّاً مِنَ الدَّخْلِ القَوْمِيِّ، وَيَبْلُغُ عَدَدُ العُمّالِ الَّذينَ يَعْمَلونَ في إنْتاجِ الزُّهورِ أرْبَعَةَ آلافٍ وَخَمْسِمِئَةِ عامِلٍ.","لَقَدْ شَهِدَتْ زِراعَةُ الوَرْدِ في سَنَواتٍ سابِقَةٍ نَجاحاً كَبيراً، بَعْدَ وُصولِها إِلى الأسْواقِ الأوروبِيَّةِ، حَيْثُ كانَ قِطاعُ غَزَّةَ يُصَدِّرُ حَوالَيْ سِتّينَ مِلْيونَ زَهْرَةٍ سَنَوِيّاً إِلى أوروبّا، لكِنَّها لَمْ تَدُمْ طَويلاً إِذْ سَرْعانَ ما ذَبُلَتْ أمامَ التَّحَدِّياتِ الَّتي واجَهَتِ المُزارِعينَ، فَتَراجَعَتْ هذِهِ الكَمِّيَّةُ إِلى أنْ أصْبَحَتْ لا تَتَجاوَزُ أرْبَعَةَ مَلايينِ زَهْرَةٍ في العامِ (٢٠١٢م). وَيُزْرَعُ في قِطاعِ غَزَّةَ أكْثَرُ مِنْ مِئَةِ صِنْفٍ مِنَ الزُّهورِ، وَمِنْ هذِهِ الأصْنافِ: اللُّونْدا وَالجورِيُّ وَالقُرَنْفُلُ، وَتُباعُ جَميعُها في السّوقِ المَحَلِّيَّةِ.","يُواجِهُ سُكّانُ قِطاعِ غَزَّةَ -كَغَيْرِهِمْ مِنَ الفِلَسْطينِيّينَ- عَقَباتٍ وَصُعوباتٍ كَثيرَةً، وَيُمَثِّلُ الاحْتِلالُ الصِّهْيونِيُّ أساسَ هذِهِ الصُّعوباتِ، وَقَدِ انْعَكَسَ أثَرُ ذلِكَ عَلى زِراعَةِ الوَرْدِ، وَتَقْليصِ مِساحَةِ الأرْضِ المَزْروعَةِ بِهِ لِتَصِلَ إِلى أقَلَّ مِنْ خَمْسينَ دُونُماً، مُعْظَمُها مُوَجَّهٌ لِلسّوقِ المَحَلِّيَّةِ الَّتي تَسْتَوْعِبُ سَنَوِيّاً أقَلَّ مِنْ نِصْفِ مِلْيونِ زَهْرَةٍ، عَلاوَةً عَلى صُعوبَةِ تَصْديرِ المَحْصولِ إِلى الخارِجِ، نَتيجَةَ سِياسَةِ الاحْتِلالِ في حِصارِ قِطاعِ غَزَّةَ، وَالتَّباطُؤِ المُتَعَمَّدِ في إِجْراءاتِ التَّصْديرِ؛ الأمْرُ الَّذي كَبَّدَ مُزارِعي الوَرْدِ خَسائِرَ مالِيَّةً فادِحَةً؛ وَدَفَعَ بِعَدَدٍ كَبيرٍ مِنْهُمْ إِلى التَّوَقُّفِ عَنْ زِراعَةِ الوَرْدِ، وَتَحْويلِ أراضيهِمْ إِلى مَزارِعَ لِلخَضْراواتِ، وَلِسانُ حالِهِمْ يَقولُ:","إِنّا نُحِبُّ الوَرْدَ، لكِنّا نُحِبُّ القَمْحَ أكْثَر","وَنُحِبُّ عِطْرَ الوَرْدِ، لكِنَّ السَّنابِلَ مِنْهُ أطْهَر.","وَمِنَ الصُّعوباتِ الَّتي تُواجِهُ زِراعَةَ الوَرْدِ: الحُروبُ المُتَعاقِبَةُ الَّتي يَشِنُّها الاحْتِلالُ، وَما يُصاحِبُها مِنْ تَجْريفٍ لِأراضي المُزارِعينَ وَتَخْريبِها، وَهَدْمٍ لِلبُيوتِ البِلاسْتيكِيَّةِ، خاصَّةً في مَنْطِقَتَي رَفَحٍ وَبَيْتَ لاهْيا، اللَّتَيْنِ تَتَرَكَّزُ فيهِما زِراعَةُ الوَرْدِ، إِضافَةً إِلى تَذَبْذُبِ كَمِّيَّةِ الأمْطارِ وَمَوْجاتِ الصَّقيعِ. هذِهِ العَوامِلُ وَغَيْرُها أدَّتْ إِلى إِلْحاقِ الضَّرَرِ بِمَحْصولِ الوَرْدِ، مِنْ حَيْثُ كَمِّيَّةُ الإِنْتاجِ وَجَوْدَةُ المَحْصولِ.","وَتُحَذِّرُ وِزارَةُ الزِّراعَةِ مِنَ انْقِراضِ زِراعَةِ الوَرْدِ إِذا لَمْ تَجِدْ مَنْ يَحْتَضِنُها، وَيُشَجِّعُ المُزارِعينَ وَيَدْعَمُهُمْ في حالِ حِصارِ قِطاعِ غَزَّةَ، وَبِالرَّغْمِ مِنْ تَشْديدِ الاحْتِلالِ خِناقَهُ عَلى قِطاعِ غَزَّةَ فَإِنَّهُ لَنْ يَتَمَكَّنَ مِنْ خَنْقِ عَبيرِ هذِهِ الوُرودِ، أوْ حِرْمانِ المُحاصَرينَ مِنَ التَّمَتُّعِ بِجَمالِها وَرِقَّةِ مَعانيها.","في غَزَّةَ يَتَعانَقُ الوَرْدُ وَالحَرْبُ، وَبِالرَّغْمِ مِنَ الجِراحِ، تَبْقى نَسَمَةُ البَحْرِ العَليلَةُ تَنْشُرُ في سَمائِها عَبَقاً مُشَبَّعاً بِالألَمِ وَالأمَلِ، وَلا يُمْكِنُ لِآ لَةِ البَطْشِ الصِّهْيونِيَّةِ أنْ تَقْطَعَ شِرْيانَ الوَرْدِ المُتَدَفِّقَ فيها، أمَلاً وَحُبّاً في حَياةٍ أفْضَلَ، حَتّى لَوْ تَوَقَّفَتْ عَنْ تَصْديرِ الزُّهورِ لِلعالَمِ، فَيَكْفيها أنْ تَزْرَعَهُ في رِياضِ شُهَدائِها، وَنُفوسِ شَبابِها، وَمُسْتَقْبَلِ أطْفالِها."],"voc":[["الألْفَةُ","التَّقارُبُ النَّفْسِيُّ، وَالانْسِجامُ الرّوحِيُّ."],["بُؤْسٌ","فَقْرٌ أوْ سوءُ حالٍ."],["سَراةُ جُنودِهِ","قادَتُهُمْ ونُخْبَتُهُمْ.ِ"],["أوْبِئَةٌ","أمْراضٌ."],["يَتَكَبَّدُها","يتَحَمَّلُ مَشَقَّتَها."]],"img":[["p2-57.webp",57],["p2-58.webp",58],["p2-59.webp",59],["p2-60.webp",60],["p2-61.webp",61]]},"grammar":{"t":"المُبْتَدَأُ وَالخَبَرُ","pg":62,"pts":["الجملة الاسميّة ركناها المبتدأ والخبر، وهما مرفوعان.","يأتي المبتدأ اسمًا مفردًا معربًا أو مبنيًّا (ضمير، اسم إشارة، اسم موصول).","يأتي الخبر مفردًا، أو جملةً فعليّة، أو جملةً اسميّة، أو شبه جملة (جارّ ومجرور، ظرف)."],"img":[["p2-62.webp",62],["p2-63.webp",63]],"q":[["نوع الخبر في «الوردُ يزيّن الحدائق»:",["جملة فعليّة","مفرد","شبه جملة","جملة اسميّة"],0,""],["نوع الخبر في «المزارعون في الحقل»:",["شبه جملة","مفرد","جملة فعليّة","جملة اسميّة"],0,""],["المبتدأ في «هذه زهرةٌ»:",["هذه (مبنيّ)","زهرة","لا مبتدأ","الهاء"],0,""]]},"balagha":{"t":"المُقابَلَةُ","pg":66,"pts":["المقابلة: أن يُؤتى بمعنيين أو أكثر ثمّ بما يقابلها على التّرتيب."],"img":[["p2-66.webp",66]]},"imla":{"t":"اخْتِبارِيٌّ","pg":67,"pts":["إملاء اختباريّ."],"img":[["p2-67.webp",67]]},"khatt":{"t":"الخَطُّ","pg":67,"pts":["كتابة عبارة."],"img":[["p2-67.webp",67]]},"taabir":{"t":"مُقَدِّمَةٌ نَظَرِيَّةٌ عَنِ السَّرْدِ","pg":68,"pts":["مقدّمة نظريّة عن السّرد: الشّخصيّات، الزّمان، المكان، الأحداث، الحبكة، الحلّ."],"img":[]}},"listen":"النَّباتاتُ آكِلَةُ الحَشَراتِ"},{"id":"P2U5","part":2,"n":5,"sec":{"read":{"t":"قِصَّةُ (ثُمَّ عادَ)","pg":71,"paras":["الكاتِبَةُ (حنان درْويش) مِنْ مَواليدِ عامِ (١٩٥٢م) في قَرْيَةِ مِصْيافٍ في سوريا، نَشَرَتْ أعْمالَها في عِدَّةِ صُحُفٍ وَمَجَلّاتٍ عَرَبِيَّةٍ... عُضْوُ اتِّحادِ الكُتّابِ العَرَبِ، وعُضْوُ اتِّحادِ الصَّحَفِيّينَ. فازَتْ بِالعَديدِ مِنَ الجَوائِزِ العَرَبِيَّةِ، وتُرْجِمَتْ عِدَّةُ قِصَصٍ مِنْ أعْمالِها إِلى الإِسْبانِيَّةِ. لَها مَجْموعاتٌ قِصَصِيَّةٌ مِنْها: ذلِكَ الصَّدى، وبَوْحُ الزَّمَنِ الأخيرِ. والقِصَّةُ الَّتي بَيْنَ أيْدينا تُعالِجُ فيها الكاتِبَةُ قَضِيَّةً أسَرِيَّةً تَظْهَرُ فيها تَضْحِيَةُ الأمِّ أثْناءَ غِيابِ الزَّوْجِ، وتَحَمُّلُها مَسْؤولِيَّةَ تَرْبِيَةِ الأبْناءِ.","ذَهَبَ دونَ وَداعٍ... لَمْ يَقُلْ شَيْئاً قَبْلَ الرَّحيلِ... حَزَمَ أمْتِعَتَهُ في غَفْلَةٍ عَنِ البَيْتِ، ثُمَّ خَرَجَ إِلى غَيْرِ رَجْعَةٍ. تَنَبَّهَتْ فاطِمَةُ إِلى غِيابِ سَليمٍ المُفاجِئِ، لكِنَّها لَمْ تَقُمْ بِأيَّةِ إِجْراءاتٍ تَخُصُّ التَّلْميحَ أوِ التَّصْريحَ؛ خَشْيَةَ انْتِشارِ الخَبَرِ بِشَكْلٍ يَنْعَكِسُ عَلَيْها، وعَلى أطْفالِها سَلْباً.","أخْفَتْ هَمَّها بادِئَ الأمْرِ، لَعَلَّ الزَّوْجَ يَكونُ قَدْ غادَرَ المَنْزِلَ في مَهَمَّةٍ قَصيرَةٍ، ثُمَّ يَعودُ...","لكِنَّ الفَتْرَةَ طالَتْ، وتَجاوَزَ الغِيابُ حَدَّهُ المَعْقولَ، وباتَ السُّكوتُ مُسْتَحيلاً. أخْبَرَتْ صِغارَها بِالحَقيقَةِ، مُخْتَلِقَةً لِرَحيلِ أبيهِمِ المُفاجِئِ أعْذاراً مُتَعَدِّدَةً، وكانَ عَدَدُهُمْ سِتَّةً، بِالإِضافَةِ إِلى جَنينٍ في بَطْنِها. بَعْدَ أشْهُرٍ أنْجَبَتْ طِفْلَةً، واجَهَتْ عَيْناها النّورَ، دونَ أنْ يُهَدْهِدَها أبٌ، ودونَ أنْ يُطْلِقَ عَلَيْها اسْماً. بَعْدَ عامٍ ونَيِّفٍ مِنَ الضَّنَكِ والعَذابِ أمْضَتْهُ فاطِمَةُ مُتَنَقِّلَةً بَيْنَ هُنا وهُناكَ في السُّؤالِ والتَّقَصّي... عَرَفَتْ أخيراً مَكانَهُ، وعَرَفَتْ أنَّهُ قَدْ غادَرَ البِلادَ، وَلَنْ يَعودَ إِلى الوَطَنِ أبَداً.","ذَرَفَتْ دُموعاً مالِحَةً كَمُلوحَةِ أيّامِها المُقْبِلَةِ. بَكَتْ بِحُرْقَةٍ عَلى حَظِّها، وعُمُرِها، وشَبابِها... حاوَلَتْ أنْ تَتَعَرَّفَ إلى سَبَبٍ واحِدٍ لِهِجْرانِهِ لَها، فَلَمْ تَجِدْهُ... فَتَّشَتْ عَنْ مُبَرِّراتٍ مُقْنِعَةٍ وكافِيَةٍ لِتَبْرِئَتِهِ أمامَ نَفْسِها، وأمامَ أوْلادِها، وأمامَ المُجْتَمَعِ، فَلَمْ تَعْثُرْ عَلَيْها، بَدَأتْ رِحْلَةُ الهُمومِ بِالنِّسْبَةِ لَها، وراحَ الصِّغارُ يَكْبُرونَ، وتَكْبُرُ مَعَهُمْ المَسْؤولِيّاتُ الجَمَّةُ الَّتي عَجَزَتْ في البِدايَةِ عَنْ حَمْلِها... إِذِ اسْتَنْجَدَتْ بِالأقارِبِ فَلَمْ يُنْجِدوها، ولَجَأتْ إِلى الأصْدِقاءِ والمَعارِفِ، فَتَهَرَّبوا مِنْها؛ لِذلِكَ قَرَّرَتْ أنْ تَعْمَلَ... وكانَ عَمَلُها أوَّلَ الأمْرِ يَتَوَزَّعُ بَيْنَ الخِدْمَةِ في بُيوتِ النّاسِ صَباحاً، وصِناعَةِ بَعْضِ المُعَجَّناتِ لِأحَدِ مَخازِنِ الحَلَوِيّاتِ مَساءً ... ثُمَّ اسْتَقَر حالُها بَعْدَ ذلِكَ عَلى القِيامِ بِمِهْنَةٍ كانَتْ قَدْ تَعَلَّمَتْها مُنْذُ صِغَرِها، وهِيَ الخِياطَةُ... فَقَدْ مَلَكَتْ مَقْدِرَةَ مُزاوَلَةِ هذِهِ المِهْنَةِ، وأتْقَنَتْ أداءَها بِالتَّدْريجِ؛ لِذلِكَ اشْتَرَتْ (ماكينَةَ) خِياطَةٍ... جَمَعَتْ ثَمَنَها قِرْشاً إِثْرَ قِرْشٍ، وراحَتْ تَخيطُ لِلْآخَرينَ بِالْأجْرَةِ... لَمْ يَكُنِ الوَضْعُ سَهْلاً أوْ مُريحاً في بِدايَتِهِ، لِعَدَمِ شُهْرَتِها، وقِلَّةِ زَبائِنِها... لكِنَّ اللّهَ لَمْ يَنْسَها، فَقَدْ أعانَها عَلى خَوْضِ مَرْحَلَتِها الجَديدَةِ، وسَهَّلَ لَها الطَّريقَ الَّذي صَمَّمَتْ عَلى السَّيْرِ فيهِ؛ لِتُصْبِحَ بَعْدَ زَمَنٍ مِنَ العَمَلِ الدَّؤوبِ المُسْتَمِرِّ، اسْماً مَعْروفاً في عالَمِ الحِياكَةِ والتَّطْريزِ، وبَدَأتْ أحْوالُها المادِّيَّةُ تَتَغَيَّرُ، وأمورُ أسْرَتِها تَنْتَقِلُ مِنَ الحَسَنِ إِلى الأحْسَنِ... حَمِدَتِ اللّهَ وشَكَرَتْهُ على نَعْمَتِهِ وفَضْلِهِ ورَحْمَتِهِ الَّتي شَمِلَها بِها، وعَوَّضَها عَنْ فَقْرِها، وفَرَّجَ كُرْبَتَها بَعْدَ مَسيرَةِ نِضالٍ مَشَتْها عَلى حِرابِ الزَّمَنِ مُدَّةَ سَبْعَةَ عَشَرَ عاماً، اسْتطاعَتْ خِلالَها أنْ تُرَبِّيَ أبْناءَها أحْسَنَ تَرْبِيَةٍ، وتُخَرِّجَهُمْ للدُّنْيا رِجالاً ونِساءً صالِحينَ، وتوصِلَهُمْ إِلى وَضْعٍ حَياتِيٍّ مَقْبولٍ بَعْدَ تَخَرُّجِ بَعْضِهِمْ في الجامِعَةِ، أمّا الأبُ فَقَدْ قَلَّتْ أخْبارُهُ، ونَدَرَتْ حتّى انْقَطَعَتْ تَماماً، ولَمْ يَعُدْ يَسْألُ عَنْهُ، أوْ يَذْكُرُهُ أحَدٌ... إِلى أنْ جاءَ يَوْمٌ طُرِقَ البابُ فيهِ عَلى عَجَلٍ، وكانَ الطّارِقُ ساعِيَ البَريدِ، يَحْمِلُ بَرْقِيَّةً تَقولُ: سَآتي بَعْدَ أسْبوعٍ، ذُهِلَتْ فاطِمَةُ... سَكَتَتْ عَنِ الكلَامِ، ولَجَمَتْ لِسانَها الدَّهْشَةُ حينَ قَرَأتِ التَّوْقيعَ... مَعْقولٌ؟! سَيَعودُ؟! بَعْدَ هذا العُمُرِ؟! ولِماذا؟ بَدَأ لِسانُها يُتَمْتِمُ، يَتَخَبَّطُ بِتَكَلُّفِ الكَلامِ... قَلَّبَ الأوْلادُ جَميعاً شِفاهَهُمْ، مُسْتَنْكِرينَ الأمْرَ، مُبْدينَ عَدَمَ الارْتِياحِ، وعَدَمَ قَبولِ ما سَمِعوا... قالَتْ إِحْدى البَناتِ:","- لِماذا يُريدُ العَوْدَةَ؟","عَقَّبَ أخوها:","- ماذا يَبْغي مِنّا؟... وماذا نَبْغي مِنْهُ؟","تابَعَتِ الصُّغْرى:","- نَحْنُ لا نَرْغَبُ بِمَجيئِهِ ...","ثُمَّ أضافَتْ:","- أنا لا أعْرِفُهُ، ولا أريدُ...","بَقِيَتِ الأمُّ عَلى شُرودِها ساهِمَةً، واجِمَةً، حائِرَة بِماذا تُجيبُ، وكَيْفَ تَتَصَرَّفُ؟ وماذا تَقولُ لِلْأوْلادِ؟ وعَلى أيِّ أساسٍ تُقْنِعُهُمْ بِوُجودِهِ، وبِأيَّةِ صِفَةٍ تَسْتَقْبِلُ ذاك الَّذي هَجَرَها عُمْراً بِحالِهِ، وتَرَكَها وأطْفالَها وهُمْ بِأمَسِّ الحاجَةِ إِلَيْهِ؟","عادَ كَالغَريبِ، رَجَعَ، وقَدْ نَأتْ عَنْهُ العافِيَةُ، وتَغَيَّرَتْ أحْوالُهُ ومَلامِحُهُ... أتى مَريضاً مَشْلولاً مَحْمولاً عَلى نَقّالَةٍ، يَنْخُرُ السّوسُ عِظامَهُ، والعِلَلُ تَتَوَزَّعُ دِماغَهُ وقَلْبَهُ... ولا بُدَّ لَهُ مِنْ خادِمَةٍ ومُمَرِّضَةٍ لِلْعِنايَةِ بِهِ... ولَيْسَ هُناكَ سِوى فاطِمَةَ، الَّتي حَكَمَتْ عَلَيْها الحَياةُ بِالعَذابِ... تُرى هَلْ تَقْبَلُهُ؟.. أمْ تَرْفُضُهُ؟ ما رَأْيُكُمْ؟..."],"voc":[["يُهَدْهِدُ","يُحَرِّكُهُ حَرَكَةً رَقيقَةً مُنَظَّمَةً لِيَنامَ."],["نَيِّفٌ","زِيادَةٌ."],["الضَّنَكُ","ضيقُ العَيْشِ."],["حِرابٌ","مُفْرَدُها حَرْبَةٌ وهِي آلَةٌ قَصيرَةٌ مِنَ الحَديدِ مُحَدَّدَةُ."],["البَرْقِيَّةُ","رِسالَةٌ تُرْسَلُ مِنْ مَكانٍ إِلى آخرَ بِوساطَةِ جِهازِ التِّلِغرافِ."],["ساهِمَةٌ","تَغَيَّرَ لَوْنُها عَنْ حالِهِ مِنْ هَمٍّ أوْ هُزالٍ."],["واجِمَةٌ","ساكِتَةٌ عَنِ الكَلامِ لِشِدَّةِ الحُزْنِ. بَوْحُ الزّمَنِ الأخيرِ، حنان درويش)."]],"img":[["p2-71.webp",71],["p2-72.webp",72],["p2-73.webp",73],["p2-74.webp",74],["p2-75.webp",75],["p2-76.webp",76]]},"poem":{"t":"في المَنْفى","pg":77,"verses":[],"voc":[["سَلَوْناهُمْ","نَسيناهُمْ."],["البيدُ","مُفْرَدُها بَيْداءُ، وَهِيَ الصَّحْراءُ."],["الغَبْراءُ","الأرْضُ المُجْدِبَةُ."],["تُهَدْهِدُ","تُحَرِّكُ."],["النَجْوى","الحَديثُ بِالسِّرِّ."],["رَبَواتٌ","مُفْرَدُها رَبْوَةٌ، وَهي التَّلَّةُ، ما ارْتَفَعَ مِنَ الأرْضِ."],["النَّشْوَةُ","الارْتِياحُ والنَّشاطُ."],["يَنْهَشُ","يَعَضُّ، ويَقْطَعُ."],["الوَجْدُ","الحُبُّ، والشَّوْقُ."],["السَّنا","الضَّوْءُ السّاطِعُ."],["واهٍ","ضَعيفٌ."]],"img":[["p2-77.webp",77],["p2-78.webp",78],["p2-79.webp",79],["p2-80.webp",80],["p2-81.webp",81]],"lines":["تُرى مَنْ يُخْبِرُ الأَحْبابَ أَنّا ما نَسيناهُمْ","وَأَنّا نَحْنُ في المَنْفى نَعيشُ بِزادِ ذِكْراهُمْ","وَأَنّا ما سَلَوْناهُمْ","فَصُحْبَتُنا بِفَجْرِ العُمْرِ ما زالَتْ تُؤانِسُنا","وَما زالَتْ بِهذي البيدِ في المَنْفى تُرافِقُنا","وَنَحْنُ بِهذِهِ الغُرْبَةْ","تُعَشِّشُ في زَوايانا عَناكِبُ هذِهِ الغُرْبَةْ","تَمُدُّ خُيوطَها السَّوْداءَ في آفاقِنا الغَبْراءِ أَحْزانا","تُهَدْهِدُ جَفْنَنا الأَحْلامُ تَنْقُلُنا عَلى جُنْحٍ مِنَ الذِّكْرى","إِلى عَهْدٍ مَضى حَيْثُ السُّكونُ يُثيرُ نَجْوانا","وَحَيْثُ الشَّوْقُ أُغْنِيَةٌ نُرَدِّدُها عَلى رَبَواتِ قَرْيَتِنا","وَحَيْثُ الحُبُّ في بَلَدي كَلامٌ صامِتُ النَّبْرَةْ","كَلامٌ صادِقُ الإِحْساسِ والنَّظْرَةْ","وَحُلْمٌ أَخْضَرُ في القَلْبِ يَرْوي سِرَّ نَشْوَتِنا،","وَيَحْضُنُنا وَيَرْعانا","يَمُرُّ اللَّيْلُ عَنْ جَفْني وَيَسْأَلُني","مَتى تَشْفى مِنَ الشَّجَنِ؟","أَحِبّائي سُؤالُ اللَّيْلِ يُؤْلِمُني","وَيُحْزِنُني","لِأَنّي كُلُّ ما أَدْريهِ أَنّي بِتُّ مَنْفِيّا","وَأَنّي لَمْ أَزَلْ حَيّا","تُعَذِّبُني وَتُقْلِقُني","طُيوفُ الأَمْسِ وَالذِّكْرى تُعَذِّبُني","فَأَجْتَرُّ الأَسى وَالصَّمْتَ وَالحَيْرَةْ","وَأَقْتاتُ الفَراغَ الرَّحْبَ أَنْحَرُ فيهِ أَيّامي","وَتَقْضِمُ عُشْبَ أَحْلامي","نُيوبُ الوَحْشَةِ المُرَّةْ","وَتَمْلَأُ خافِقي بِالحُزْنِ، تَفْعَمُ عالَمي حَسْرَةْ","فَأَطْوي صَفْحَةَ الماضي، وَأَغْفو عَلَّني أَصْحو","عَلى رَبْواتِنا أَعْدو","وَأَحْضُنُ في ثَراها الشَّوْقَ، أَلْمِسُهُ بِتَحْنانِ","وَيُغْرِقُني عَبيرُ الأَرْضِ، يُسْكِرُني بِلا خَمْرَةْ","وَأَحْيا حُلْمِيَ المَنْشودَ، أَلْمَحُ فيهِ إِنْساني","وَأَدْفِنُ فيهِ أَشْجاني","وَلكِنّي أَحِبّائي، أَفيقُ وَبَيْنَنا سَدُّ","غَريبٌ في بِلادِ النَّفْيِ يَنْهَشُ عُمْرَهُ البُعْدُ","وَيُسْقِمُ قَلْبَهُ الوَجْدُ","يُداعِبُهُ سَنا أَمَلٍ، بَدا في أُفْقِهِ واهٍ","غَداً يَمْضي بِنا التَّيّارُ يَجْمَعُنا بِمَنْ نَهْوى","وَيَدْري النّاسُ وَالْأَحْبابُ أَنّا ما سَلَوْناهُمْ","وَأَنّا لَمْ نَزَلْ في مَرْكَبِ الأَشْواقِ نُبْحِرُ صَوْبَ دُنْياهُمْ","تُرى مَنْ يُخْبِرُ الأَحْبابَ أَنّا ما نَسيناهُمْ","وَأَنّا لَمْ نَزَلْ في مَرْكَبِ الأَشْواقِ نُبْحِرُ صَوْبَ دُنْياهُمْ","ويَدْفَعُنا جُنونُ الوَجْدِ يَسْبِقُنا لِلُقْياهُمْ","تُرى مَنْ يُخْبِرُ الأَحْبابَ أَنّا ما نَسيناهُمْ؟!"]},"grammar":{"t":"كانَ وَأخَواتُها","pg":82,"pts":["كان وأخواتها أفعالٌ ناقصة ناسخة، تدخل على الجملة الاسميّة فترفع المبتدأ ويسمّى اسمها، وتنصب الخبر ويسمّى خبرها.","أخواتها: أصبح، أضحى، أمسى، ظلّ، بات، صار، ليس، ما زال، ما دام..."],"img":[["p2-82.webp",82],["p2-83.webp",83]],"q":[["«كان الجوُّ ماطرًا»: «ماطرًا»:",["خبر كان منصوب","اسم كان","حال","مفعول به"],0,""],["أدخل «أصبح» على «المنفى قاسٍ»:",["أصبح المنفى قاسيًا","أصبح المنفى قاسٍ","أصبح المنفى قاسي","أصبحت المنفى قاسيًا"],0,""],["«ليس الغريبُ سعيدًا»: «الغريبُ»:",["اسم ليس مرفوع","خبر ليس","فاعل","مبتدأ"],0,""]]},"balagha":{"t":"الفَرْقُ بَيْنَ الطِّباقِ وَالمُقابَلَةِ","pg":87,"pts":["الفرق بين الطّباق والمقابلة: الطّباق بين لفظين، والمقابلة بين معنيين أو أكثر وما يقابلهما."],"img":[["p2-87.webp",87]]},"imla":{"t":"أخْطاءٌ شائِعَةٌ في كِتابَةِ فِعْلِ الأمْرِ المُعْتَلِّ الآخِرِ","pg":88,"pts":["يُبنى فعل الأمر المعتلّ الآخر على حذف حرف العلّة."],"img":[["p2-88.webp",88]]},"khatt":{"t":"الخَطُّ","pg":90,"pts":["كتابة عبارة."],"img":[["p2-90.webp",90]]},"taabir":{"t":"كِتابَةُ بِطاقَةِ مُعايَدَةٍ","pg":91,"pts":["كتابة بطاقة معايدة."],"img":[]}},"listen":"عَمْرُو بْنُ الجَموحِ رَضِيَ اللهُ عَنْهُ"},{"id":"P2U6","part":2,"n":6,"sec":{"read":{"t":"الحَرْبُ الإِلِكْتْرونِيَّةُ","pg":93,"paras":["باتَتِ (التِّكنولوجيا الإِلِكتْرونِيَّةُ) حاضِرَةً في كُلِّ مَجالاتِ الحَياةِ العَمَلِيَّةِ، ومِعْياراً لِقِياسِ قُوَّةِ الدُّوَلِ العُظْمى، وَيَتَمَثَّلُ ذلِكَ بِما تَمْتَلِكُ كُلُّ دَوْلَةٍ مِنْ مَظاهِرِ التِّقْنِيَّةِ الحَديثَةِ، في القِطاعاتِ الصِّناعِيَّةِ والزِّراعِيَّةِ والعَسْكَرِيَّةِ وَغَيْرِها.","وَفي هذا المَقالِ العِلْمِيِّ نُسَلِّطُ الضَّوْءَ عَلى بَعْضِ آفاقِ اسْتِخْدامِ الإِلِكتْرونيّاتِ في مَجالِ الحُروبِ، وَدَوْرِها في حَسْمِها لِصالِحِ طَرَفٍ مِنَ الأطْرافِ، بَعْدَ أنْ باتَتِ الحَرْبُ التَّقْليدِيَّةُ سِلاحاً ذا تَكاليفَ باهِظَةٍ في الأرْواحِ والمُعَدّاتِ.","إِذَا كانَ كُلٌّ مِنَ البَرِّ، وَالبَحْرِ، وَالجَوِّ، وَالفَضاءِ الخارِجِيِّ، مَسْرَحاً لِلحَرْبِ التَّقْليدِيَّةِ، فَإِنَّ المَجالَ (الكَهْرومِغْناطيسِيَّ)، هُوَ المَسْرَحُ الحَقيقِيُّ لِلحَرْبِ الإِلِكتْرونِيَّةِ؛ إِذْ لَمْ تَعُدِ الحُروبُ تَقْتَصِرُ عَلى اسْتِخْدامِ الأسْلِحَةِ الفَتّاكَةِ الَّتي تَحْمِلُها الطّائِراتُ أوِ المُدَرَّعاتُ أوِ الجُنودُ، وَتوشِكُ هذِهِ أنْ تَتَوارى وَراءَ ظِلِّ حُروبٍ إِلِكتْرونِيَّةٍ، رُبَّما تَكونُ أكْثَرَ فَتْكاً، مَيْدانُها الشَّبَكَةُ العَنْكَبوتِيَّةُ، وَتَنْطَوي عَلى هَجَماتٍ ذاتِ دَوافِعَ سِياسِيَّةٍ عَلى المَعْلوماتِ وَنُظُمِها، إِذْ يُمْكِنُها أنْ تُعَطِّلَ مَواقِعَ (الويب) الرَّسْمِيَّةَ والشَّبَكاتِ وَالخَدَماتِ الأساسِيَّةَ، أو سَرِقَةَ البَياناتِ السِّرِّيَّةِ وَتَعْدِيلَها، وَتَخْريبَ الأنْظِمَةِ المالِيِّةِ...","تَمْتَدُّ مَسارِحُ الحُروبِ الإلِكتْرونِيَّةِ مِنْ قاعِ المُحيطاتِ حَتّى الفَضاءِ الخارِجِيِّ، وتُسْتَخْدَمُ فيهَا نُظُمٌ إلِكتْرونِيَّةٌ مُتَنَوِّعَةٌ مِثْلُ: المُراقَبَةِ، والكَشْفِ، والخِداعِ، والسَّيْطَرَةِ، وَتَوْجيهِ الأسْلِحَةِ.","لَقَدْ باتَ بِإِمْكانِ الغَوّاصاتِ البَحْرِيَّةِ رَصْدُ الألْغامِ والغَوّاصاتِ المُعادِيَةِ، وَباتَتْ طائِراتُ الاسْتِطْلاعِ وَالإِنْذارِ المُبَكِّرِ قادِرَةً عَلى كَشْفِ أيِّ اخْتِراقٍ مُعادٍ، وَإِبْلاغِ غُرْفَةِ العَمَلِيّاتِ المَرْكَزِيَّةِ بِهِ أوَّلاً بِأوّل، أمّا في مَجالِ الاسْتِخْدامِ البَرِّيِّ، فَتَتَرَكَّزُ الحَرْبُ الإِلِكتْرونِيَّةُ عَلى إِرْباكِ عَمَلِ غُرَفِ عَمَلِيّاتِ العَدُوِّ، وَمُراقَبَتِها والتَّنَصُّتِ عَلَيْها، وَمَعْرِفَةِ تردُّداتِ الإ رْسالِ فيها، وَإرْباكِها بِإِشاراتٍ خَدّاعَةٍ.","بِإِمْكانِ أيِّ دَوْلَةٍ شَنُّ حَرْبٍ إلِكتْرونِيَّةٍ عَلى دَوْلَةٍ أخْرى مَهْما كانَتْ مَوارِدُها؛ وَذلِكَ لِأنَّ مُعْظَمَ القُوّاتِ العَسْكَرِيَّةِ تَرْتَبِطُ بِشَبَكاتٍ حاسوبِيَّةٍ، وَتَتَّصِلُ (بِالإ نْتَرْنِت)، وَلِذلِكَ فَهِي لَيْسَتْ آمِنَةً، وَلِلسَّبَبِ ذاتِهِ؛ باتَ بِإِمْكانِ الجَماعاتِ غَيْرِ الحُكومِيَّةِ، وَحَتّى الأفْرادِ، شَنُّ هَجَماتِ حَرْبٍ إِلِكتْرونِيَّةٍ، والآنَ فَإِنَّ ثَمَّةَ سِباقاً بَيْنَ الدُّوَلِ الغَنِيّةِ، لِتَطْويرِ بَرْمَجِيّاتٍ يَكونُ مِنْ شَأْنِها امْتِلاكُ قُدُراتٍ هُجومِيَّةٍ وَأخْرى دِفاعِيَّةٍ، قادِرَةٍ عَلى التّصَدّي لِأيَّةِ هَجَماتٍ مُشابِهَةٍ.","وَيُعَدُّ فَيروسُ (ستاكْسْ نِتْ) الّذي تَسَبَّبَ في إِلْحاقِ أضْرارٍ بِأجْهِزَةِ التَّخْصيبِ النَّوَوِيِّ الإِيرانِيِّ، مِنْ أبْرَزِ الأدِلَّةِ عَلى الهَجَماتِ الإِلِكتْرونِيَّةِ الحَديثَةِ، إِذْ أطْلَقَتْهُ الوِلاياتُ المُتَّحِدَةُ وَدَوْلَةُ الصَّهايِنَةِ عامَ (٢٠١٠م)، ضِدَّ حَواسيبَ تابِعَةٍ لِلمُنْشآتِ النَّوَوِيَّةِ الإِيرانِيَّةِ؛ بِهَدَفِ إِبْطاءِ عَمَلِها. وَمِنَ الأمْثِلَةِ الأخْرى، الهُجومُ الأمريكِيُّ الإِلِكتْرونِيُّ عَلى نِظامِ الدِّفاعِ الجَوِّيِّ الصِّرْبِيِّ سَنَةَ (١٩٩٨م)؛ لاخْتِراقِهِ بِهَدَفِ تَسْهيلِ قَصْفِ أهْدافٍ صِرْبِيَّةٍ.","لَقَدْ أسْهَمَتِ الحَرْبُ الإِلِكتْرونِيَّةُ في تَغْييرِ قَواعِدِ الصِّراعِ بَيْنَ الدُّوَلِ؛ فَلَمْ يَعُدِ الحَسْمُ الحَربِيُّ مُعْتَمِداً عَلى التَّفوُّقِ النَّوْعِيِّ وَالعَدَدِيِّ، وَإِنَّما عَلى مِقْدارِ ما يَمْتَلِكُ كُلُّ طَرَفٍ مِنْ وَسائِلَ إِلِكتْرونِيَّةٍ حَديْثَةٍ، فَمَعْرِفَةُ إِمْكاناتِ العَدُوِّ، وَتَشْكيلاتِهِ، وَأنْظِمَةِ مُواصَلاتِهِ، وَتَحَرُّكاتِهِ مُسْبَقاً، هِيَ الَّتي تَخْدِمُ الطَّرَفَ المُعاديَ في تَحْقيقِ النَّصْرِ وَالمُباغَتَةِ، وَلا بُدَّ مِنَ الإِشارَةِ إِلى أنَّ التَّحَكُّمَ الآلِيَّ، وَالأشِعَّةَ فَوْقَ الحَمْراءِ، أسْهَمَتْ في تَطْويرِ أنْظِمَةٍ دِفاعِيَّةٍ وَهُجومِيَّةٍ عالِيَةِ الدِّقَّةِ، تُصيبُ هَدَفَها المُقَرَّرَ بِدِقّةٍ مُتَناهِيَةٍ، لِدَرَجَةِ أنَّنا صِرْنا نُشاهِدُ الطّائِراتِ الإِلِكتْرونِيَّةَ جَنْباً إِلى جَنْبٍ مَعَ الطّائِراتِ الهُجومِيَّةِ، لِأعْمالِ المُباغَتَةِ، وَالحِراسَةِ، وَاخْتِراقِ أجْهِزَةِ (الرّادارِ) لَدى الخَصْمِ.","وَهكذا، نَرى أنَّ مُعْطَياتِ التِّقْنِيَّةِ الحَديثَةِ سِلاحٌ ذو حَدَّيْنِ؛ فَبِقَدْرِ ما تَحْمِلُهُ مِنْ مَنافِعَ وَ بِقَدْرِ ما تُوَفِّرُ مِنَ الوَقْتِ والجُهْدِ، فإِنَّها قَدْ تَكونُ نُقْطَةَ ضَعْفٍ وَثَغْرَةً يَتَسَلَّلُ مِنْها العَدُوُّ، فَتُصْبِحُ ساحاتُ الجَيْشِ وَمُقَدَّراتُهُ عَلى مَرْمى (كَبْسَةِ زِرٍّ) أوْ نَقْرَةٍ واحِدَةٍ مِنْ أصابِعِ الجَيْشِ المُعادي؛ ما يُحَتِّمُ عَلَيْنا التَّعامُلَ بِحَذَرٍ بالِغٍ مَعَ هذِهِ المُخْرَجاتِ والخَياراتِ الإِلِكتْرونِيَّةِ، وَأنْ نَسْعى دَوْماً لِاكْتِسابِ مَهاراتٍ جَدِيدَةٍ وَمُسْتَحْدَثَةٍ في عالَمِ التِّكْنولوجيا الواسِعِ؛ فَقَدْ قيلَ: \"لِكُلِّ زَمانٍ دَوْلَةٌ وَرِجالٌ\". وَرِجالُ عَصْرِنا هذا هُمْ رِجالُ التِّكْنولوجيا، وَمُخْرَجاتُها، بِخَيْرِها وَشَرِّها.","يُوجَدُ فَرْقٌ في المَعْنى بَيْنَ مَفْهُومَيِ الاخْتِراعِ والاكْتِشافِ، فالاخْتِراعُ: شَيءٌ لَمْ يَكُن مَوجوداً مِنَ الأساسِ، وَتَسَبَّبَ المُخْتَرِعُ في إيجادِهِ مِنْ خِلالِ تَفْكيرِهِ وَتَصْميمِهِ، مِثْلَ اخْتِراعِ الحاسوبِ. أمّا الاكْتِشافُ: فَهُوَ شَيْءٌ مَوْجودٌ، وَلَكِنْ لَمْ يَعْلَمْ بِهِ أحَدٌ سابِقاً، وَالمُكْتَشِفُ تَسَبّبَ فِي إِظْهارِهِ، مِثْلَ اكْتِشَافِ حَيَوانٍ، أوْ اكْتِشَافِ (فايْروسٍ) مُسَبِّبٍ لِمَرَضٍ مُعَيَّنٍ، أو اكْتِشافِ كَوْكَبٍ."],"voc":[["تَنْطَوي عَلى","تَشْتَمِلُ عَلى."],["الغَوّاصاتُ","مَراكِبُ تَسيْرُ تَحْتَ الماء."],["الإِرْباكُ","الإ يقاعُ في الاضْطِرابِ."],["الحَسْمُ","الإِنْهاءُ."],["المُباغَتَةُ","المُفاجَأةُ."],["التَّسَلُّلُ","الدُّخولُ أو الخُروجُ خِفْيَةً."]],"img":[["p2-93.webp",93],["p2-94.webp",94],["p2-95.webp",95],["p2-96.webp",96],["p2-97.webp",97],["p2-98.webp",98]]},"poem":{"t":"قُوَّةُ العِلْمِ","pg":99,"verses":[["بِقُوَّةِ العِلْمِ تَقْوى شَوْكَةُ الأُمَمِ","فَالْحُكْمُ في الدَّهْرِ مَنْسوبٌ إِلى القَلَمِ"],["لَوْ أَنْصَفَ النّاسُ كانَ الفَضْلُ بَيْنَهُمُ","بِقَطْرَةٍ مِنْ مِدادٍ، لا بِسَفْكِ دَمِ"],["فَاعْكِفْ على العِلْمِ، تَبْلُغْ شَأْوَ مَنْزِلَةٍ","في الفَضْلِ مَحْفوفَةٍ بِالعِزِّ وَالكَرَمِ"],["فَلَيْسَ يَجْني ثِمارَ الفَوْزِ يانِعَةً","مِنْ جَنَّةِ العِلْمِ إِلّا صادِقُ الهِمَمِ"],["لَوْلا مُداوَلَةُ الأَفْكارِ ما ظَهَرَتْ","خَزائِنُ الأَرْضِ بَيْنَ السَّهْلِ وَالعَلَمِ"],["فَاسْتَيْقِظوا يا بَني الأَوْطانِ، وانْتَصِبوا","لِلعِلْمِ؛ فَهْوَ مَدارُ العَدْلِ في الأُمَمِ"],["فَرُبَّ ذي ثَرْوَةٍ بِالجَهْلِ مُحْتَقَرٍ","وَرُبَّ ذي خَلَّةٍ بِالعِلْمِ مُحْتَرَمِ"],["شيدوا المَدارِسَ؛ فَهْيَ الغَرْسُ إنْ بَسَقَتْ","أَفْنانُهُ أَثْمَرَتْ غَضّاً مِنَ النِّعَمِ"],["يَجْنونَ مِنْ كُلِّ عِلْمٍ زَهْرَةً عَبِقَتْ","بِنَفْحَةٍ تَبْعَثُ الأَرْواحَ في الرِّمَمِ"],["بَلْ، كَمْ خَطيبٍ شَفى نَفْساً بِمَوْعِظَةٍ","وَكَمْ طَبيبٍ شَفى جِسْماً مِنَ السَّقَمِ"],["مُؤَدَّبونَ بِآدابِ المُلوكِ، فَلا","تَلْقى بِهِمْ غَيْرَ عالي القَدْرِ مُحْتَشِمِ"],["قَوْمٌ بِهِمْ تَصْلُحُ الدُّنْيا إِذا فَسَدَتْ","وَيَفْرُقُ العَدْلُ بَيْنَ الذِّئْبِ وَالغَنَمِ"],["وَكَيْفَ يَثْبُتُ رُكْنُ العَدْلِ في بَلَدٍ","لَمْ يَنْتَصِبْ بَيْنَها لِلعِلْمِ مِنْ عَلَمِ؟"],["لَوْلا الفَضيلَةُ لَمْ يَخْلُدْ لِذي أَدَبٍ","ذِكْرٌ عَلى الدَّهْرِ بَعْدَ المَوْتِ وَالعَدَمِ"],["فَلْيَنْظُرِ المَرْءُ فيما قَدَّمَتْ يَدُهُ","قَبْلَ المَعادِ، فَإِنَّ العُمْرَ لَمْ يَدُمِ"]],"voc":[["بَسَقَتْ أفْنانُهُ","عَلَتْ -١٠ العِطْرِ. -١١ ِمُؤَدَّبونَ بآدابِ المُلوكِ، فَلاْتَلْقى بِهِمْ غَيْرَ عالي القَدْرِ مُحْتَشِم"],["الرِّمَمُ","العِظامُ البالِيَةُ."]],"img":[["p2-99.webp",99],["p2-100.webp",100],["p2-101.webp",101]]},"grammar":{"t":"كادَ وَأخَواتُها","pg":102,"pts":["كاد وأخواتها أفعالٌ تعمل عمل كان، وخبرها جملة فعليّة فعلها مضارع.","أفعال المقاربة: كاد، أوشك، كرب. أفعال الرّجاء: عسى، حرى، اخلولق. أفعال الشّروع: بدأ، أخذ، شرع، جعل، أنشأ، طفق."],"img":[["p2-102.webp",102],["p2-103.webp",103]],"q":[["«كاد العلمُ يقهرُ المستحيل»: خبر كاد:",["جملة يقهر المستحيل","العلم","المستحيل","يقهر وحده"],0,""],["«عسى» من أفعال:",["الرّجاء","المقاربة","الشّروع","الذّمّ"],0,""],["«شرعَ» من أفعال:",["الشّروع","الرّجاء","المقاربة","النّفي"],0,""]]},"imla":{"t":"اخْتِبارِيٌّ","pg":106,"pts":["إملاء اختباريّ."],"img":[["p2-106.webp",106]]},"khatt":{"t":"الخَطُّ","pg":107,"pts":["كتابة عبارة."],"img":[["p2-107.webp",107]]},"taabir":{"t":"مُقَدِّمَةٌ نَظَرِيَّةٌ عَنِ الرِّسالَةِ الإِخْوانِيَّةِ","pg":108,"pts":["مقدّمة نظريّة عن الرّسالة الإخوانيّة: المكان والتّاريخ، التّحيّة، المقدّمة، المضمون، الخاتمة، التّوقيع."],"img":[]}},"listen":"قِصَّةُ اخْتِراعِ قَلَمِ الحِبْرِ الجافِّ"},{"id":"P2U7","part":2,"n":7,"sec":{"read":{"t":"الفَسادُ مِعْوَلٌ يَهْدِمُ المُجْتَمَعَ","pg":111,"paras":["الإِصْلاحُ سُنَّةُ اللّهِ في الأرْضِ، وَرِسالَةُ الأنْبِياءِ وَالرُّسُلِ، وَهُوَ نَقيضُ الفَسادِ، الّذي يَعْني الاسْتِغْلالَ غَيْرَ القانونِيِّ للسُّلْطَةِ السِّياسِيَّةِ، أوِ الإِدارِيَّةِ، أوِ الوَظيفِيَّةِ؛ ما يُؤَدّي إِلى التَّسَبُّبِ بِالضَّرَرِ العامِّ لِلأمَّةِ جَميعِها؛ وَيَنْخُرُ وُجودَها، وَيُعيقُ تَحْقيقَ أهْدافِها. قالَ تَعالى:","وَلِلفَسادِ أسْبابٌ مُتَنَوِّعَةٌ مِنْها: ضَعْفُ الوازِعِ الدّينِيِّ، وَالخُضوعُ لِلشَّهَواتِ الأمّارَةِ بِالسّوءِ، وهذا يَقودُ الإِنْسانَ إِلى الانْحِرافِ عَنْ جادَّةِ الصَّوابِ. وَأسْبابٌ اجْتِماعِيَّةٌ، تَظْهَرُ في الآثارِ السَّيِّئَةِ النّاتِجَةِ عَنِ الأزَماتِ وَالكَوارِثِ الَّتي تَلْحَقُ بِالمُجْتَمَعِ، إِضافَةً إِلى العاداتِ وَالتَّقاليدِ الاجْتِماعِيَّةِ السَّيِّئَةِ المُتَوارَثةِ، نُضيفُ لِذلِكَ الفَقْرَ وَالحاجَةَ، وارْتِفاعَ تَكاليفِ المَعيشَةِ. وَأسْبابٌ سِياسِيَّةٌ، تَتَمَثَّلُ في ضَعْفِ تَطْبيقِ الأنْظِمَةِ وَالقَوانينِ، وَقِلَّةِ الشَّفّافِيَّةِ، وَالتَّضْليلِ بِحُقوقِ الأفْرادِ وَواجِباتِهِم.","أمّا مَظاهِرُ الفَسادِ فَكَثيرَةٌ وَمُتَنَوِّعَةٌ، مِنْها: الرَّشْوَةُ، وَالمَحْسوبِيَّةُ، وَإِقْصاءُ الكَفاءاتِ المُؤَهَّلَةِ، وَالمُحاباةُ، وَاسْتِغْلالُ المُمْتَلَكاتِ العامَّةِ، وَعَدَمُ الالْتِزامِ بِمَواعيدِ الدَّوامِ الرّسْمِيِّ، وَالابْتِزازُ، وَالتَّهاوُنُ في تَطْبيقِ الأنْظِمَةِ وَالقَوانينِ، وَالاسْتيلاءُ عَلى المالِ العامِّ، وَعَدَمُ وَضْعِ الرَّجُلِ المُناسِبِ في المَكانِ المُناسِبِ، وَتَغْييبُ الرَّقابَةِ الإِلهِيَّةِ وَالذّاتِيَّةِ أثْناءَ القِيامِ بِالعَمَلِ ...","وَيَنْبَغي عَلى كُلِّ واحِدٍ مِنّا أنْ يَحْمِلَ عَلى كاهِلِهِ، وَيَضَعَ نُصْبَ عَيْنَيْهِ أنَّ بِناءَ الوَطَنِ وَالمُواطِنِ لا يَسْتَقيمانِ إلّا إِذا باتَ قَوْلُ رَسولِنا الكَريمِ -صَلّى اللّهُ عَلَيْهِ وَسَلَّمَ-: \"كُلُّكُمْ راعٍ وكُلُّكُمْ مَسْؤولٌ عَنْ رَعِيَّتِهِ\" شِعاراً تَضْرِبُ جُذورُهُ في أعْماقِ النَّفْسِ، وَتَشمَخُ فُروعُهُ إِلى عَنانِ السَّماءِ.","يَجِبُ أنْ يَكونَ كُلُّ فَرْدٍ مِنّا يَقِظاً فَطِناً حارِساً أميناً عَلى مُقَدَّراتِ البَلَدِ وَمَرافِقِهِ العامَّةِ، مُدْرِكاً أنَّ تَضافُرَ جُهودِ الأفْرادِ، وَالتِزامَهُمُ الدّينِيَّ وَالوَطِنِيَّ وَالأخْلاقِيَّ، وَغَيْرَتَهُمْ عَلى المَصْلَحَةِ العامَّةِ أوَّلُ خُطُواتِ مُحارَبَةِ الفَسادِ وَالفاسِدينَ. كَما أنَّ سَنَّ الأنْظِمَةِ وَالتَّشْريعاتِ الشَّفّافَةِ المُحارِبَةِ لِلفَسادِ، وَتَوْضيحَها، وَإِنْزالَ أقْصى العُقوباتِ الرّادِعَةِ عَلى المُخالِفينَ تَجْعَلُ الأفْرادَ وَالجَماعاتِ مُنْتَبِهينَ مُتَيَقِّظينَ لِهذِهِ الظّاهِرَةِ الخَطيرَةِ، وَلِنَتائِجِها السَّلْبِيَّةِ الَّتي تَسْري في المُجْتَمَعِ سَرَيانَ النّارِ في الهَشيمِ.","وَلا يَخْفى عَلى كُلِّ ذي بَصيرَةٍ أنَّ تَعْزيزَ النَّماذِجِ الصّالِحَةِ الَّتي تَرْبَأ بِنَفْسِها عَنِ الفَسادِ، أوْ تُقاوِمُهُ أوْ تُبَلِّغُ عَنْهُ، يُوَلِّدُ الانْتِماءَ وَالإِبْداعَ لَدى أفْرادِ الشَّعْبِ، وَيَغْرِسُ بُذورَ الأمَلِ لِميلادِ مُسْتَقْبَلٍ حافِلٍ بِالعَطاءِ، وَيُوَفِّرُ فُرَصَ العَمَلِ لِطاقاتِ الشَّبابِ، كَما أنَّ لِعَقْدِ النَّدَواتِ، وَالتَّوْعِيَةِ في المُؤَسَّساتِ، وَاسْتِغْلالِ وَسائِلِ الإِعْلامِ، أثَراً كَبيراً في انْحِسارِ هذهِ الظّاهِرَةِ، وَتَنْمِيَةِ ثَقافَةِ إيثارِ المَصالِحِ العامَّةِ عَلى المَصالِحِ الذّاتِيَّةِ.","إِنَّ الْفَسادَ وَرَمٌ خَبيثٌ يَأْتي عَلى وُجودِ الفَرْدِ وَالمُجْتَمَعِ، وَيَقِفُ حائِلاً دونَ اللَّحاقِ بِرَكْبِ الأمَمِ المُتَقَدِمَةِ. وَلَعَلَّ أشْكالَهُ المُتَعَدِّدَةَ في عالَمِنا العَرَبِيِّ سَبَبٌ في تَدَنّي قُدْراتِ الدَّوْلَةِ وَالأفْرادِ، وَتَراجُعِ اقْتِصادِها المالِيِّ وَنُمُوِّها المَعْرِفِيِّ، وَظُهورِ طَبَقاتٍ ثَرِيَّةٍ جِدّاً، تَعْبَثُ بِالثَّرْوَةِ وَالمالِ، وَتُمارِسُ أشْكالَ البَطَرِ وَالفَسادِ كافَّةً، مُقابِلَ طَبَقاتٍ أخْرى غَيْرِ قادِرَةٍ عَلى تَأْمينِ أدْنى مُتَطَلَّباتِ الحَياةِ؛ لِذا يَتَوَجَّبُ عَلَيْنا أنْ نُدافِعَ عَنْ وَطَنِنا بِكُلِّ ما أوتينا مِنْ قُوَّةٍ، وَنَضْرِبَ بِأيْدٍ مِنْ حَديدٍ عَلى الفَسادِ وَالفاسِدينَ، وَلا نَتْرُكَ لَهُمْ مَوْطِئَ قَدَمٍ بَيْنَنا، فَالوَطَنُ لِأبْنائِهِ الّذينَ يَسْهَرونَ وَيَبْنونَ، لا لِأولئِكَ الّذينَ يَنْهَبونَ وَيَهْدِمونَ."],"voc":[["﴾(القَصَصُ","٧٧ )"],["الوازِعُ","المانِعُ، وَالرّادِعُ."],["جادَّةُ الصَّوابِ","طَريقُ الحَقِّ."],["الشَّفّافِيَّةُ","الوُضوحُ."],["إِقْصاءُ الكَفاءاتِ المُؤَهَّلَةِ","إِبْعادُ أصْحابِ الشِّهاداتِ وَالخِبْراتِ الجَيِّدَةِ."],["المُحاباةُ","أنْ تُعْطِيَ شَخْصاً ما لَيْسَ لَهُ، وَتُمَيِّزَهُ عَنْ غَيْرِهِ."],["الكاهِلُ","أعْلى الظَّهْرِ ما بَيْنَ الكَتِفِ وَالعُنُقِ."],["تَضافُرُ الجُهودِ","تَعاوُنُها، وَاتّحادُها."],["الرادِعَةُ","المانِعَةُ."],["الهَشيمُ","النَّبْتُ اليابِسُ."],["تَرْبَأ بِنَفْسِها","تَتَرَفَّعُ عَنِ الشَّيْءِ، وَتَتَجَنَّبُهُ."],["البَطَرُ","الإِسْرافُ وإِتْلافُ النِّعَمِ."]],"img":[["p2-111.webp",111],["p2-112.webp",112],["p2-113.webp",113],["p2-114.webp",114],["p2-115.webp",115]]},"poem":{"t":"خَجِلْتُ وَرَبِّ البَيْتِ","pg":116,"verses":[["خَجِلْتُ، وَرَبِّ البَيْتِ، مِنْ حالِ أَوْطاني","فَلا الحَرْبُ أَرْضَتْني وَلا السِّلْمُ أَرْضاني"],["فَلَسْتُ أَرى إِلّا وُجوهاً كَئيبَةً","وَلَسْتُ أَرى إِلّا صِراعاتِ إِخْوانِ"],["وَلَسْتُ أَرى إِلّا خِلافاً وَفُرْقَةً","أَعَدْنا بِها أَيّامَ \"عَبْسٍ\" وَ\"ذُبْيانِ\""],["نَسينا عَلى عَزْفِ الشِّعاراتِ دينَنا","فَلَسْنا إِلى قاصٍ وَلَسْنا إِلى دانِ"],["فَكَمْ ظالِمٍ يَمْشي إِلى كُلِّ رَغْبَةٍ","وَكَمْ مِنْ بَريءٍ جاثِمٍ خَلْفَ قُضْبانِ"],["وَكَمْ حُرَّةٍ صاحَتْ: أَباهُ، وَلَمْ تَجِدْ","يَداً تَحْتَميها مِنْ ذِئابٍ وَغِرْبانِ"],["أَرى في الوُجوهِ الباسِماتِ تَجَهُّماً","وَفي نَظَراتِ القَوْمِ إِغْضاءَ حَيْرانِ"],["وَيَطْعَنُني سَهْمُ الصَّديقِ فَأَنْثَني","وَفي جَسَدي جُرْحٌ، وَجُرْحٌ بِوِجْداني"],["أَخي .. ما دَهَا عَيْنَيْكَ؟ ما عادَ فيهِما","صَفاءٌ يُشيعُ الأَمْنَ في قَلْبِيَ العاني"],["أَرى في الرَّوابي الخُضْرِ جَدْباً يُميتُها","وَفي نَبْعِها الصّافي رَواسِبَ أَدْرانِ"],["لَقَدْ كُنْتَ تَبْني صَرْحَ قُوَّتِنا مَعي","فَكَيْفَ غَدَوْتَ اليَوْمَ، تَهْدِمُ بُنْياني"],["عَلامَ تَعادَيْنا؟ وَفيمَ خِصامُنا؟","وَنَحْنُ عَلى أَبْوابِ تَحْريرِ أَوْطانِ"],["وَحَتّامَ نَبْقى في صُفوفٍ أَخيرَةٍ؟","نَسيرُ وَراءَ القَوْمِ في كُلِّ مَيْدانِ"],["إِلى أَيْنَ يا قَوْمي؟ فَهذا طَريقُنا","وَكُلُّ طَريقٍ غَيْرُهُ، دَرْبُ خُسْرانِ"],["إِذا فَقَدَ الإِنْسانُ صِدْقَ انْتِمائِهِ","وَأَضْحى بِلا قَلْبٍ فَلَيْسَ بِإِنْسانِ"]],"voc":[["-٦ ِوَكَمْ حُرَّةٍ صاحَتْ","أباهُ، وَلَمْ تَجِد يَداً تَحْتَميها مِنْ ذِئابٍ وَغِرْبانً وَالغَضَبُ. -٨ وَيَطْعَنُني سَهْمُ الصَّديقِ فَأنْثَني وَفي جَسَدي جُرْحٌ، وَجُرْحٌ بِوِجْداني"],["الإِغْضاءُ","إِرْخاءُ جَفْنِ كِنايَةٌ عَنِ التَغافُلِ. -١٠ أرى في الرَّوابي الخُضْرِ جَدْباً يُميتُها وَفي نَبْعِها الصّافي رَواسِبَ أدْران"],["أنْثَني","أرْتَدُّ."],["دَها","أصابَ. -١٢ ِعَلامَ تَعادَيْنا؟ وَفيمَ خِصامُنا؟ وَنَحْنُ عَلى أبْوابِ تَحْريرِ أوْطان"],["العاني","الأسيرُ المُعَذَّبُ. -١٣ ِوَحَتّامَ نَبْقى في صُفوفٍ أخيرَةٍ؟ نَسيرُ وَراءَ القَوْمِ في كُلِّ مَيْدان"],["الجَدْبُ","القَحْطُ. -١٤ ِإِلى أيْنَ يا قَوْمي؟ فَهذا طَريقُناِوَكُلُّ طَريقٍ غَيْرُهُ، دَرْبُ خُسْران"],["الأدْرانُ","الأوْساخُ،"],["الصَّرْحُ","القَصْرُ العالي."]],"img":[["p2-116.webp",116],["p2-117.webp",117],["p2-118.webp",118],["p2-119.webp",119]]},"grammar":{"t":"إِنَّ وَأخَواتُها","pg":120,"pts":["إنّ وأخواتها ستّة أحرف: إنّ، أنّ، لكنّ، لعلّ، ليت، كأنّ.","تدخل على الجملة الاسميّة فتنصب المبتدأ ويسمّى اسمها، وترفع الخبر ويسمّى خبرها.","معانيها: إنّ وأنّ للتّوكيد، لكنّ للاستدراك، كأنّ للتّشبيه، ليت للتّمنّي، لعلّ للتّرجّي."],"img":[["p2-120.webp",120],["p2-121.webp",121]],"q":[["«إنّ الفسادَ معولٌ»: «الفسادَ»:",["اسم إنّ منصوب","خبر إنّ","مبتدأ","فاعل"],0,""],["معنى «ليت»:",["التّمنّي","التّوكيد","التّشبيه","الاستدراك"],0,""],["أدخل «لعلّ» على «المجتمعُ سليمٌ»:",["لعلّ المجتمعَ سليمٌ","لعلّ المجتمعُ سليمًا","لعلّ المجتمعَ سليمًا","لعلّ المجتمعُ سليمٌ"],0,""]]},"balagha":{"t":"تَدْريباتٌ عَلى الطِّباقِ وَالمُقابَلَةِ","pg":124,"pts":["تدريبات على الطّباق والمقابلة."],"img":[["p2-124.webp",124]]},"imla":{"t":"أخْطاءٌ شائِعَةٌ","pg":124,"pts":["أخطاء شائعة: إشباع حركات أواخر الكلمات، مثل كتابة «أنتِ» «أنتي»، و«لكِ» «لكي»."],"img":[["p2-124.webp",124]]},"khatt":{"t":"الخَطُّ","pg":126,"pts":["كتابة عبارة."],"img":[["p2-126.webp",126]]},"taabir":{"t":"تَحْليلُ رِسالَةٍ","pg":127,"pts":["تحليل رسالة."],"img":[]}},"listen":"الدّينُ المُعامَلَةُ"},{"id":"P2U8","part":2,"n":8,"sec":{"read":{"t":"مَواقِفُ وَطَرائِفُ","pg":131,"paras":["الأَدَبُ يُغْني عَنِ النَّسَبِ","قالَ أَحَدُهُمْ: كُنْتُ لَيْلَةً جالِساً عِنْدَ بَعْضِ وُلاةِ شُرْطَةِ اللَّيْلِ، فَجيءَ بِرَجُلَيْنِ. فَسَأَلَ الوالي أَحَدَهُما: مَنْ أَبوكَ؟ فَأَجابَ:","أَنا ابْنُ الَّذي لا يُنْزِلُ الدَّهْرُ قِدْرَهُ ... وَإِنْ نَزَلَتْ يَوْماً فَسَوْفَ تَعودُ","تَرى النّاسَ أَفْواجاً عَلى بابِ دارِهِ ... فَمِنْهُمْ قِيامٌ حَوْلَها وَقُعودُ","فَقالَ الوالي: إِنَّ أَباهُ كَريمٌ مِضْيافٌ. ثُمَّ قالَ لِلآخَرِ: مَنْ أَبوكَ؟ فَأَجابَ:","أَنا ابْنُ مَنْ دانَتِ الرِّقابُ لَهُ ... ما بَيْنَ مَخْزومِها وَهاشِمِها","خاضِعَةٌ أَذْعَنَتْ لِطاعَتِهِ ... يَأْخُذُ مِنْ مالِها وَمِنْ دَمِها","فَقالَ الوالي: ما أَبوهُ إِلّا شُجاعٌ مِقْدامٌ. ثُمَّ عَفا عَنْهُما، وَلَمّا انْصَرَفا، قُلْتُ لِلوالي: أَمّا الأَوَّلُ فَكانَ أَبوهُ فَوّالاً، وَأَمّا الثّاني فَكانَ أَبوهُ حَجّاماً. عِنْدَئِذٍ قالَ الوالي:","كُنِ ابْنَ مَنْ شِئْتَ وَاكْتَسِبْ أَدَباً ... يُغْنيكَ مَحْمودُهُ عَنِ النَّسَبِ","إِنَّ الفَتى مَنْ يَقولُ ها أَنَذا ... لَيْسَ الفَتى مَنْ يَقولُ كانَ أَبي","(طَرائِفُ عَرَبِيَّةٌ - مَجَلَّةُ صَدى الإِلِكْتْرونِيَّةِ)","الأَحْمَقانِ","حُكِيَ أَنَّ أَحْمَقَيْنِ اصْطَحَبا في طَريقٍ، فَقالَ أَحَدُهُما لِلآخَرِ: تَعالَ نَتَمَنَّ، فَإِنَّ الطَّريقَ تُقْطَعُ بِالحَديثِ. قالَ أَحَدُهُما: أَتَمَنّى قَطيعَ غَنَمٍ أَنْتَفِعُ بِلَبَنِها وَلَحْمِها وَصوفِها. وَقالَ الآخَرُ: أَتَمَنّى قَطيعَ ذِئابٍ أُرْسِلُها عَلى غَنَمِكَ حَتّى لا تَتْرُكَ مِنْها شَيْئاً. قالَ: وَيْحَكَ! أَهذا مِنْ حَقِّ الصُّحْبَةِ وَحُرْمَةِ العِشْرَةِ؟ فَتَصايَحا وَتَخاصَما، وَاشْتَدَّتِ الخُصومَةُ بَيْنَهُما حَتّى تَماسَكا بِالأَطْواقِ، ثُمَّ تَراضَيا أَنَّ أَوَّلَ مَنْ يَطْلُعُ عَلَيْهِما يَكونُ حَكَماً بَيْنَهُما، فَطَلَعَ عَلَيْهِما رَجُلٌ بِحِمارٍ عَلَيْهِ زِقّانِ مِنَ العَسَلِ، فَحَدَّثاهُ بِحَديثِهِما، فَنَزَلَ بِالزِّقَّيْنِ، وَفَتَحَهُما حَتّى سالَ العَسَلُ عَلى التُّرابِ، وَقالَ: صَبَّ اللّهُ دَمي مِثْلَ هذا العَسَلِ إِنْ لَمْ تَكونا أَحْمَقَيْنِ.","(قِصَصُ العَرَبِ، إِبراهيم شمس الدين)","إِمامُ البُخَلاءِ","زَعَموا أَنَّ رَجُلاً قَدْ بَلَغَ في البُخْلِ غايَتَهُ، وَصارَ إِماماً فيهِ، وَأَنَّهُ كانَ إِذا صارَ في يَدِهِ الدِّرْهَمُ، خاطَبَهُ وَناجاهُ وَفَدّاهُ وَاسْتَبْطَنَهُ، وَكانَ مِمّا يَقولُ لَهُ: \"كَمْ مِنْ أَرْضٍ قَدْ قَطَعْتَ، وَكَمْ مِنْ كيسٍ قَدْ فارَقْتَ، وَكَمْ مِنْ خامِلٍ رَفَعْتَ، وَمِنْ رَفيعٍ قَدْ أَخْمَلْتَ. لَكَ عِنْدي أَلّا تَعْرى وَأَلّا تَراكَ شَمْسٌ\"، ثُمَّ يُلْقيهِ في كيسِهِ، وَيَقولُ: \"اسْكُنْ عَلى اسْمِ اللّهِ في مَكانٍ لا تُهانُ وَلا تُذَلُّ فيهِ وَلا تُزْعَجُ مِنْهُ\". وَإِنَّهُ لَمْ يُدْخِلْ فيهِ دِرْهَماً قَطُّ فَيُخْرِجُهُ، وَأَنَّ أَهْلَهُ أَلَحّوا عَلَيْهِ في شَهْوَةِ طَعامٍ، وَأَكْثَروا عَلَيْهِ في إِنْفاقِ دِرْهَمٍ، فَماطَلَهُمْ ما أَمْكَنَ ذلِكَ. ثُمَّ حَمَلَ دِرْهَماً فَقَطْ، فَبَيْنَما هُوَ ذاهِبٌ إِذْ رَأى حَوّاءً قَدْ أَرْسَلَ عَلى نَفْسِهِ أَفْعى لِدِرْهَمٍ يَأْخُذُهُ، فَقالَ في نَفْسِهِ: أَأُتْلِفُ شَيْئاً تُبْذَلُ فيهِ النَّفْسُ بِأَكْلَةٍ أَوْ شَرْبَةٍ؟ وَاللّهِ ما هذا إِلّا مَوْعِظَةٌ لي مِنَ اللّهِ. فَرَجَعَ إِلى أَهْلِهِ وَرَدَّ الدِّرْهَمَ إِلى كيسِهِ. فَكانَ أَهْلُهُ مِنْهُ في بَلاءٍ، وَكانوا يَتَمَنَّوْنَ مَوْتَهُ وَالخَلاصَ مِنْهُ، وَالحَياةَ بِدونِهِ. فَلَمّا ماتَ، وَظَنّوا أَنَّهُمْ قَدِ اسْتَراحوا مِنْهُ، قَدِمَ ابْنُهُ فَاسْتَوْلى عَلى مالِهِ وَدارِهِ، ثُمَّ قالَ: \"ما كانَ إِدامُ أَبي؟ فَإِنَّ أَكْثَرَ البَذْلِ إِنَّما يَكونُ في الإِدامِ\". قالوا: \"كانَ يَتَأَدَّمُ بِجُبْنَةٍ عِنْدَهُ\"، قالَ: \"أَرونيها\"، فَإِذا فيها حَزٌّ كَالجَدْوَلِ مِنْ أَثَرِ مَسْحِ اللُّقْمَةِ. قالَ: \"ما هذِهِ الحُفْرَةُ؟\" قالوا: \"كانَ لا يَقْطَعُ الجُبْنَ، وَإِنَّما كانَ يَمْسَحُ عَلى ظَهْرِهِ، فَيَحْفِرُ كَما تَرى\" قالَ: \"بِهذا أَهْلَكَني، وَبِهذا أَقْعَدَني هذا المَقْعَدَ، لَوْ عَلِمْتُ ذلِكَ ما خَرَجْتُ في جَنازَتِهِ\". قالوا: \"ماذا تُريدُ أَنْ تَصْنَعَ؟\" قالَ: \"أَضَعُها مِنْ بَعيدٍ، فَأُشيرُ عَلَيْها بِاللُّقْمَةِ\".","(قِصَصُ العَرَبِ، إِبراهيم شمس الدين)"],"voc":[["فَوّالٌ","بائِعُ فولٍ."],["حَجّامٌ","مَنْ يَقومُ بإخْراجِ الدَّمِ الزّائِدِ في الجِسْمِ بِالمِحْجَمِ أو المِشْرَطِ، وَيُقْصَدُ بِها هُنا الحَلّاقُ."],["قَطيعٌ","طائِفَةٌ مِن الغَنَمِ أوِ الجِمالِ أوِ البَقَرِ أوِ سِواها، وَالجَمْعُ قُطْعانٌ."],["الأطْواقُ","كُلُّ مُسْتَديرٍ يُحيطُ بِالعُنُقِ، وَالمُفْرَدُ: الطَّوْقُ."],["الزِّقُّ","وِعاءٌ مِنْ جِلْدٍ يُمْلَأ بِالماءِ أوِ اللَّبَنِ وَنَحْوِها."],["استَبْطَنَهُ","أخْفاهُ."],["خامِلٌ","لا نَباهَةَ لَهُ."],["حَوّاءٌ","جامِعُ الحَيّاتِ."]],"img":[["p2-131.webp",131],["p2-132.webp",132],["p2-133.webp",133],["p2-134.webp",134],["p2-135.webp",135]]},"grammar":{"t":"تَدْريباتٌ عَلى إِنَّ وَأخَواتِها","pg":136,"pts":["تدريبات على إنّ وأخواتها."],"img":[["p2-136.webp",136]],"q":[["«كأنّ الطّرفةَ دواءٌ»: «دواءٌ»:",["خبر كأنّ مرفوع","اسم كأنّ","مفعول به","حال"],0,""],["معنى «لكنّ»:",["الاستدراك","التّمنّي","التّرجّي","التّشبيه"],0,""]]},"imla":{"t":"تَدْريباتٌ - مُراجَعَةٌ عامَّةٌ","pg":137,"pts":["مراجعة عامّة."],"img":[["p2-137.webp",137]]},"khatt":{"t":"الخَطُّ","pg":139,"pts":["كتابة عبارة."],"img":[["p2-139.webp",139]]},"taabir":{"t":"تَدْريبٌ عَلى الرِّسالَةِ الإِخْوانِيَّةِ","pg":140,"pts":["تدريب على الرّسالة الإخوانيّة."],"img":[]}},"listen":"أدَبُ الفُكاهَةِ"}];
